window.PEOPLE = {"dublin":{"zh":"都柏林","en":"Dublin","ll":[-6.2603,53.3498],"r_km":25,"start":["seamus","lin"],"order":["seamus","dessie","andrei","lucas","kasia","lin","bridget","ciara","darragh","aoife"],"clip":{"src":"https://img.heyvoyo.com/clips/social_money_rentcap_2.mp4","poster":"https://img.heyvoyo.com/clips/social_money_rentcap_2.webp","where":"英国 · 一排排连栋房子（不是在都柏林拍的）","by":"Altaf Shah","url":"https://www.pexels.com/video/35745979/"},"people":{"seamus":{"nm":"Séamus","av":"👨🏻‍🦳","job":"自由区（The Liberties）一家老酒馆的老板 · 64 岁","x":60,"y":50,"now":[["Quiet in here before six. I'm polishing glasses and waiting for the regulars.","六点前店里很安静。我一边擦杯子，一边等熟客来。"],["It rained all week, so the place was packed. Nobody wanted to go home!","下了一整周的雨，店里反倒坐满了。谁都不想回家！"],["A tourist asked me where to find a real Irish pub. I said, \"You're standing in one.\"","有个游客问我哪儿有真正的爱尔兰酒馆。我说：「你现在就站在一家里。」"],["My son wants to put a big telly in for the football. We're still arguing about it.","我儿子想在店里装个大电视看球。我们俩还在为这事争。"]],"story":"这家酒馆是他爷爷开的，他十四岁就在吧台后面帮忙。店里从来不放电视，他说酒馆是让人说话的地方。有一年冬天下大雪，一群回不了酒店的游客在这儿唱了一整晚的歌，到现在每年还给他寄圣诞卡。","ties":{"dessie":"从小在自由区一起长大的老朋友","aoife":"每周二晚上在他的酒馆里拉琴","lucas":"他每天早上去 Lucas 的咖啡摊买咖啡"},"next":"dessie","chat":[{"npc":["Come in out of the rain! What can I get you?","快进来躲躲雨！喝点什么？"]},{"me":[["Just a cup of tea, please.","来杯茶就好，谢谢。"],["What's good here?","这儿什么好喝？"]]},{"npc":["Well, the Guinness is good, but a cup of tea is grand too. This pub was my grandad's, you know. No telly, just people talking.","健力士是不错，不过来杯茶也挺好。这酒馆是我爷爷开的，知道吧。不放电视，就是让人聊天的地方。"]},{"me":[["Why no TV?","为什么不放电视？"],["Have you always lived around here?","你一直住在这一带吗？"]]},{"npc":["I've spent my whole life around here, and a pub is for talking, not telly! My oldest friend Dessie grew up two streets away. He drives a taxi now. Get in his car and he'll tell you the whole history of Dublin!","我这辈子都在这一带，酒馆是让人说话的，不是看电视的！我最老的朋友 Dessie 就在隔两条街长大。他现在开出租车。坐上他的车，他能把都柏林的历史从头讲给你听！"]}],"clip":{"src":"https://img.heyvoyo.com/clips/eat_well_time_2.mp4","poster":"https://img.heyvoyo.com/clips/eat_well_time_2.webp","where":"伦敦 · 一家老派酒吧，傍晚","why":"他在都柏林开的酒馆，就是这种老派酒吧","by":"Florian Delée","url":"https://www.pexels.com/video/37661399/"},"face":{"s":1,"h":"thin","hc":"white","t":"shirt","tc":"#f2f2f2","b":"mous","a":["pen"],"o":1,"e":"calm","bg":"#e6ecdc","bgs":"pub","prop":"pint"}},"dessie":{"nm":"Dessie","av":"🧔🏻","job":"开了快三十年出租车的老都柏林人 · 58 岁","x":170,"y":40,"now":[["Night shift again. Stopped at the petrol station for diesel and a breakfast roll.","又是夜班。去加油站加了柴油，顺手买了个夹香肠培根的面包卷。"],["The airport was mad busy all week. Everyone's flying somewhere.","这周机场忙疯了，好像人人都要飞去哪儿。"],["Thinking about getting an electric car. My wallet says yes, my heart says no.","在想要不要换辆电动车。算账觉得该换，心里又舍不得。"],["Drove Bridget to the hospital for her check-up. She talked the whole way, God love her.","开车送 Bridget 去医院复查。她一路说个不停，这老太太真可爱。"]],"story":"年轻时想当历史老师，没考上大学，就开起了出租车。车里放着一本旧笔记本，记着这些年乘客讲给他的故事。他说：都柏林真正的历史不在博物馆里，在他的后座上。","ties":{"seamus":"从小一起长大的老朋友","andrei":"他的理发师","bridget":"他妈妈的老朋友，他常开车送她去医院"},"next":"andrei","chat":[{"npc":["Séamus sent you? Hop in. Where are we off to?","Séamus 让你来的？上车吧。去哪儿？"]},{"me":[["To the city centre, please.","去市中心，谢谢。"],["Anywhere you like. Show me your Dublin!","去哪儿都行。带我看看你的都柏林！"]]},{"npc":["No bother. See that bridge? My granny sold flowers there for forty years. Every street here has a story.","没问题。看见那座桥了吗？我奶奶在那儿卖了四十年花。这儿每条街都有故事。"]},{"me":[["Do you like driving a taxi?","你喜欢开出租车吗？"],["What's the best part of the job?","这份工作最好的地方是什么？"]]},{"npc":["I love it, and the best part is the people! Every kind of person gets into this car. Oh, and I need a haircut. My barber Andrei is from Romania, a sound lad. Tell him Dessie sent you.","喜欢啊，最好的就是能见到各种人！什么样的人都坐过我的车。哦对了，我该剪头了。我的理发师 Andrei 是罗马尼亚来的，人特别好。跟他说是 Dessie 介绍的。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/economy_club_fuel_2.mp4","poster":"https://img.heyvoyo.com/clips/economy_club_fuel_2.webp","where":"英国 · 夜里路边的加油站（航拍）","why":"他夜里出车，常在这种路边加油站停一下","by":"David Pickup","url":"https://www.pexels.com/video/29352648/"},"face":{"s":2,"h":"short","hc":"salt","t":"jumper","tc":"#3c5a4a","b":"full","o":1,"e":"calm","bgs":"doors","prop":"wheel"}},"andrei":{"nm":"Andrei","av":"👨🏻","job":"菲布斯伯勒（Phibsborough）的理发师，罗马尼亚人 · 30 岁","x":280,"y":60,"now":[["Saturday morning, and there's already a queue at the door. Everyone wants a fade.","周六上午，门口已经排上队了。人人都要剪渐变发型。"],["My mum is visiting from Romania. She thinks Dublin is too expensive and too wet.","我妈从罗马尼亚来看我。她觉得都柏林又贵又潮。"],["Took Mum to the sea at Howth. It rained, of course, but she loved the fish and chips.","带我妈去霍斯看海。当然又下雨了，不过她特别爱吃那儿的炸鱼薯条。"],["Mum flew home and left a huge cake. I gave half to Ciara next door.","我妈飞回去了，留下一个大蛋糕。我分了一半给隔壁的 Ciara。"]],"story":"刚来都柏林时他在建筑工地干活，英语全是在工地上学的，一开口就是满嘴的爱尔兰俚语。后来攒钱学了理发，开了自己的小店。他最得意的是：店里的老客人现在都会用罗马尼亚语跟他说「谢谢」。","ties":{"dessie":"剪了好几年头的老客人","lucas":"每个月来他这儿剪一次头","ciara":"她的药店就在他理发店隔壁"},"next":"lucas","chat":[{"npc":["Hey, come in! Dessie rang me. He said, \"Be nice, it's a friend.\" I'm always nice!","嘿，进来！Dessie 给我打过电话了。他说「客气点，是朋友」。我哪次不客气了！"]},{"me":[["Can I get a trim, please?","能帮我修一下吗？"],["Just a bit shorter on the sides, please.","两边剪短一点就好。"]]},{"npc":["Sure, no problem. Sit down. So, where are you from? Lots of people in Dublin are from somewhere else, like me.","没问题，坐吧。你是哪儿人？都柏林好多人都是从别处来的，跟我一样。"]},{"me":[["I'm from China. How long have you been here?","我是中国人。你来这儿多久了？"],["Was it hard to start a new life here?","在这儿重新开始难吗？"]]},{"npc":["I've been here ten years. The start was hard, but people help you. Do you know Lucas? Brazilian guy, he makes the best coffee in town. He sits in this chair every month.","我来这儿十年了。刚开始挺难的，但总有人帮你。你认识 Lucas 吗？巴西小伙，城里最好的咖啡就是他做的。他每个月都来我这儿剪头。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/fashion_club_haircut_1.mp4","poster":"https://img.heyvoyo.com/clips/fashion_club_haircut_1.webp","where":"爱尔兰 · 理发店里","why":"他在菲布斯伯勒开的，就是这样的小理发店","by":"Luciann Photography","url":"https://www.pexels.com/video/11440852/"},"face":{"s":2,"h":"side","hc":"black","t":"tee","tc":"#222","b":"stubble","a":["comb"],"bgs":"barber","prop":"scissors"}},"lucas":{"nm":"Lucas","av":"🧑🏽","job":"乔治街拱廊市场里的咖啡师，巴西来的语言学校学生 · 24 岁","x":310,"y":160,"now":[["Early shift at the coffee stall. The market's still empty, just me and the espresso machine.","咖啡摊早班。市场里还没什么人，只有我和咖啡机。"],["Our landlord is selling the house, so we went to see a flat today. Forty people came to see it. Forty!","房东要卖房子，今天我们去看了一套房，来看的有四十个人。四十个！"],["I passed my English exam! My teacher says I sound a bit Irish now.","英语考试过了！老师说我现在说话有点爱尔兰味儿了。"],["Kasia found a flat for both of us! I'm cooking feijoada tonight to say thanks.","Kasia 给我们俩找到房子了！今晚我做巴西黑豆炖肉谢谢她。"]],"story":"在圣保罗学的是建筑，来都柏林是想先把英语练好。第一个月他听不懂客人说的 \"Small black coffee, ta\"，还以为 ta 是个人名，其实是「谢谢」的意思。现在大部分熟客要喝什么，他不用问就知道。","ties":{"kasia":"合租的室友","andrei":"他的理发师","seamus":"每天早上来买咖啡的熟客"},"next":"kasia","chat":[{"npc":["Bom dia! Sorry, good morning! Andrei told me you'd come. Coffee?","Bom dia！不好意思，早上好！Andrei 说你会来。喝咖啡吗？"]},{"me":[["Yes, a flat white, please.","好啊，来杯澳白。"],["What do you recommend?","你推荐什么？"]]},{"npc":["A flat white is always a good idea. Brazilian beans, Irish milk. The best of both worlds! How's your English going?","点澳白总不会错。巴西的豆子，爱尔兰的牛奶，两边最好的都在这杯里了！你英语学得怎么样？"]},{"me":[["Not bad, but the Irish accent is hard!","还行，不过爱尔兰口音好难！"],["I'm still learning. How did you learn?","还在学。你是怎么学的？"]]},{"npc":["Ha, same for me at first! I learned behind this counter, one customer at a time. My flatmate Kasia helped me a lot too. She's Polish and works at a big tech company. She speaks four languages!","哈，我刚开始也一样！我就是在这个柜台后面，一个客人一个客人学出来的。我室友 Kasia 也帮了我很多。她是波兰人，在一家大科技公司上班，会说四种语言！"]}],"clip":{"src":"https://img.heyvoyo.com/clips/body_mind_cafe_0.mp4","poster":"https://img.heyvoyo.com/clips/body_mind_cafe_0.webp","where":"伦敦 · 利德贺老市场（维多利亚式室内市场）","why":"他打工的咖啡摊在都柏林的乔治街拱廊，也是这种维多利亚式的老室内市场","by":"Gül Işık","url":"https://www.pexels.com/video/28988754/"},"face":{"s":3,"h":"curly","hc":"dbrown","t":"apron","tc":"#5a3b28","t2":"#e6e0d0","e":"grin","bg":"#fdebd2","bgs":"cafe","prop":"coffee"}},"kasia":{"nm":"Kasia","av":"👩🏼‍💻","job":"码头区一家大科技公司的用户支持组长，波兰人 · 32 岁","x":280,"y":270,"now":[["Quick coffee outside with the team. Five minutes of fresh air, then back to meetings.","跟组里的人出来喝杯咖啡。透五分钟气，再回去开会。"],["Our landlord is selling the house. Lucas and I have to find a new place. Again.","房东要卖房子。我和 Lucas 又得找新住处了。又要折腾一回。"],["Saw a two-bed flat in Drumcondra. The kitchen is tiny, but the light is lovely.","在德拉姆康德拉看了一套两居室。厨房很小，不过采光特别好。"],["We got the flat! Lucas cooked feijoada to celebrate. I'm still full.","房子租到了！Lucas 做了巴西黑豆炖肉庆祝。我到现在还撑着。"]],"story":"她刚来时在呼叫中心接电话，常常一天被骂好几回。现在她带一个十人的团队，定的第一条规矩是：碰到生气的用户，先说一句 \"That sounds really frustrating.\"。周六早上她雷打不动去凤凰公园跑步，下雨也去。","ties":{"lucas":"合租的室友","lin":"每周六早上一起在凤凰公园跑步"},"next":"lin","chat":[{"npc":["Hi! You're Lucas's friend? Sorry, I've only got ten minutes. Meetings all day.","嗨！你是 Lucas 的朋友？不好意思，我只有十分钟，一整天都在开会。"]},{"me":[["No problem. What do you do at work?","没事。你工作是做什么的？"],["Ten minutes is fine. Busy day?","十分钟够了。今天很忙？"]]},{"npc":["Busy as always! I run a support team. When people are angry about their accounts, they talk to us. My job is to stay calm.","一直这么忙！我带一个用户支持团队。用户账号出了问题，很生气，就来找我们。我的工作就是保持冷静。"]},{"me":[["How do you stay calm?","你怎么保持冷静？"],["What do you do after work?","下班以后你做什么？"]]},{"npc":["Running! Every Saturday morning I do parkrun in the Phoenix Park. Lin, a Chinese student, runs with me. She's faster than me, to be honest.","跑步！每周六早上我都去凤凰公园参加 parkrun 晨跑。有个中国留学生 Lin 跟我一起跑。说实话，她比我快。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/eat_well_lunch_2.mp4","poster":"https://img.heyvoyo.com/clips/eat_well_lunch_2.webp","where":"英国 · 写字楼外，同事们拿着咖啡出来歇一会儿","why":"她在都柏林码头区上班，午休也常这样拿杯咖啡出来走走","by":"August de Richelieu","url":"https://www.pexels.com/video/4480972/"},"face":{"s":1,"h":"long","hc":"blonde","t":"blazer","tc":"#3a4a5a","t2":"#fff","a":["headset","badge"],"e":"calm","bgs":"office","prop":"laptop"}},"lin":{"nm":"Lin","av":"👩🏻‍🎓","job":"在圣三一学院读计算机硕士的中国留学生 · 23 岁","x":170,"y":290,"now":[["Saturday morning run in the Phoenix Park. I saw the deer again! And I beat Kasia, ha.","周六早上去凤凰公园跑步。又看见鹿了！还跑赢了 Kasia，哈。"],["Group project week. My teammates say \"grand\" about everything, even when nothing is grand.","这周赶小组作业。组员什么事都说 grand（挺好），其实一点都不好。"],["Bridget taught me to make brown bread. Mine looks like a brick.","Bridget 教我烤苏打面包。我烤的像块砖。"],["I played the tin whistle at Séamus's pub for the first time. My hands were shaking!","第一次在 Séamus 的酒馆里吹锡哨。手一直在抖！"]],"story":"刚来都柏林时找不到房子，在青旅住了一个多月，差点想回国。最后是在超市门口的布告栏上，看到了 Bridget 手写的招租卡片。现在每天晚上两个人一起看电视上的答题节目，Bridget 每道题都抢着答。","ties":{"kasia":"每周六一起跑步","bridget":"她的房东，现在像奶奶一样","aoife":"教她吹锡哨"},"next":"bridget","chat":[{"npc":["Oh, hi! Kasia told me about you. Are you a student here too?","哦，你好！Kasia 跟我说起过你。你也是来这儿读书的吗？"]},{"me":[["Yes, I'm studying English.","对，我在学英语。"],["No, I'm just visiting. Do you like Dublin?","不是，我只是来玩。你喜欢都柏林吗？"]]},{"npc":["Dublin is lovely, but it rains a lot! I study computer science at Trinity. The hardest part isn't the coding. It's the accent!","都柏林挺好的，就是老下雨！我在圣三一学院读计算机。最难的不是写代码，是听懂口音！"]},{"me":[["Me too! Can you understand people now?","我也是！你现在能听懂了吗？"],["Where do you live?","你住在哪儿？"]]},{"npc":["I rent a room in Bridget's house, near here. She's seventy-nine, and she's my best friend here! We chat every evening, so now I understand much more.","我租的是 Bridget 家的一个房间，就在这附近。她七十九岁了，是我在这儿最好的朋友！我们每天晚上都聊天，所以现在我能听懂的多多了。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/growth_club_run_2.mp4","poster":"https://img.heyvoyo.com/clips/growth_club_run_2.webp","where":"伦敦 Ealing · 公园里跑步","why":"她每周六早上在凤凰公园跑步，就是这样的公园晨跑","by":"George Morina","url":"https://www.pexels.com/video/4187430/"},"face":{"s":2,"h":"long","hc":"black","t":"hoodie","tc":"#3e6fb0","a":["rglasses"],"ac":{"rglasses":"#333"},"bgs":"campus","prop":"book"}},"bridget":{"nm":"Bridget","av":"👵🏻","job":"住在菲布斯伯勒的退休老太太，以前在邮局上班 · 79 岁","x":225,"y":180,"now":[["Out with the dog every morning, rain or shine. He has to say hello to every dog in the park.","每天早上都带狗出门，刮风下雨都去。公园里的狗它每只都要去打个招呼。"],["My knee is at me again. Ciara at the chemist gave me something for it.","膝盖又疼起来了。药店的 Ciara 给我拿了点药。"],["Lin made her first brown bread. I told her it was lovely. It was not.","Lin 第一次烤苏打面包。我跟她说很好吃，其实不怎么样。"],["Dessie drove me to the hospital for my check-up. All clear, thanks be to God.","Dessie 开车送我去医院复查。一切正常，谢天谢地。"]],"story":"老伴走了以后，她一个人在这栋房子里住了三年，安静得吓人。是药店的 Ciara 劝她把空房间租出去。现在 Lin 住进来了，她说自己又多了个孙女，还是会写代码的那种。","ties":{"lin":"住在她家的房客","dessie":"老朋友的儿子，常开车送她去医院","ciara":"她常去的那家药店的药剂师"},"next":"ciara","chat":[{"npc":["You're Lin's friend! Come in, come in, the kettle's on.","你是 Lin 的朋友！快进来，水已经烧上了。"]},{"me":[["Thank you! What a lovely house.","谢谢！这房子真好。"],["Thanks. Lin talks about you a lot.","谢谢。Lin 常常说起您。"]]},{"npc":["Ah, stop. I've lived here for fifty years. It was very quiet before Lin came. Now there's always someone to talk to.","哎呀，哪里哪里。我在这儿住了五十年了。Lin 来之前家里特别安静，现在总有人陪我说话。"]},{"me":[["How did you meet Lin?","您是怎么认识 Lin 的？"],["Do you go out much?","您常出门吗？"]]},{"npc":["Well, I'm at the chemist most days, and that's how Lin came, really! Ciara there told me to rent out the room. She's a dote. Go and see her. The chemist's next to the barber's.","我几乎天天去药店，Lin 能住进来，说起来也是因为这个！是药店的 Ciara 劝我把房间租出去的。她可贴心了。去找她吧，药店就在理发店隔壁。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/pet_club_walk_1.mp4","poster":"https://img.heyvoyo.com/clips/pet_club_walk_1.webp","where":"伦敦 · 伊灵的公园草地","why":"她每天早上带狗去附近公园转一圈，就是这样的草地","by":"George Morina","url":"https://www.pexels.com/video/5201745/"},"face":{"s":1,"h":"bun","hc":"white","t":"cardigan","tc":"#9a6aa0","t2":"#f6efe4","a":["pearls","glasses"],"ac":{"glasses":"#6a4a7a"},"o":1,"bg":"#f3e6ef","bgs":"home","prop":"teacup"}},"ciara":{"nm":"Ciara","av":"👩🏻‍⚕️","job":"菲布斯伯勒一家药店的药剂师 · 41 岁","x":120,"y":170,"now":[["Cold and flu season has started. Half the street is coughing.","感冒季开始了，半条街的人都在咳嗽。"],["Bridget's knee is acting up again. I made her promise to see the doctor.","Bridget 的膝盖又不舒服了。我让她答应一定去看医生。"],["Darragh's team won their first match. He's been smiling for three days.","Darragh 带的队赢了第一场比赛。他已经乐了三天了。"],["Andrei next door brought us some of his mum's cake. The whole pharmacy smells of cinnamon.","隔壁的 Andrei 给我们送来他妈妈做的蛋糕，整个药店都是肉桂味。"]],"story":"在爱尔兰，很多人身体不舒服先来药店，不先去看医生，所以她每天要听很多人讲自己哪儿难受。她说最要紧的不是药，是让人把话说完。有一回她发现一位老太太一周来买了三次止痛药，多问了一句，才知道老太太在家摔了一跤，谁也没告诉。那位老太太就是 Bridget。","ties":{"bridget":"几乎天天来的老顾客","andrei":"隔壁理发店的老板","darragh":"她的对象"},"next":"darragh","chat":[{"npc":["Hello! Bridget rang ahead to say you were coming. She rings about everything!","你好！Bridget 提前打电话说你要来。她什么事都要打个电话说一声！"]},{"me":[["Hi! I've got a sore throat. What can I take?","你好！我嗓子疼，吃点什么好？"],["Hi! Do people here really go to the pharmacy before the doctor?","你好！这儿的人真的先来药店，再去看医生吗？"]]},{"npc":["Sure, lots of people here come to us first. For a sore throat, try these lozenges and drink plenty of water. If you get a high temperature, see a GP.","是啊，这儿很多人不舒服都先来找我们。嗓子疼的话，试试这种含片，多喝水。要是发高烧，就去看家庭医生。"]},{"me":[["Thanks! Do you like your job?","谢谢！你喜欢这份工作吗？"],["You must know everyone around here.","这一带的人你一定都认识吧。"]]},{"npc":["I do! It's like a small village inside a big city. But my partner Darragh knows even more people. He coaches hurling for kids on Saturdays. Go and watch. It's the fastest game on grass!","是啊！这儿就像大城市里的一个小村子。不过我对象 Darragh 认识的人更多。他每周六给小孩当板棍球教练。去看看吧，那可是草地上最快的运动！"]}],"face":{"s":1,"h":"pony","hc":"brown","t":"blazer","tc":"#ffffff","t2":"#7fb3d5","a":["badge"],"ac":{"badge":"#2a8c5a"},"e":"calm","bgs":"pharmacy","prop":"pills"}},"darragh":{"nm":"Darragh","av":"👨🏻","job":"中学体育老师，周末给小孩当板棍球（hurling）教练 · 34 岁","x":40,"y":150,"now":[["Took the kids to a big club match on Sunday. The crowd outside was unreal!","周日带孩子们去看了一场俱乐部的大比赛。球场门口的人多得不得了！"],["Training in the rain again. The kids didn't even notice. Fair play to them.","又在雨里训练。孩子们根本不在乎。真有他们的。"],["Our under-12s won their first match! I nearly cried.","我们十二岁以下的队赢了第一场比赛！我差点哭了。"],["Aoife wants me to play the bodhrán at her session. I can't keep a beat to save my life.","Aoife 想让我周二去酒馆，跟她们一起打爱尔兰手鼓。可我怎么都打不准拍子。"]],"story":"他小时候是全区最有希望的板棍球选手，十九岁那年膝盖受了重伤，再也没能上场比赛。后来他当了老师，把周末都给了别人家的孩子。他说：教会一个孩子摔倒了不怕，比自己赢球开心多了。","ties":{"ciara":"他的对象","aoife":"他妹妹"},"next":"aoife","chat":[{"npc":["Ciara sent you? Grab a hurley, so! Only joking. Stand over there, those balls fly fast.","Ciara 让你来的？那拿根球棍上场吧！开玩笑的。站那边去，球飞得可快了。"]},{"me":[["What is hurling, exactly?","板棍球到底是什么？"],["Wow, the kids are really fast!","哇，这些孩子真快！"]]},{"npc":["It's one of the oldest games in the world. You hit a small ball with a stick called a hurley. These kids are faster than me now!","这是世界上最古老的运动之一。用一根叫 hurley 的木棍打一个小球。这些孩子现在比我还快！"]},{"me":[["Is it dangerous?","危险吗？"],["Do you play too?","你自己也打吗？"]]},{"npc":["I used to, till I hurt my knee. So yes, it can be dangerous! Now I just shout from the side. My sister Aoife got the talent in our family. She plays the fiddle. Go and hear her on Tuesday night at Séamus's pub.","以前打，后来膝盖受了伤。所以没错，是有点危险！现在我就在场边喊。我们家的天分都给了我妹妹 Aoife，她拉小提琴。周二晚上去 Séamus 的酒馆听她拉吧。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/people_values_footballer_2.mp4","poster":"https://img.heyvoyo.com/clips/people_values_footballer_2.webp","where":"英国 · 布莱顿球场门口 · 比赛日","why":"他常带孩子们去看比赛，比赛日的球场门口就是这么热闹","by":"Hassan Ehsan","url":"https://www.pexels.com/video/39239779/"},"face":{"s":1,"h":"crop","hc":"ginger","t":"jersey","tc":"#2e7d4f","t2":"#fff","a":["whistle"],"b":"stubble","e":"grin","bgs":"pitch","prop":"hurley"}},"aoife":{"nm":"Aoife","av":"👩🏻‍🦰","job":"爱尔兰传统音乐的小提琴手，白天教小孩拉琴 · 27 岁","x":60,"y":260,"now":[["Tuesday again! I'll be at the corner pub tonight with my fiddle.","又到周二了！今晚我带着小提琴去街角那家酒馆。"],["One of my students played a whole tune today. She's only seven!","今天有个学生完整拉下来一首曲子。她才七岁！"],["Rain, rain and more rain. Perfect weather for practising at home, I suppose.","雨下个没完。正好待在家里练琴吧。"],["Lin played the tin whistle with us for the first time. She was shaking, but she was brilliant.","Lin 第一次跟我们一起吹锡哨。她紧张得发抖，但吹得特别好。"]],"story":"她奶奶在戈尔韦乡下拉了一辈子琴，从来没上过台，只在自家厨房里拉。奶奶走后留下这把小提琴，琴盒里夹着一张纸，上面是奶奶几十年来记下的曲名。现在 Aoife 每次演出，都从那张纸上挑一首。","ties":{"darragh":"她哥哥","seamus":"每周二晚上在他的酒馆里拉琴","lin":"她教 Lin 吹锡哨"},"next":"seamus","chat":[{"npc":["Darragh said you might come! Grab a seat, we're starting in a minute.","Darragh 说你可能会来！找个位子坐，我们马上开始。"]},{"me":[["Can I just listen?","我能只听吗？"],["What kind of music is this?","这是什么音乐？"]]},{"npc":["It's Irish trad music, and this is a session. Anyone can listen or join in. There's no stage. We just sit around the table and play old tunes together.","这是爱尔兰传统音乐，这种玩法叫 session。谁都可以听，也可以加入。没有舞台，大家围着桌子坐，一起拉老曲子。"]},{"me":[["Who taught you to play?","谁教你拉琴的？"],["Do you play here every week?","你每周都在这儿拉吗？"]]},{"npc":["My granny taught me when I was small, and I've played here every Tuesday for years. Séamus never charges us for tea. Ask him about the snowy night. He tells it better than me.","我小时候是奶奶教的。这些年每周二我都在这儿拉。Séamus 从来不收我们茶钱。去问问他那个下大雪的晚上，他讲得比我好听。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/first_money_split_0.mp4","poster":"https://img.heyvoyo.com/clips/first_money_split_0.webp","where":"伦敦 · 老酒馆招牌","why":"她每周二晚上去拉琴的，就是这种街角的老酒馆","by":"Dominik Gryzbon","url":"https://www.pexels.com/video/35330803/"},"face":{"s":1,"h":"curlylong","hc":"ginger","t":"jumper","tc":"#2f5d50","e":"grin","bg":"#e4f0e6","bgs":"pub","prop":"violin"}}}},"london":{"zh":"伦敦","en":"London","ll":[-0.1276,51.5072],"r_km":45,"start":["precious","fatima"],"order":["precious","tom","kofi","dave","holly","poppy","oliver","harriet","ella","fatima"],"people":{"precious":{"nm":"Precious","av":"👩🏾‍⚕️","job":"NHS 内科病房的夜班护士 · 35 岁","x":60,"y":60,"now":[["Four nights done. Just got on the bus home. I'm sleeping all day!","连上四个夜班，总算完了。刚坐上回家的公交，今天要睡一整天！"],["Back on days this week. Seeing the sun feels a bit weird!","这周换回白班了，天天见到太阳，反而有点不习惯！"],["My mum brought round a big pot of jollof. Best thing after a long shift.","我妈给我送来一大锅 jollof 饭。长长的班上完，吃这个最舒服。"],["Ella's mum popped into the ward today. We hadn't seen each other in years!","Ella 的妈妈今天来病房看我们，我们好多年没见了！"]],"story":"在伦敦当了八年护士。最会在病人情况变差之前看出苗头。夜班下了，最想吃的是一碗妈妈做的 jollof 饭。","ties":{"tom":"同一个病房，常一起上夜班","ella":"Ella 的妈妈是她以前的同事","harriet":"推荐了这个月读书会的书"},"next":"tom","chat":[{"npc":["Hi! Sorry, I'm half asleep. I've just finished a night shift.","嗨！不好意思，我半睡半醒的，刚下夜班。"]},{"me":[["Oh, you must be exhausted. Are you a nurse?","哦，你一定累坏了。你是护士吗？"],["No worries. What do you do?","没事。你是做什么的？"]]},{"npc":["I'm a nurse on a medical ward. Last night we had three new patients after midnight. Honestly, the coffee machine kept me alive.","我是内科病房的护士。昨晚半夜之后来了三个新病人。说真的，全靠咖啡机撑着。"]},{"me":[["How do you sleep during the day?","你白天怎么睡觉？"],["Do you like working nights?","你喜欢上夜班吗？"]]},{"npc":["The hardest bit is sleeping in the day. Blackout curtains and earplugs! Hey, if you want to know about a junior doctor's life, talk to Tom. He's even more tired than me.","最难的是白天睡觉。遮光窗帘加耳塞！对了，你要是想知道年轻医生过的什么日子，去找 Tom 聊聊。他比我还累。"]}],"npc":"precious","clip":{"src":"https://img.heyvoyo.com/clips/body_mind_ward_2.mp4","poster":"https://img.heyvoyo.com/clips/body_mind_ward_2.webp","where":"伦敦 · 早上的双层公交","why":"她下了夜班，坐的就是这样的早班双层公交","by":"George Morina","url":"https://www.pexels.com/video/29554601/"},"face":{"s":5,"h":"braidbun","hc":"black","t":"scrubs","tc":"#2f6db5","a":["fob","tag","ear"],"e":"tired","bgs":"ward","prop":"clipboard"}},"tom":{"nm":"Tom","av":"🧑🏻‍⚕️","job":"NHS 的第三年住院医师 · 28 岁","x":150,"y":40,"now":[["Back on the wards on Monday. Four nights in a row again.","周一又回病房了，又是连上四个夜班。"],["We lost on Sunday. Kofi still hasn't forgiven me for that penalty.","周日我们输了。那个点球，Kofi 到现在还没原谅我。"],["Had to give a family some bad news today. I walked home the long way.","今天得把坏消息告诉一家人。下了班，我绕了好远的路走回家。"],["A whole weekend off! Lie-in, football, then Sunday roast at my mum's.","整个周末都不用上班！睡个懒觉，踢场球，再回我妈家吃周日烤肉。"]],"story":"常常连上四个夜班。参加过医生罢工，跟家里人还为这事吵过。觉得医学英语最难的，是怎么把坏消息说得温柔。","ties":{"precious":"同一个病房的护士","kofi":"周日社区足球队的队友"},"next":"kofi","chat":[{"npc":["Hey! Precious said you'd come and say hi. She says I look tired. She's right.","嘿！Precious 说你会来打招呼。她说我看起来很累，她说得对。"]},{"me":[["Nice to meet you! Busy week?","很高兴认识你！这周很忙吗？"],["Hi Tom. Is being a doctor as hard as people say?","嗨 Tom。当医生真有大家说的那么难吗？"]]},{"npc":["Yeah, it's hard work. The worst part isn't the hours, though. It's telling a family bad news. You never get used to it.","是挺累的。不过最难的不是时间长，是要告诉家属坏消息。永远习惯不了。"]},{"me":[["What do you do to relax?","你怎么放松？"],["That sounds really tough.","听起来真不容易。"]]},{"npc":["Football helps! Every Sunday in Peckham. Our captain is Kofi, the barber. Get a haircut at his shop, and he'll tell you all about the team.","踢球管用！每周日在佩卡姆踢。我们队长是理发师 Kofi。去他店里剪个头，他会把球队的事全告诉你。"]}],"npc":"tomo","clip":{"src":"https://img.heyvoyo.com/clips/med_club_gp_0.mp4","poster":"https://img.heyvoyo.com/clips/med_club_gp_0.webp","where":"伦敦 · 圣托马斯医院（NHS）门口，白天","why":"伦敦的 NHS 大医院门口，他上班的就是这样的医院","by":"Eren Cebeci","url":"https://www.pexels.com/video/18166293/"},"face":{"s":1,"h":"side","hc":"brown","t":"scrubs","tc":"#4a6b8a","a":["steth","tag"],"b":"stubble","e":"calm","bgs":"ward","prop":"xray"}},"kofi":{"nm":"Kofi","av":"👨🏿","job":"佩卡姆的理发师，足球队长 · 38 岁","x":250,"y":60,"now":[["Saturday afternoon, and the shop's packed. Everyone wants a fresh cut for Saturday night.","周六下午，店里挤满了人，人人都想剪个头，晚上好出去玩。"],["Tom came in for a cut. I told him, practise your penalties, mate!","Tom 来剪头了。我跟他说：哥们，点球多练练吧！"],["Cut my son's hair this morning. He actually sat still for once!","今天早上给儿子剪头，他难得一动不动坐住了！"],["Quiet Tuesday. Dave popped in for a trim and moaned about traffic, as usual.","周二人少。Dave 进来修了修头发，照例抱怨了半天路况。"]],"story":"加纳裔，十八岁开始剪头发。店里永远放着足球和非洲节拍。他说：先聊天，再动剪刀。","ties":{"tom":"足球队的队员","dave":"Dave 在他这儿剪了十年头"},"next":"dave","chat":[{"npc":["Come in, come in! Take a seat. First time here?","进来进来！坐。第一次来？"]},{"me":[["Yes, Tom told me about you.","对，Tom 跟我说起过你。"],["Yeah, Tom sent me. Just a trim, please.","对，Tom 让我来的。修一下就好。"]]},{"npc":["Ah, Tom! Did he tell you he missed a penalty on Sunday? No? Typical.","啊，Tom！他有没有跟你说他周日罚丢了点球？没说？就知道。"]},{"me":[["How long have you been cutting hair?","你剪头发多久了？"],["Is this shop always this busy?","店里一直这么忙吗？"]]},{"npc":["Twenty years, and it's always busy. Some customers have been coming for ages, like Dave, the taxi driver. Ten years in this chair! He knows every street in London.","二十年了，店里一直这么忙。有的客人来了好多年，比如开出租车的 Dave，在这张椅子上剪了十年！伦敦每条街他都认识。"]}],"npc":"kofi","clip":{"src":"https://img.heyvoyo.com/clips/fashion_club_haircut_0.mp4","poster":"https://img.heyvoyo.com/clips/fashion_club_haircut_0.webp","where":"伦敦 · 布里克斯顿（佩卡姆隔壁）· 下午","why":"他的理发店在隔壁的佩卡姆，那一带的街就是这样","by":"Eren Cebeci","url":"https://www.pexels.com/video/18212946/"},"face":{"s":6,"h":"crop","hc":"black","t":"tee","tc":"#e2a72e","a":["comb"],"b":"short","e":"grin","bg":"#fde9c8","bgs":"barber","prop":"clippers"}},"dave":{"nm":"Dave","av":"🧔🏻","job":"开了三十年黑色出租车 · 61 岁","x":300,"y":150,"now":[["The roads are a nightmare this week. Roadworks everywhere.","这周路况简直是噩梦，到处在修路。"],["Picked up a lady at Heathrow. She's just moved here from Hong Kong, so I gave her all my tips.","在希思罗机场接了位女士，她刚从香港搬来。我把知道的伦敦窍门全告诉她了。"],["Rain all week. Good for business, bad for my back.","下了一整周的雨。生意是好了，我的腰可受不了。"],["Holly showed me her new short film on her phone. I'm such a proud uncle!","Holly 用手机给我看了她新拍的短片。我这个当叔叔的，骄傲得很！"]],"story":"为了开黑色出租车，花了三年骑着摩托背下整个伦敦的路，那个考试叫 The Knowledge。侄女 Holly 在电影院打工，他最骄傲的就是她。","ties":{"kofi":"他的理发师","holly":"他的侄女"},"next":"holly","chat":[{"npc":["Hiya! Kofi sent you, did he? Hop in.","你好！Kofi 让你来的吧？上车。"]},{"me":[["Yes! He said you know every street in London.","是的！他说你认识伦敦每一条街。"],["Could you take me to Leicester Square?","能送我去莱斯特广场吗？"]]},{"npc":["Course! I know every street in this city. I studied for The Knowledge for three years. Rode around on a little motorbike in the rain.","当然！这城里每条街我都认识。为了考 The Knowledge 学了三年，骑个小摩托在雨里到处转。"]},{"me":[["Three years? That's amazing.","三年？太厉害了。"],["Do you still enjoy driving?","你现在还喜欢开车吗？"]]},{"npc":["Worth every minute. I still love it! If you're ever in Leicester Square, say hi to my niece Holly at the cinema. She'll get you the best seat.","一分钟都没白花，我到现在还喜欢这行！你要是去莱斯特广场，到电影院跟我侄女 Holly 打个招呼，她能给你挑最好的位子。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/dev_club_robotaxi_2.mp4","poster":"https://img.heyvoyo.com/clips/dev_club_robotaxi_2.webp","where":"伦敦 · 街上的黑色出租车","why":"伦敦的黑色出租车，Dave 开的就是这种","by":"Eren Cebeci","url":"https://www.pexels.com/video/18212684/"},"face":{"s":2,"h":"thin","hc":"grey","t":"shirt","tc":"#7d8fa3","b":"full","o":1,"bg":"#e4e4e4","bgs":"taxi","prop":"wheel"}},"holly":{"nm":"Holly","av":"👩🏼","job":"电影院售票员，电影专业学生 · 22 岁","x":290,"y":255,"now":[["Friday night at the cinema. The queue went all the way round the corner!","周五晚上的电影院，排队排到街角去了！"],["Finished filming my short this weekend. Poppy lent me a dress from the seventies.","这周末短片拍完了。Poppy 借了我一条七十年代的裙子。"],["Editing all night, then a shift at the cinema. I'm living on popcorn.","整晚剪片子，第二天还得去电影院上班，天天拿爆米花当饭吃。"],["Showed my film to the class today. Nobody laughed at the wrong bits!","今天在班上放了我的片子。没人在不该笑的地方笑！"]],"story":"白天上电影课，晚上在莱斯特广场的电影院卖票、做爆米花。短片里的戏服全是在 Poppy 的古着摊淘的。","ties":{"dave":"她的叔叔","poppy":"她的戏服都在 Poppy 那儿淘"},"next":"poppy","chat":[{"npc":["Hi! What can I get you? Oh wait, are you the one Uncle Dave told me about?","嗨！要买什么？等等，你就是 Dave 叔叔说的那个人？"]},{"me":[["That's me! He said you'd find me a good seat.","就是我！他说你能给我找个好位子。"],["Yes! Two tickets for the eight o'clock, please.","是的！两张八点的票，谢谢。"]]},{"npc":["Row F, right in the middle. Best seats in the house. I'm a film student, so I take this very seriously.","F 排正中间，全场最好的位子。我学电影的，对这个很认真。"]},{"me":[["What kind of films do you make?","你拍什么样的片子？"],["Do you make your own films?","你自己也拍片吗？"]]},{"npc":["Short ones, with no money! All my costumes come from Poppy's vintage stall on Brick Lane. You should go, she's brilliant.","短的，没钱的！我所有的戏服都是在红砖巷 Poppy 的古着摊淘的。你该去看看，她太厉害了。"]}],"npc":"holly_cine","clip":{"src":"https://img.heyvoyo.com/clips/fun_club_cinema_0.mp4","poster":"https://img.heyvoyo.com/clips/fun_club_cinema_0.webp","where":"伦敦 · 莱斯特广场的电影院，晚上","why":"她打工的莱斯特广场，晚上就是这样","by":"George Morina","url":"https://www.pexels.com/video/2112832/"},"face":{"s":1,"h":"pony","hc":"blonde","t":"polo","tc":"#7a1f2b","a":["tag"],"e":"grin","bg":"#fbe3e8","bgs":"cinema","prop":"popcorn"}},"poppy":{"nm":"Poppy","av":"👩🏻‍🦰","job":"红砖巷市集的古着摊主 · 29 岁","x":190,"y":290,"now":[["Sunday on Brick Lane. I got here at seven to set up the stall.","周日的红砖巷，我七点就来摆摊了。"],["Off to a warehouse in Belgium tomorrow. Fingers crossed for some good denim!","明天去比利时的仓库，希望能淘到好牛仔！"],["Back from Belgium with a van full of jackets. Oliver helped me carry them upstairs.","从比利时拉回满满一车外套，是 Oliver 帮我搬上楼的。"],["Our cat knocked over a whole rail of clothes. Oliver thinks it's funny. I don't.","我们家的猫把一整排衣服都推倒了。Oliver 觉得好笑，我可不觉得。"]],"story":"常去欧洲各地的二手仓库挑衣服，上周刚从比利时淘回四十件牛仔外套，最懂七八十年代的牛仔。跟三个室友合租，其中一个是记者 Oliver，房子是中介 Fatima 帮他们找的。","ties":{"holly":"Holly 的短片戏服都从她这儿来","oliver":"室友","fatima":"帮他们找到现在这套房子"},"next":"oliver","chat":[{"npc":["Hiya! Have a look around. Everything's one of a kind.","嗨！随便看看，每件都是独一份的。"]},{"me":[["Holly said you have the best jackets.","Holly 说你这儿的外套最好。"],["I love this denim jacket!","我好喜欢这件牛仔外套！"]]},{"npc":["Thanks! This denim one's from the seventies. They don't make them like this anymore.","谢谢！这件牛仔的是七十年代的。现在没人这么做衣服了。"]},{"me":[["Where do you find all these clothes?","这些衣服你都是从哪儿找的？"],["Do you live near here?","你住这附近吗？"]]},{"npc":["I buy them in warehouses all over Europe, then fill up my flat round the corner! I share it with three flatmates. One of them, Oliver, writes about money, but he's always broke!","我去欧洲各地的仓库买，再塞满我街角那套房子！我跟三个室友合住。其中一个叫 Oliver，靠写钱的事吃饭，自己却老是没钱！"]}],"npc":"poppy","clip":{"src":"https://img.heyvoyo.com/clips/trends_now_vintage_0.mp4","poster":"https://img.heyvoyo.com/clips/trends_now_vintage_0.webp","where":"伦敦 · 红砖巷街角，上午","why":"她摆摊的红砖巷，上午就是这样","by":"Airam Dato-on","url":"https://www.pexels.com/video/34394920/"},"face":{"s":1,"h":"wavy","hc":"ginger","t":"blazer","tc":"#4f6fa3","t2":"#f1e3c8","a":["hoops","bandana"],"ac":{"bandana":"#e6a23c"},"bg":"#fff0d9","bgs":"rack","prop":"hanger"}},"oliver":{"nm":"Oliver","av":"👨🏼","job":"财经新闻网站的记者 · 26 岁","x":95,"y":255,"now":[["Interest rates again this week. I've written three stories about mortgages.","这周又是利率，我已经写了三篇房贷的稿子。"],["Book club's on Thursday and I'm only halfway through. Don't tell Harriet.","周四就是读书会了，书我才读了一半。别告诉 Harriet。"],["Poppy's van is outside again. Our flat is full of jackets.","Poppy 的小货车又停在门口了，我们家堆满了外套。"],["My editor wants a piece on Christmas spending, so I've been chatting to shoppers on Oxford Street.","主编让我写一篇大家圣诞节花多少钱的稿子，我在牛津街找了好多逛街的人聊。"]],"story":"大学学历史，阴差阳错进了财经新闻，每天把利率、通胀讲给普通人听。每个月去 Harriet 的书店参加读书会。","ties":{"poppy":"室友","harriet":"读书会的常客","fatima":"帮他们找的房子"},"next":"harriet","chat":[{"npc":["Oh hi, you must be Poppy's friend. Sorry, the flat's a mess.","哦嗨，你一定是 Poppy 的朋友。不好意思，屋里乱糟糟的。"]},{"me":[["No problem. Poppy says you're a journalist?","没关系。Poppy 说你是记者？"],["Hi! Nice to meet you.","嗨！很高兴认识你。"]]},{"npc":["I'm a journalist. I write about the economy. Basically, I explain why everything is getting more expensive.","我是记者，写经济新闻。基本上就是解释为什么什么都越来越贵。"]},{"me":[["Is rent very expensive in London?","伦敦的房租很贵吗？"],["What do you do in your free time?","你空闲时做什么？"]]},{"npc":["Well, London's not cheap! But my favourite thing is free: a book club at a little bookshop. Harriet runs it, first Thursday of every month. Come along!","唉，伦敦可不便宜！不过我最喜欢的事不花钱：一家小书店里的读书会。是 Harriet 办的，每个月第一个周四。一起来吧！"]}],"npc":"oliver","clip":{"src":"https://img.heyvoyo.com/clips/first_money_credit_2.mp4","poster":"https://img.heyvoyo.com/clips/first_money_credit_2.webp","where":"伦敦 · 汇丰银行门口","why":"他天天写的银行和利率，就在这样的街上","by":"George Morina","url":"https://www.pexels.com/video/5228150/"},"face":{"s":2,"h":"side","hc":"dbrown","t":"shirt","tc":"#c9d7ea","a":["rglasses"],"e":"calm","bgs":"news","prop":"laptop"}},"harriet":{"nm":"Harriet","av":"👩🏻‍🦳","job":"独立书店店员，读书会主持人 · 52 岁","x":30,"y":170,"now":[["This month's book club: a novel set in Lagos. Precious recommended it!","这个月读书会读一本以拉各斯为背景的小说，是 Precious 推荐的！"],["Book club night. A full room, plenty of wine, and Oliver hadn't finished the book. Again.","读书会那晚坐满了人，酒也没少喝。Oliver 又没读完书。"],["Rainy Saturday. People come in to get dry, and some of them leave with a book.","下雨的周六。大家进来躲雨，有的人走的时候手里多了本书。"],["Picking next month's book. Everyone's got an opinion, of course.","在挑下个月读什么。当然了，人人都有意见。"]],"story":"在一家小书店工作了十五年，每月第一个周四晚上在店里办读书会，大家带酒带饼干来。她说：读书不是比谁读得多，是找到想聊的人。","ties":{"oliver":"读书会常客","ella":"读书会里最年轻的","precious":"推荐了这个月的书"},"next":"ella","chat":[{"npc":["Welcome! Grab a biscuit. Are you here for the book club?","欢迎！拿块饼干。你是来参加读书会的吗？"]},{"me":[["Yes, Oliver invited me.","是的，Oliver 邀请我来的。"],["I'd love to join, but I haven't read the book.","我很想参加，但我还没读那本书。"]]},{"npc":["Lovely! And don't worry if you haven't read the book. Half of us never finish it. We mostly talk about life.","太好了！没读书也别担心，我们一半人都读不完。我们主要是聊生活。"]},{"me":[["How long have you worked here?","你在这儿工作多久了？"],["Do you run the book club every month?","读书会每个月都是你办吗？"]]},{"npc":["I've been here fifteen years, and I've run the book club since the start. Oh, and you should meet Ella. She's our youngest member, and she always organises the pub afterwards.","我在这儿十五年了，读书会从一开始就是我办的。对了，你该认识一下 Ella。她是我们最年轻的成员，散了以后去酒馆都是她张罗。"]}],"npc":"harriet","clip":{"src":"https://img.heyvoyo.com/clips/growth_club_bookclub_0.mp4","poster":"https://img.heyvoyo.com/clips/growth_club_bookclub_0.webp","where":"伦敦 · 晚上的 Foyles 书店门口（查令十字街，离考文特花园很近）","why":"晚上的书店门口，读书会就在这附近","by":"Dominik Gryzbon","url":"https://www.pexels.com/video/35222110/"},"face":{"s":1,"h":"bob","hc":"grey","t":"cardigan","tc":"#7a8b5a","t2":"#f3efe2","a":["glasses"],"ac":{"glasses":"#8a3b3b"},"o":1,"e":"calm","bg":"#efe8d8","bgs":"books","prop":"book"}},"ella":{"nm":"Ella","av":"👱🏻‍♀️","job":"出版社编辑助理，朋友出去玩时管账的那个 · 25 岁","x":120,"y":150,"now":[["Pub after book club as usual. I've already set up the group chat.","读书会完照旧去酒馆，群我已经建好了。"],["Sent everyone the bill from the pub. Only two people have paid me back so far.","把酒馆的账发给大家了，到现在只有两个人还了我钱。"],["Long week at work. I'm proofreading a cookbook, so I'm hungry all the time.","这周上班好累。我在校对一本菜谱，搞得我一直很饿。"],["Mum asked me to say hi to Precious for her. Small world, honestly.","我妈让我替她跟 Precious 问声好。说真的，世界真小。"]],"story":"刚工作两年。每次和朋友出去，都是她打开手机算账。她说：钱算清楚，朋友才做得久。她妈妈以前和 Precious 在同一家医院。","ties":{"harriet":"读书会","precious":"妈妈以前的同事"},"next":"precious","chat":[{"npc":["Hey! Harriet said you're new. Coming to the pub with us after?","嘿！Harriet 说你是新来的。待会儿跟我们去酒馆吗？"]},{"me":[["Sure, I'd love to!","好啊，很想去！"],["Maybe just for one drink.","也许就喝一杯。"]]},{"npc":["Great. Just so you know, we usually split the bill. I'll sort it out on my phone.","太好了。先说一声，我们一般平摊，我用手机算。"]},{"me":[["How do you know everyone here?","你怎么认识这里每个人的？"],["Do you work near here?","你在这附近上班吗？"]]},{"npc":["I work at a publisher, so my whole life is books! That's how I know everyone. And funny thing, my mum used to work with Precious, the nurse. London's a big city, but it's a small world.","我在出版社上班，整个生活都是书！大家就是这么认识的。说来好笑，我妈以前跟护士 Precious 是同事。伦敦是大城市，其实圈子很小。"]}],"npc":"ella_pub","clip":{"src":"https://img.heyvoyo.com/clips/first_money_split_0.mp4","poster":"https://img.heyvoyo.com/clips/first_money_split_0.webp","where":"伦敦 · 老酒馆招牌","why":"读书会散了，大家常去的那种老酒馆","by":"Dominik Gryzbon","url":"https://www.pexels.com/video/35330803/"},"face":{"s":1,"h":"long","hc":"lblonde","t":"jumper","tc":"#e8a0a8","a":["ear"],"ac":{"ear":"#ddd"},"e":"grin","bgs":"office","prop":"phone"}},"fatima":{"nm":"Fatima","av":"🧕🏽","job":"哈克尼的房屋中介 · 34 岁","x":215,"y":160,"now":[["Twenty-five viewings this week. Everyone wants a flat before Christmas.","这周带了二十五次看房。人人都想在圣诞前找到房子。"],["A student from Shanghai signed for her first room in London today. She was so happy!","今天一个上海来的留学生签下了她在伦敦的第一间房，高兴坏了！"],["Poppy sent me another photo of their cat. It's sitting on a pile of jackets.","Poppy 又给我发了她们家猫的照片，猫正坐在一堆外套上。"],["Quick tip for renters: read the whole contract before you sign. Every line!","给租房的人提个醒：签合同前从头读到尾，每一行都别漏！"]],"story":"在伦敦东边做租房中介八年，很多客户是刚来英国的留学生。她总提醒：问清楚押金放在哪个保护计划里、账单包不包。","ties":{"poppy":"给她和室友找的房子","oliver":"给他和室友找的房子"},"next":"poppy","chat":[{"npc":["Hi there! Are you here for the viewing at two?","你好！你是来看两点那套房的吗？"]},{"me":[["Yes, I'm looking for a room near here.","对，我在找这附近的房间。"],["Yes. Are bills included?","是的。账单包含在房租里吗？"]]},{"npc":["Lovely. Bills are included in this one. Always check that! And always ask where your deposit is protected.","好的。这套包账单，这个一定要问清楚！还要问押金放在哪个保护计划里。"]},{"me":[["How long have you been an estate agent?","你做中介多久了？"],["Is it hard to find a flat in London?","在伦敦找房子难吗？"]]},{"npc":["I've done this for eight years. It's always tough, but never impossible. Last year I found a flat for Poppy and Oliver. They still send me photos of their cat!","我干这行八年了。一直都难，但从来不是不可能。去年我给 Poppy 和 Oliver 找了房子，他们到现在还给我发他们家猫的照片！"]}],"npc":"fatima_ag","clip":{"src":"https://img.heyvoyo.com/clips/social_money_rentcap_2.mp4","poster":"https://img.heyvoyo.com/clips/social_money_rentcap_2.webp","where":"英国 · 一排排连栋房子","why":"她每周带人看的，就是这种连栋房子","by":"Altaf Shah","url":"https://www.pexels.com/video/35745979/"},"face":{"s":4,"h":"hijab","hc":"#6a3d7a","t":"blazer","tc":"#2d2d3a","t2":"#e9e2f0","a":["badge"],"e":"calm","bgs":"houses","prop":"keys"}}},"clip":{"src":"https://img.heyvoyo.com/clips/life_abroad_newcity_0.mp4","poster":"https://img.heyvoyo.com/clips/life_abroad_newcity_0.webp","where":"伦敦 · 地铁站的 UNDERGROUND 标牌（样板）","by":"Videogrammer .com","url":"https://www.pexels.com/video/5814581/"}},"manchester":{"zh":"曼彻斯特","en":"Manchester","ll":[-2.2426,53.4808],"r_km":35,"start":["beth","xiaoyu"],"order":["beth","pete","imran","danny","kasia","grace","ollie","sue","xiaoyu","lin"],"clip":{"src":"https://img.heyvoyo.com/clips/life_abroad_gp_0.mp4","poster":"https://img.heyvoyo.com/clips/life_abroad_gp_0.webp","where":"曼彻斯特 · 市中心（中央图书馆）","by":"Mylo Kaye","url":"https://www.pexels.com/video/17229178/"},"people":{"beth":{"nm":"Beth","av":"👩🏼‍💼","job":"社区家庭诊所（GP）的前台 · 45 岁","x":60,"y":60,"now":[["I walk to work past rows of little terraced houses. Someone in nearly every one is our patient!","我走路上班，路过一排排连栋小房子。几乎每栋里都住着我们诊所的病人！"],["Monday morning: 130 phone calls before eleven. A new record, and not a good one.","周一上午，十一点前接了一百三十个电话。破纪录了，可不是什么好事。"],["We've got a new doctor this week. The patients already love her.","这周来了一位新医生，病人们已经很喜欢她了。"],["Flu jab clinic on Saturday. I've booked in over three hundred people!","周六有流感疫苗门诊，我已经给三百多人约上了！"]],"story":"在这家诊所前台做了十五年，最常说的一句是「我们给你回电话」。很多人以为看 GP 要地址证明，不敢来登记——有个刚到的中国留学生发着烧，在门口站了二十分钟才敢进来，那就是晓雨。从那以后，Beth 在窗口贴了张纸：「谁都可以登记，不用任何证明」。","ties":{"pete":"看了三十年的老病人，每周一都打电话来问点事","xiaoyu":"刚来时帮她在诊所登记的留学生","lin":"林姐的妈妈在她们诊所看病，每次来都带蛋挞"},"next":"pete","chat":[{"npc":["Morning! Are you here to register? Don't worry, it's easier than people think.","早上好！你是来登记的吗？别担心，没大家想的那么麻烦。"]},{"me":[["Yes, please. Do I need proof of address?","是的。我需要地址证明吗？"],["Hi, I'm new here. Can I see a doctor?","你好，我刚来。我能看医生吗？"]]},{"npc":["No problem. You don't need any documents. Anyone can register with a GP. Just fill in this form, and we'll ring you back.","没问题。什么证明都不用，谁都可以在 GP 登记。填一下这张表，我们会给你回电话。"]},{"me":[["Thanks! Do you get lots of new people?","谢谢！新来登记的人多吗？"],["Thank you. Is it always this busy?","谢谢。这里一直这么忙吗？"]]},{"npc":["Oh, every day! But we've got our regulars too. See the man at the bus stop outside? That's Pete. He's been our patient for thirty years. Go and say hello, he loves a chat.","哦，天天都是！不过也有老病人。看到门口公交站那位老先生了吗？那是 Pete，在我们这儿看了三十年病。去打个招呼吧，他最爱聊天了。"]}],"npc":"beth_gp","clip":{"src":"https://img.heyvoyo.com/clips/social_money_rentcap_2.mp4","poster":"https://img.heyvoyo.com/clips/social_money_rentcap_2.webp","where":"英国 · 一排排连栋房子（曼彻斯特到处是这种房子）","why":"她每天走路上班，路过的就是这样一排排连栋房子","by":"Altaf Shah","url":"https://www.pexels.com/video/35745979/"},"face":{"s":1,"h":"bob","hc":"brown","t":"cardigan","tc":"#3d6f8f","t2":"#fff","a":["headset","badge"],"e":"calm","bgs":"clinic","prop":"clipboard"}},"pete":{"nm":"Pete","av":"👴🏻","job":"退休邮递员，每天坐 42 路进城 · 74 岁","x":160,"y":35,"now":[["Top deck, front seat again. Best seat on the 42!","又坐在二层最前面。42 路上最好的位子！"],["The 42 was twenty minutes late on Tuesday. In the rain, of course.","周二 42 路晚了二十分钟。当然了，还下着雨。"],["My granddaughter taught me to send voice messages. I've sent her about fifty.","孙女教会我发语音了，我已经给她发了大概五十条。"],["Bought a new winter coat. It took me three shops and two hours.","买了件新冬衣。逛了三家店，花了两个钟头。"]],"story":"当了四十年邮递员，南曼彻斯特每条街、每家的狗他都认识。老伴走了以后，他每天坐 42 路进城，其实没什么事，就是想跟人说说话。他兜里总揣着薄荷糖，碰到看着像迷路的学生，就递过去一颗。","ties":{"beth":"他的 GP 诊所前台，每周一都给她打电话","imran":"每天早上在他店里买报纸，顺便聊半个钟头"},"next":"imran","chat":[{"npc":["Is the forty-two running late again? Oh, Beth sent you, did she? She's a good lass.","42 路又晚点了吗？哦，是 Beth 让你来的吧？那姑娘人好。"]},{"me":[["She did. Are you waiting for the 42 too?","对，是她。你也在等 42 路吗？"],["She did! Where are you off to today?","是她！你今天去哪儿？"]]},{"npc":["I go into town every day, love. I was a postman for forty years. I still like to see the streets.","我天天进城。当了四十年邮递员，还是喜欢到街上转转。"]},{"me":[["Forty years? You must know everyone!","四十年？你肯定谁都认识！"],["Do you miss the job?","你想念那份工作吗？"]]},{"npc":["Ha! I knew everyone, and I miss the people more than the job. Now I chat to Imran at the corner shop every morning. His mum makes the best sweets in Rusholme. Pop in and tell him Pete sent you.","哈！那时候谁都认识。比起那份活儿，我更想那些人。现在我每天早上去街角小店跟 Imran 聊天，他妈妈做的甜点是拉什霍姆最好吃的。去他店里看看，就说是 Pete 让你来的。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/social_money_minwage_2.mp4","poster":"https://img.heyvoyo.com/clips/social_money_minwage_2.webp","where":"伦敦 · 坐公交回家（不是曼彻斯特，但 42 路也是这样的双层公交）","why":"他每天坐的就是这样的双层公交","by":"George Morina","url":"https://www.pexels.com/video/20171788/"},"face":{"s":2,"h":"thin","hc":"white","t":"jumper","tc":"#8a2f2f","b":"mous","o":1,"bg":"#ece6d8","bgs":"bus","prop":"letter"}},"imran":{"nm":"Imran","av":"👨🏽","job":"拉什霍姆一家开了五十年的家庭小店的老板 · 42 岁","x":260,"y":55,"now":[["Lots of people still pay in cash round here. My hand's tired from giving change!","这一带还有很多人付现金。找零找得我手都酸了！"],["Mum made her jalebi this week. All gone in one afternoon.","妈妈这周做了她的 jalebi（一种炸糖圈），一个下午就卖光了。"],["My son wants to work in the shop. I told him: finish school first.","儿子想来店里干活。我跟他说：先把书念完。"],["I fixed the fridge myself. Well, Danny talked me through it on the phone.","冰箱是我自己修好的。好吧，是 Danny 在电话里一步一步教我的。"]],"story":"爷爷七十年代从巴基斯坦来，开了这家小店。Imran 本来在伦敦当会计，爸爸病了才回来接手，以为只干一两年，没想到一干就是十年。他说现在每天最盼着的，是早上听 Pete 讲他送信那些年的事。","ties":{"pete":"每天早上来买报纸的老熟人","danny":"给他店里重新接过线的电工，两个人一起看曼城"},"next":"danny","chat":[{"npc":["Alright? Pete sent you, didn't he? He sends all his new friends to me.","你好啊！是 Pete 让你来的吧？他交了新朋友，都往我这儿领。"]},{"me":[["He did! He says your mum's sweets are the best.","是他！他说你妈妈做的甜点最好吃。"],["Yes. What's good here?","对。这儿有什么好吃的？"]]},{"npc":["Try this one, it's my mum's jalebi. My grandad opened this shop fifty years ago.","尝尝这个，我妈妈做的 jalebi。这家店是我爷爷五十年前开的。"]},{"me":[["Mmm, it's really sweet! Do you like running the shop?","嗯，真甜！你喜欢开店吗？"],["Fifty years! Has the street changed a lot?","五十年！这条街变了很多吧？"]]},{"npc":["I love it. The street's changed a lot, but people still come in for a chat. And at the weekend, it's football. I watch City with Danny, the electrician. He'll be at the match on Saturday. Go and find him!","喜欢。这条街变了很多，但大家还是爱进来聊几句。周末就是看球，我跟电工 Danny 一起看曼城。他周六去现场，去找他吧！"]}],"clip":{"src":"https://img.heyvoyo.com/clips/economy_club_fx_2.mp4","poster":"https://img.heyvoyo.com/clips/economy_club_fx_2.webp","where":"英国 · 手里递过来的英镑","why":"他店里的柜台一天到晚就是这样收钱、找零","by":"Steve B","url":"https://www.pexels.com/video/8208812/"},"face":{"s":4,"h":"short","hc":"black","t":"shirt","tc":"#e8eef5","b":"short","a":["pen"],"e":"calm","bgs":"shop","prop":"newspaper"}},"danny":{"nm":"Danny","av":"👨🏼‍🔧","job":"电工，从小看曼城的季票球迷 · 36 岁","x":315,"y":140,"now":[["Home game on Saturday. I've had a season ticket for twenty-eight years!","周六是主场比赛。我的季票买了二十八年了！"],["I rewired a whole house in Didsbury this week. My back's killing me.","这周给迪兹伯里一整栋房子重新布了线，腰疼死了。"],["Kasia's mum is here from Poland. I'm learning to say 'thank you' in Polish.","Kasia 的妈妈从波兰来了。我在学用波兰语说「谢谢」。"],["Took my nephew to his first match. He cried when we scored!","带外甥去看了他的第一场球。我们进球的时候他哭了！"]],"story":"八岁那年爸爸第一次带他去看曼城，那时候还在老球场 Maine Road，球队成绩很差，常常输。后来搬到了新球场，爸爸前几年也走了，他的季票一年都没断过。旁边那张季票，现在是 Kasia 的——虽然她到现在也没弄懂什么叫越位。","ties":{"imran":"给他店里接过线，周末一起看球","kasia":"他的女朋友","sue":"从小在她的酒吧看球长大，他爸以前是那儿的常客"},"next":"kasia","chat":[{"npc":["Alright, mate! Imran said you'd come. Have you ever been to a match?","嘿，伙计！Imran 说你会来。你去现场看过球吗？"]},{"me":[["No, never! What's it like?","没有，从来没有！现场是什么感觉？"],["Only on TV. Is it loud in there?","只在电视上看过。里面很吵吗？"]]},{"npc":["It's mad! Fifty thousand people singing. I've had a season ticket since I was eight. My dad took me.","疯了一样！五万人一起唱。我八岁起就有季票，是我爸带我去的。"]},{"me":[["That's lovely. Does your family still come?","真好。你家里人现在还来吗？"],["Who do you come with now?","你现在跟谁一起来？"]]},{"npc":["These days it's my girlfriend, Kasia. She doesn't really get football, but she sings the loudest! She works at the big supermarket on the corner. Go and say hi.","现在是跟我女朋友 Kasia 一起。她其实看不太懂足球，但唱得最大声！她在街角那家大超市上班，去跟她打个招呼吧。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/fun_club_football_2.mp4","poster":"https://img.heyvoyo.com/clips/fun_club_football_2.webp","where":"曼彻斯特 · 伊蒂哈德球场","why":"他每个主场都来的伊蒂哈德球场","by":"David Pickup","url":"https://www.pexels.com/video/28164728/"},"face":{"s":2,"h":"crop","hc":"brown","t":"jersey","tc":"#6cabdd","t2":"#1c2c5b","b":"stubble","e":"grin","bgs":"stadium","prop":"screwdriver"}},"kasia":{"nm":"Kasia","av":"👱🏼‍♀️","job":"大超市的值班经理，波兰人 · 33 岁","x":300,"y":240,"now":[["The self-checkouts broke again. I said 'Sorry, love' about a hundred times.","自助收银机又坏了。我大概说了一百遍「不好意思啊」。"],["I made the staff rota for Christmas. Nobody's happy, so it must be fair!","排好了圣诞节的班。谁都不满意，那应该就是公平的！"],["Mum's here from Kraków. She thinks Manchester is too rainy. She's right.","我妈从克拉科夫过来了。她觉得曼彻斯特雨太多。她说得没错。"],["Parkrun with Grace on Saturday. My best time this year!","周六跟 Grace 去公园跑，跑出了今年最好的成绩！"]],"story":"在波兰大学学的是数学，本来要当老师。二十岁来曼彻斯特，只打算打一个暑假的工，结果一待就是十三年。现在店里三十个人的班都是她排的，同事说这是数学老师的本事。","ties":{"danny":"她的男朋友","grace":"每周六一起参加公园跑的跑友"},"next":"grace","chat":[{"npc":["Hiya! Danny texted me about you. Did he talk about football the whole time?","嗨！Danny 给我发消息说起你了。他是不是一直在聊足球？"]},{"me":[["Ha, yes, the whole time!","哈，对，一直在聊！"],["A bit! He says you sing the loudest.","聊了一些！他说你唱得最大声。"]]},{"npc":["Typical Danny! I don't understand the rules, but I love the singing. I came from Poland thirteen years ago, and the songs helped my English!","Danny 就这样！我不懂规则，就是喜欢唱。我十三年前从波兰来，那些歌还帮我学了英语呢！"]},{"me":[["Really? That's a great way to learn!","真的？这个学法真不错！"],["Songs help me with English too!","我也是靠唱歌学英语的！"]]},{"npc":["Honestly, it works! But songs aren't enough. You need friends too. On Saturdays I run in the park with Grace. She knows everyone. Come along and meet her!","说真的，挺管用！不过光靠唱歌不够，还得有朋友。我每周六跟 Grace 在公园跑步，她谁都认识。一起来认识她吧！"]}],"clip":{"src":"https://img.heyvoyo.com/clips/life_abroad_grocery_2.mp4","poster":"https://img.heyvoyo.com/clips/life_abroad_grocery_2.webp","where":"加拿大 · 哈利法克斯的一家超市（不是在曼彻斯特拍的）","why":"她上班的就是这样的超市收银区","by":"Max Medyk","url":"https://www.pexels.com/video/7457422/"},"face":{"s":1,"h":"pony","hc":"lblonde","t":"polo","tc":"#2e7d5b","a":["badge"],"ac":{"badge":"#2e7d5b"},"bgs":"supermarket","prop":"scanner"}},"grace":{"nm":"Grace","av":"👩🏾","job":"曼彻斯特电车（Metrolink）的客服，周六公园跑志愿者 · 29 岁","x":210,"y":290,"now":[["Parkrun on Saturday. Five kilometres round the lake, two hundred runners, and no rain!","周六的公园跑，绕着湖五公里，两百个人一起跑，还没下雨！"],["Someone left a wedding ring on a tram this week. She cried when we gave it back.","这周有人把婚戒落在电车上了。我们还给她的时候，她哭了。"],["Busy week at work. So many people asking which tram goes to the airport.","这周上班好忙，好多人问去机场坐哪趟电车。"],["Mum sent me a box of Nigerian snacks. I shared them at work. Big mistake, they're all gone!","妈妈给我寄了一箱尼日利亚零食。我带到单位分了——失策，全没了！"]],"story":"上班时她帮得最多的，是迷路的人和丢东西的人。有一次一个小伙子上班第一天就把手机落在电车上，急得快哭了，她打了一圈电话，最后在终点站找到了——那就是 Ollie。现在 Ollie 每周六都来跑步，说是来「还人情」。","ties":{"kasia":"每周六一起跑步的跑友","ollie":"帮他找回过手机，后来成了朋友"},"next":"ollie","chat":[{"npc":["Hiya! You're Kasia's friend, right? Ready to run?","嗨！你是 Kasia 的朋友吧？准备好跑了吗？"]},{"me":[["I think so! Is it far?","应该吧！远吗？"],["Not really. I'm not very fast!","不太行，我跑得不快！"]]},{"npc":["It's five K, but don't worry. Lots of people walk it. It's not a race, it's just for fun!","五公里，不过别担心，很多人是走完的。这不是比赛，就是图个开心！"]},{"me":[["That's great. Do you run every week?","太好了。你每周都跑吗？"],["Good! What do you do in the week?","那就好！你平时做什么工作？"]]},{"npc":["I'm here every Saturday. And in the week, I help people on the trams. Lost phones, lost people... Ask Ollie, I found his phone once! He's over there, the tall one in the orange hat. Go and say hi.","我每周六都来！平时我在电车上帮人。丢手机的、迷路的……不信问 Ollie，我帮他找回过手机！他在那边，戴橙色帽子的那个高个子。去打个招呼吧。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/body_mind_park_0.mp4","poster":"https://img.heyvoyo.com/clips/body_mind_park_0.webp","where":"利兹 · 朗德海公园的湖（曼彻斯特往东一小时）","why":"她周六带跑的公园，也是这样绕着一个湖跑","by":"David Pickup","url":"https://www.pexels.com/video/26977462/"},"face":{"s":5,"h":"curlylong","hc":"black","t":"uniform","tc":"#2a3f6b","t2":"#f2d33a","a":["badge","ear"],"e":"grin","bgs":"tram","prop":"phone"}},"ollie":{"nm":"Ollie","av":"🧑🏼","job":"索尔福德媒体城的播客制作助理 · 27 岁","x":110,"y":285,"now":[["Lunch break outside at MediaCity. Ten minutes of sun, then back to my desk.","在媒体城出来午休。晒十分钟太阳，就得回工位了。"],["We recorded a podcast with a famous chef. I was so nervous I forgot his name!","我们跟一位有名的大厨录了一期播客。我紧张得把他名字都忘了！"],["I ran the whole parkrun without walking! Grace gave me a high five.","公园跑我第一次一步没走跑完了！Grace 跟我击了个掌。"],["Helped Mum at the pub on Tuesday. I read out the quiz questions. Half of them are going in our podcast!","周二去妈妈的酒吧帮忙，题是我念的。有一半要放进我们的播客！"]],"story":"在妈妈的酒吧楼上长大，小时候每周二晚上都趴在楼梯上偷听知识竞赛的题。现在他在媒体城做一档知识问答播客——同事都不知道，节目里一半的题是从妈妈那儿「借」来的。","ties":{"grace":"帮他找回过手机，现在每周六一起跑步","sue":"他妈妈"},"next":"sue","chat":[{"npc":["Oh, hi! Grace said you'd come over. Did she tell you about my phone?","哦，嗨！Grace 说你会过来。她跟你说我手机那事了吗？"]},{"me":[["She did! You were lucky.","说了！你运气真好。"],["Ha, a little bit. What happened?","哈，说了一点。怎么回事？"]]},{"npc":["I left it on the tram on my first day at work! Grace found it at the end of the line. Anyway, I work at MediaCity, on a quiz podcast.","上班第一天我就把它落在电车上了！Grace 在终点站找到的。对了，我在媒体城上班，做一档知识问答播客。"]},{"me":[["A quiz podcast? That sounds fun!","问答播客？听起来好好玩！"],["Where do you get all the questions?","你的题都是从哪儿来的？"]]},{"npc":["Here's a secret: lots of the questions come from my mum, Sue. She runs a pub in Levenshulme, with a quiz every Tuesday. Go and try it, you'll love it!","告诉你个秘密：很多题是我妈 Sue 出的。她在莱文舒姆开了家酒吧，每周二晚上都有知识竞赛。去试试吧，你会喜欢的！"]}],"clip":{"src":"https://img.heyvoyo.com/clips/eat_well_lunch_2.mp4","poster":"https://img.heyvoyo.com/clips/eat_well_lunch_2.webp","where":"英国 · 写字楼外，有人拿着咖啡出来歇一会儿","why":"他在媒体城上班，午休就是这样拿杯咖啡出来透透气","by":"August de Richelieu","url":"https://www.pexels.com/video/4480972/"},"face":{"s":1,"h":"curly","hc":"dbrown","t":"hoodie","tc":"#5a5a7a","a":["headphones"],"e":"grin","bgs":"studio","prop":"mic"}},"sue":{"nm":"Sue","av":"👩🏻‍🦰","job":"莱文舒姆一家老酒吧的老板娘 · 59 岁","x":40,"y":200,"now":[["Quiet at five o'clock. Just the regulars, and a pot of tea behind the bar.","五点钟还很安静，就几个老客人，吧台后面泡着一壶茶。"],["Quiz night was packed. Twelve teams! We ran out of pens.","知识竞赛那晚挤满了人，十二支队伍！笔都不够用了。"],["The lights went off in the middle of the quiz. Danny fixed them in five minutes. Free pint for him!","竞赛进行到一半灯全灭了，Danny 五分钟就修好了。我请他喝一杯！"],["Ollie came to help on Tuesday. He reads the questions better than me, cheeky thing.","周二 Ollie 来帮忙，念题念得比我还好，这小子。"]],"story":"她年轻时在这家酒吧打工，老板退休那年，她拿出全部积蓄把店盘了下来。店里最老的规矩是知识竞赛时不许看手机，谁看就罚给全场唱首歌。最近被罚得最多的是一个中国留学生——她不是作弊，是在查单词。","ties":{"ollie":"她儿子","danny":"从小看着长大的老街坊，酒吧的电都是他修","xiaoyu":"每周二来参加知识竞赛的留学生"},"next":"xiaoyu","chat":[{"npc":["Hiya, love! You must be Ollie's friend. Come in, it's warm in here.","你好啊！你就是 Ollie 的朋友吧？快进来，里面暖和。"]},{"me":[["Thanks! Is the quiz tonight?","谢谢！今晚有知识竞赛吗？"],["Hi! Ollie says you write great questions.","你好！Ollie 说你出的题特别好。"]]},{"npc":["Yes, every Tuesday, and I write all the questions myself! There's one rule in my pub: no phones! If I see your phone, you sing a song for everyone.","对，每周二，题全是我自己出的！我这儿就一条规矩：不许看手机！要是被我看见，你就得给大家唱首歌。"]},{"me":[["Has anyone really had to sing?","真有人被罚唱歌吗？"],["Oh no! I'd better keep my phone in my bag.","糟了！我还是把手机收进包里吧。"]]},{"npc":["Ha! Xiaoyu sings nearly every week. She's a student from China, and she's always looking up words. Go and join her team, they need one more!","哈！晓雨几乎每周都唱。她是从中国来的留学生，老是查单词。去加入她那一队吧，他们正好差一个人！"]}],"clip":{"src":"https://img.heyvoyo.com/clips/eat_well_time_2.mp4","poster":"https://img.heyvoyo.com/clips/eat_well_time_2.webp","where":"伦敦 · 一家老派酒吧，傍晚（跟她的酒吧是同一种）","why":"她开的就是这样的老派街坊酒吧","by":"Florian Delée","url":"https://www.pexels.com/video/37661399/"},"face":{"s":1,"h":"bob","hc":"auburn","t":"tee","tc":"#2d2d2d","a":["hoops"],"o":1,"e":"grin","bg":"#f6e2c8","bgs":"pub","prop":"pint"}},"xiaoyu":{"nm":"Xiaoyu","av":"👩🏻‍🎓","job":"在曼彻斯特大学读硕士的成都姑娘 · 23 岁","x":130,"y":160,"now":[["In the library all day. My essay is due on Friday and I've written... two pages.","在图书馆泡了一整天。论文周五交，我写了……两页。"],["Our quiz team came second! I got the question about pandas.","我们队知识竞赛拿了第二！大熊猫那道题是我答对的。"],["I made hotpot for my flatmates. One of them cried, but she said it was 'lovely'.","给室友做了火锅。有个室友辣哭了，还一直说「好吃」。"],["Mum video-called at seven in the morning. It's three in the afternoon in Chengdu. She always forgets the time difference!","妈妈早上七点给我打视频。成都那边是下午三点，她老是忘了时差！"]],"story":"在国内英语考试分数很高，到了曼彻斯特第一周，却连公交司机说的 \"Ta, love\" 都听不懂，还坐过了三站。上个月在酒吧被罚唱歌，她唱了曼彻斯特乐队 Oasis 的《Wonderwall》，结果全场跟着一起唱——那天晚上，她第一次觉得自己是这儿的人。","ties":{"sue":"每周二去她酒吧参加知识竞赛","lin":"周末在林姐的店里打工","beth":"刚来时帮她在诊所登记的前台"},"next":"lin","chat":[{"npc":["Hi! Are you joining our team? Sue said you might come.","嗨！你要加入我们队吗？Sue 说你可能会来。"]},{"me":[["Yes, if that's OK! I'm new here.","好啊，如果可以的话！我刚来不久。"],["Sure! But I'm not very good at quizzes.","好啊！不过我不太会答题。"]]},{"npc":["Great! I'm Xiaoyu, from Chengdu. I'm doing a master's here. Honestly, our team is terrible, so don't worry!","太好了！我叫晓雨，成都人，在这儿读硕士。说实话我们队很菜，别有压力！"]},{"me":[["Do you like living here?","你喜欢住在这儿吗？"],["Is Manchester very different from Chengdu?","曼彻斯特跟成都很不一样吧？"]]},{"npc":["It's very different, but I love it! When I miss home, I go to Chinatown. I work at Lin's shop on Saturdays. She's like an aunt to me. Go and meet her, she'll feed you!","很不一样，但我很喜欢！想家了就去唐人街。我周六在林姐的店里打工，她就像我阿姨一样。去认识她吧，她肯定给你塞吃的！"]}],"clip":{"src":"https://img.heyvoyo.com/clips/life_questions_major_2.mp4","poster":"https://img.heyvoyo.com/clips/life_questions_major_2.webp","where":"图书馆里（拍摄地没写）","why":"她每天泡的就是这样的图书馆","by":"Yan Krukau","url":"https://www.pexels.com/video/8199319/"},"face":{"s":2,"h":"long","hc":"black","t":"hoodie","tc":"#d97a5c","e":"grin","bg":"#ffe8dc","bgs":"campus","prop":"laptop"}},"lin":{"nm":"Lin","av":"👩🏻","job":"唐人街中国超市的老板娘，香港人 · 52 岁","x":225,"y":170,"now":[["A lorry of rice came on Saturday. Xiaoyu and I carried bags all morning.","周六来了一卡车大米，我跟晓雨扛了一上午。"],["Took my mum to the GP. She brought egg tarts for everyone, of course.","带我妈去诊所看病。她当然又给大家带了蛋挞。"],["A student from Hunan asked for chopped chillies. I ordered a whole box just for him.","有个湖南来的学生想要剁辣椒，我专门给他订了一整箱。"],["My daughter says I work too hard. She's booked us a weekend in the Lake District.","女儿说我太拼了，给我们订了个周末去湖区。"]],"story":"九十年代跟家人从香港来，先在亲戚的外卖店里炸了十年薯条，攒够钱才开了这家超市。现在一半客人是留学生，她记得每个人家乡的口味：四川来的给郫县豆瓣，湖南来的给剁辣椒。","ties":{"xiaoyu":"周末在她店里打工的留学生","beth":"她妈妈看病的诊所前台，她妈妈每次都给 Beth 带蛋挞"},"next":"beth","chat":[{"npc":["Hello, hello! You're Xiaoyu's friend? Come in, come in. Have you eaten?","你好你好！你是晓雨的朋友？进来进来。吃饭了没？"]},{"me":[["Not yet! What do you recommend?","还没！你推荐什么？"],["Yes, thanks. I just want to look around.","吃了，谢谢。我就随便看看。"]]},{"npc":["Then you must try these dumplings. Take some home, they're the best! I came from Hong Kong thirty years ago. Back then, there weren't many Chinese shops here.","那你一定要尝尝这饺子，带一袋回家，最好吃了！我三十年前从香港来，那时候这儿还没几家中国店。"]},{"me":[["And now there are so many!","现在有这么多了！"],["Was it hard when you first came?","你刚来的时候难吗？"]]},{"npc":["Oh yes, life is much easier now! And if anyone gets ill, I send them to Beth at the GP. She's helped my mum so much. Go and say hello, and take her some egg tarts from me!","是啊，现在日子好过多啦！谁要是病了，我就让他们去诊所找 Beth。她帮了我妈好多。去跟她打个招呼吧，顺便帮我给她带几个蛋挞！"]}],"face":{"s":2,"h":"bob","hc":"dbrown","t":"apron","tc":"#b0332b","t2":"#f1e9dc","a":["ear"],"o":1,"e":"calm","bgs":"cnshop","prop":"basket"}}}},"new_york":{"zh":"纽约","en":"New York","ll":[-74.006,40.7128],"r_km":45,"start":["min","xiaoyu"],"order":["min","jess","jay","luis","andre","marcus","grace","patel","ahmed","marco","xiaoyu"],"clip":{"src":"https://img.heyvoyo.com/clips/body_mind_office_2.mp4","poster":"https://img.heyvoyo.com/clips/body_mind_office_2.webp","where":"纽约 · Cortlandt St 地铁站","by":"Ono Kosuki","url":"https://www.pexels.com/video/5999651/"},"people":{"min":{"nm":"Min","av":"🧑🏻‍💻","job":"广告公司的设计师，刚从首尔调来 · 27 岁","x":180,"y":40,"now":[["Got my usual iced latte from Marco and walked to work. I'm starting to feel like a New Yorker.","在 Marco 那儿买了每天那杯冰拿铁，走着去上班。我开始有点像纽约人了。"],["Jess asked how I was, and I just said, \"Good, you?\" No long story this time. Small win!","Jess 问我怎么样，我就回了句「挺好，你呢？」，这次没讲一大段。小小的进步！"],["My mom called from Seoul at six in the morning. She still gets the time difference wrong.","妈妈早上六点从首尔打来电话。她到现在还是算不对时差。"],["My first big presentation is next week. Jess is helping me practice every day after work.","下周要做第一个大提案。Jess 每天下班后陪我练。"]],"story":"在首尔做了三年设计，被调到纽约总部。第一周每次有人问 How are you，他都认真地从早上起床讲起，直到 Jess 把他拉到一边。现在他每个周日给首尔的妈妈拍一张纽约的天空，妈妈全存在一个相册里。","ties":{"jess":"同一个组的同事，是她教他怎么接 How are you","marco":"每天早上在他店里买一杯冰拿铁","marcus":"来美国开的第一个银行账户，是 Marcus 帮他办的","xiaoyu":"跟他一样被“How are you?”难倒"},"next":"jess","chat":[{"npc":["Oh, hi! Sorry, I'm still learning how small talk works here.","哦，嗨！不好意思，我还在学这边的人怎么寒暄。"]},{"me":[["Me too! How are you?","我也是！你好吗？"],["No worries! How's it going?","没关系！最近怎么样？"]]},{"npc":["Good, thanks! See? I'm getting better. I moved here from Seoul two months ago. Honestly, everything is so fast here.","挺好的，谢谢！你看，我有进步吧。我两个月前从首尔搬来的。说真的，这里什么都好快。"]},{"me":[["What was the hardest part?","最难的是什么？"],["What surprised you the most?","最让你意外的是什么？"]]},{"npc":["\"How are you?\" At first, I gave everyone a really long answer! My coworker Jess taught me the short ones. Go say hi to her. She's really nice.","就是「How are you」。一开始我每次都回一大段！是同事 Jess 教我怎么简单地回。去跟她打个招呼吧，她人特别好。"]}],"npc":"min_ny","clip":{"src":"https://img.heyvoyo.com/clips/eat_well_drink_2.mp4","poster":"https://img.heyvoyo.com/clips/eat_well_drink_2.webp","where":"纽约 · 拿着一杯咖啡走在街上","why":"纽约早上拿着咖啡走去上班的街，他每天也这样走","by":"Ono Kosuki","url":"https://www.pexels.com/video/5975251/"},"face":{"s":2,"h":"fringe","hc":"black","t":"tee","tc":"#ececec","a":["rglasses"],"ac":{"rglasses":"#222"},"e":"calm","bgs":"office","prop":"sketch"}},"jess":{"nm":"Jess","av":"👩🏼","job":"广告公司的文案 · 31 岁，皇后区长大","x":285,"y":70,"now":[["Big pitch on Friday. Min and I have been sharing one laptop all week.","周五有个大提案。我跟 Min 这一周都挤着用一台电脑。"],["We won the pitch! Our boss bought pizza for the whole team.","提案拿下了！老板请全组吃披萨。"],["Went to Jay's open mic on Thursday. He was actually funny this time!","周四去看了 Jay 的开放麦。这回他是真的好笑！"],["I'm trying to write a whole ad in six words. It's harder than it sounds.","我在想办法用六个词写完一整条广告，比听起来难多了。"]],"story":"在皇后区长大，爸爸开了三十年出租车，她说自己的寒暄都是在爸爸车上学的：每个乘客都能聊上两句。Min 来的第一周，她看他认认真真回答每一个 How are you，没笑他，只是递给他一张便利贴，上面写着三种回法。","ties":{"min":"她带的新同事","jay":"大学同学，常去看他的开放麦"},"next":"jay","chat":[{"npc":["Hey! Min said you'd stop by. He's doing great, by the way. Don't tell him I said that.","嘿！Min 说你会过来。顺便说一句，他进步很大。别告诉他是我说的。"]},{"me":[["Hi Jess! He says you taught him small talk.","嗨 Jess！他说是你教他寒暄的。"],["Nice to meet you! What do you do here?","很高兴认识你！你在这儿做什么？"]]},{"npc":["I'm a copywriter, so words are my job. Small talk is easy for me. I grew up in Queens, and everyone talks to everyone there.","我是文案，跟文字打交道就是我的工作。寒暄对我来说不难，我在皇后区长大，那儿谁都跟谁聊。"]},{"me":[["What do you do for fun?","你平时玩什么？"],["Any tips for me?","能给我点建议吗？"]]},{"npc":["Comedy shows! My old college friend Jay does open mics in the Village. You should go. Watching people talk is the best English class.","看脱口秀！我大学的老朋友 Jay 在格林威治村演开放麦，你该去看看。看别人怎么聊天，就是最好的英语课。"]}],"npc":"jess","clip":{"src":"https://img.heyvoyo.com/clips/dev_club_code_2.mp4","poster":"https://img.heyvoyo.com/clips/dev_club_code_2.webp","where":"美国 · 联合办公空间","why":"她们公司就是这样的开放式办公室，提案前常两个人挤一台电脑","by":"fauxels","url":"https://www.pexels.com/video/3252423/"},"face":{"s":1,"h":"wavy","hc":"brown","t":"blazer","tc":"#c24a3a","t2":"#222","a":["hoops"],"e":"grin","bgs":"office","prop":"laptop"}},"jay":{"nm":"Jay","av":"🧑🏻‍🎤","job":"还没出名的脱口秀演员，白天在咖啡店上班 · 30 岁","x":320,"y":160,"now":[["Did five minutes at an open mic last night. Two people laughed. I'm counting it!","昨晚在开放麦讲了五分钟，有两个人笑了。我就当成功了！"],["Wrote a new joke about my barber, Luis. He says he wants half the money.","写了个新段子，讲我的理发师 Luis。他说要分他一半钱。"],["Picking up extra shifts at the café with Marco. Comedy doesn't pay the rent.","这周在咖啡店跟 Marco 一起多排了几个班。说脱口秀可交不起房租。"],["A club owner saw my set and asked me back next week. A real stage, real lights!","一个俱乐部老板看了我的表演，让我下周再去。真舞台，真灯光！"]],"story":"从俄亥俄的小镇来纽约读大学，跟 Jess 是同学，毕业后留了下来，讲脱口秀已经五年了。第一次上台冷场冷到能听见吧台冰箱嗡嗡响，他没下台，干脆讲起了那台冰箱，结果第一次逗笑了全场。到现在，他每次上台前都会在心里谢一下那台冰箱。","ties":{"marco":"同一家咖啡店的同事","jess":"大学同学，常来看他演出","luis":"他的理发师，也是他最好笑的段子的主角","xiaoyu":"每周四来他开放麦讲五分钟的交换生"},"next":"luis","chat":[{"npc":["Hey! You're Jess's friend? Cool. Grab a seat, I'm on in ten minutes.","嘿！你是 Jess 的朋友？好啊。找个位子坐，我十分钟后上台。"]},{"me":[["Are you nervous?","你紧张吗？"],["Good luck! Is this your first time?","祝你顺利！是第一次上台吗？"]]},{"npc":["Ha, I've done this a hundred times, and I still get nervous. Five minutes feels like an hour when nobody laughs.","哈，我都上过一百回了，还是会紧张。没人笑的时候，五分钟就像一个小时。"]},{"me":[["Where do you get your jokes?","你的段子都是哪儿来的？"],["What's your best joke about?","你最好笑的段子讲的是什么？"]]},{"npc":["Real life! My best one is about my barber, Luis. Go get a haircut at his shop in Bushwick. He talks more than any comedian I know.","从生活里来！我最好的一个段子讲的是我的理发师 Luis。去他在布什维克的店剪个头吧。他比我认识的哪个喜剧演员都能说。"]}],"npc":"jay_comedy","clip":{"src":"https://img.heyvoyo.com/clips/fun_club_standup_0.mp4","poster":"https://img.heyvoyo.com/clips/fun_club_standup_0.webp","where":"纽约 · 夜里的街口","why":"开放麦散场后，他常跟朋友站在这样的街口，聊刚才哪个段子没响","by":"Tim Samuel","url":"https://www.pexels.com/video/5834617/"},"face":{"s":1,"h":"curly","hc":"brown","t":"tee","tc":"#2d2d2d","a":["beanie"],"ac":{"beanie":"#c9a227"},"b":"stubble","e":"grin","bgs":"stage","prop":"mic"}},"luis":{"nm":"Luis","av":"👨🏽","job":"布什维克街坊理发店的老板 · 48 岁，来自多米尼加","x":290,"y":255,"now":[["Saturday at the shop. Every chair's been full since nine.","周六的店里，从九点到现在，每把椅子都没空过。"],["My daughter is applying to college. I'm more excited than she is.","女儿在申请大学，我比她还激动。"],["Jay told his joke about me again. Now people walk in and ask, \"Are you THE Luis?\"","Jay 又讲了那个关于我的段子。现在有客人一进门就问：「你就是那个 Luis？」"],["Closed early on Sunday for my mom's birthday. Thirty people in her little apartment!","周日早早关了门给我妈过生日，她那间小公寓里挤了三十个人！"]],"story":"二十岁从多米尼加来到纽约，在别人的店里扫了两年头发，才轮到他拿推子。店里一面墙贴满了小孩第一次剪头的照片，其中一张是七岁的 Andre，哭得满脸是泪。","ties":{"jay":"老顾客，把他写进了段子","andre":"从 Andre 七岁起就给他剪头"},"next":"andre","chat":[{"npc":["¡Hola! Come in, come in. Jay sent you? Then you already know all my secrets.","¡Hola!（你好！）进来进来。Jay 让你来的？那你已经知道我所有的秘密了。"]},{"me":[["Just a little shorter, please.","剪短一点就好，谢谢。"],["Is that joke about you true?","那个讲你的段子是真的吗？"]]},{"npc":["Sit down, sit down. And don't believe everything Jay says! I talk a lot, sure. But a barber is half a therapist, you know?","坐坐坐。还有，别全信 Jay 的话！我是挺能说的。不过理发师本来就算半个心理医生，你懂吧？"]},{"me":[["What do people talk about here?","大家在这儿都聊些什么？"],["How long have you had this shop?","这家店开了多久了？"]]},{"npc":["Everything! I've had this shop for over twenty years. Kids I cut hair for are all grown up now, like Andre. He cried at his first haircut! Now he works at a sneaker store in SoHo. Go see him.","什么都聊！这家店我开了二十多年，在这儿剪过头的小孩现在都长大了，比如 Andre，他第一次剪头哭得不行！现在在 SoHo 的球鞋店上班。去看看他吧。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/fashion_club_haircut_2.mp4","poster":"https://img.heyvoyo.com/clips/fashion_club_haircut_2.webp","where":"美国 · 一家理发店（没写是哪座城市）","why":"他的店就是这样的街坊理发店，周六从早忙到晚","by":"ArtHouse Studio","url":"https://www.pexels.com/video/7686519/"},"face":{"s":4,"h":"crop","hc":"black","t":"polo","tc":"#1b4d8c","b":"goatee","a":["comb"],"e":"grin","bgs":"barber","prop":"clippers"}},"andre":{"nm":"Andre","av":"🧑🏾","job":"SoHo 球鞋店的店员 · 27 岁，布鲁克林长大","x":190,"y":290,"now":[["New drop on Saturday. The line outside the store started at six in the morning.","周六有新款发售，店门口早上六点就排起了队。"],["My cousin Marcus says I need a budget, not another pair. He's not wrong.","我表哥 Marcus 说我该做个预算，而不是再买一双。他说得也没错。"],["Sold my rarest pair and bought my mom a new fridge. Felt good, honestly.","把最稀有的一双卖了，给我妈换了台新冰箱。说实话，感觉挺好。"],["I'm teaching the new guy how to lace shoes the right way. It's an art!","我在教新来的同事怎么系鞋带才对。这可是门手艺！"]],"story":"在布鲁克林长大，收了六十多双球鞋，却总说鞋是拿来穿的，不是放在盒子里的，所以每一双都穿出过门。最舍不得的是第一双：爸爸拿两个月的加班费给他买的，鞋底早就磨平了，他一直没扔。","ties":{"luis":"从小就在他店里剪头","marcus":"表哥"},"next":"marcus","chat":[{"npc":["Yo, what's up? Luis sent you? That man has known me since I was seven.","哟，你好啊！Luis 让你来的？他从我七岁就认识我了。"]},{"me":[["He says you cried at your first haircut!","他说你第一次剪头的时候哭了！"],["Hi! These sneakers look amazing.","嗨！这些球鞋看起来太棒了。"]]},{"npc":["Ha! Okay, welcome in. Look around. Are you looking for something to wear every day, or something special?","哈！好吧，欢迎。随便看。你想要天天穿的，还是特别一点的？"]},{"me":[["Something for every day.","天天穿的吧。"],["Just looking, thanks.","就看看，谢谢。"]]},{"npc":["Cool, take your time. But real talk? Don't put shoes on a credit card. My cousin Marcus works at a bank in Midtown. He'll tell you the same thing!","好，慢慢挑。不过说句实在的：别刷信用卡买鞋。我表哥 Marcus 在中城的银行上班，他也会这么跟你说！"]}],"npc":"andre","clip":{"src":"https://img.heyvoyo.com/clips/fashion_club_sneakers_0.mp4","poster":"https://img.heyvoyo.com/clips/fashion_club_sneakers_0.webp","where":"纽约 · SoHo 的西百老汇街 · 早上","why":"他上班的球鞋店就在 SoHo 这样的街上，新款发售的早上最热闹","by":"Coverr","url":"https://www.pexels.com/video/854197/"},"face":{"s":6,"h":"crop","hc":"black","t":"tee","tc":"#111","a":["bcap"],"ac":{"bcap":"#1a6ad2"},"e":"grin","bgs":"shoes","prop":"sneaker"}},"marcus":{"nm":"Marcus","av":"👨🏾‍💼","job":"中城银行网点的个人客户顾问 · 40 岁","x":90,"y":270,"now":[["Lunchtime rush. Everyone comes in on their break with a question about their card.","午休最忙，大家都趁休息过来问信用卡的事。"],["Helped Grace find a cheaper way to send money home. That's my favorite kind of day.","帮 Grace 找到了一个更便宜的往家里汇钱的办法。我最喜欢这样的日子。"],["My little cousin Andre asked me to look at his budget. I almost cried. Happy tears!","表弟 Andre 主动找我帮他看预算。我差点哭了，高兴的！"],["Coaching my son's basketball team on Saturdays. We lost again, but the kids had fun.","周六给儿子的少儿篮球队当教练。又输了，不过孩子们玩得挺开心。"]],"story":"二十出头的时候，他自己刷信用卡欠了一大笔，每个月只还最低额，还了好几年。所以现在每个来办第一张卡的年轻人，他都会多花十分钟讲账单怎么看。Min 来开户那天，他还给他讲了支票账户和储蓄账户有什么不一样。","ties":{"andre":"表弟","min":"帮他开了来美国的第一个银行账户","grace":"多年的老客户，帮她安排往家里汇钱"},"next":"grace","chat":[{"npc":["Hi there, have a seat. You're Andre's friend, right? Let me guess. He told you not to buy shoes on credit.","你好，请坐。你是 Andre 的朋友吧？我猜猜，他跟你说别刷卡买鞋。"]},{"me":[["Yes! Is he right?","对！他说得对吗？"],["Ha, yes. Should I get a credit card?","哈，对。我该办张信用卡吗？"]]},{"npc":["Believe it or not, he's right! A credit card is a great tool if you pay it off every month. If you only pay the minimum, it gets expensive fast.","信不信由你，他说对了！每个月全额还清，信用卡就是好工具。要是只还最低额，很快就会变得很贵。"]},{"me":[["How do I build credit here?","在这儿怎么攒信用记录？"],["What should I do first?","那我第一步该怎么做？"]]},{"npc":["Start small and always pay on time. Lots of my customers came here from far away, like Grace, a nurse from Manila. She sends money home every month. Ask her how she does it!","从小额开始，每次都按时还。我很多客户都是从很远的地方来的，比如从马尼拉来的护士 Grace。她每个月往家里寄钱。去问问她是怎么安排的！"]}],"npc":"marcus_bank","clip":{"src":"https://img.heyvoyo.com/clips/first_money_credit_0.mp4","poster":"https://img.heyvoyo.com/clips/first_money_credit_0.webp","where":"纽约 · 曼哈顿中城街上","why":"他上班的银行网点就在中城这样的街上，午休时人最多","by":"JINISH RAJAGOPAL","url":"https://www.pexels.com/video/35307737/"},"face":{"s":5,"h":"bald","hc":"black","t":"suit","tc":"#2b3a55","t2":"#fff","b":"short","e":"calm","bgs":"bank","prop":"card"}},"grace":{"nm":"Grace","av":"👩🏻‍⚕️","job":"布鲁克林一家医院的注册护士 · 36 岁，来自菲律宾","x":35,"y":190,"now":[["Long night shift. The ambulances kept coming all night.","夜班好长，救护车一整晚都没停过。"],["Video call with my daughter in Manila. She lost her first tooth!","跟在马尼拉的女儿视频，她掉了第一颗牙！"],["Brought adobo to work for the whole team. Dr. Patel had three plates.","做了一锅菲律宾炖肉 adobo 带去上班，给全组吃，Patel 医生吃了三盘。"],["Booked my flight home for Christmas. Two whole weeks with my family!","订好了圣诞节回家的机票，能跟家人待整整两个星期！"]],"story":"在马尼拉读完护理，考过英语和美国执照考试，来纽约已经十年。每月往家里寄钱，女儿在菲律宾跟外婆住。病房里大家都叫她 Ate Grace（大姐 Grace）。她手机里存着病人家属教她的一句句家乡话，有波兰语、海地克里奥尔语、粤语……她说病人一听到家乡话，手就没那么抖了。","ties":{"marcus":"她的银行顾问，帮她往家里汇钱","patel":"同一家医院的同事"},"next":"patel","chat":[{"npc":["Hi! Marcus told me you'd come by. Sorry, I just finished my shift. Okay, okay, I'm awake now.","嗨！Marcus 跟我说你会来。不好意思，我刚下班。好了好了，我醒了。"]},{"me":[["You must be tired. Was it a busy night?","你一定累了。昨晚忙吗？"],["Marcus says you're from Manila.","Marcus 说你是从马尼拉来的。"]]},{"npc":["Yes po! Ten years in New York now. Last night was busy, but I love this job. My daughter is back in Manila with my mom.","是呀！（po 是菲律宾话里表示客气的小词）我来纽约十年了。昨晚是挺忙的，不过我喜欢这份工作。我女儿在马尼拉，跟我妈妈住。"]},{"me":[["That must be hard.","那一定很难吧。"],["Do you get to see her?","你能常见到她吗？"]]},{"npc":["It's hard, but we video call every night, and I fly home at Christmas. Hey, you should meet Dr. Patel. He takes care of our older patients. He's the kindest doctor I know.","是挺难的，不过我们每天晚上视频，圣诞节我就飞回去。对了，你该认识一下 Patel 医生。他照顾我们医院的老年病人，是我认识的最好心的医生。"]}],"npc":"grace","clip":{"src":"https://img.heyvoyo.com/clips/med_club_er_2.mp4","poster":"https://img.heyvoyo.com/clips/med_club_er_2.webp","where":"美国纽约 · 布鲁克林街上的救护车","why":"她上班的医院在布鲁克林，门口天天能看到这样的救护车","by":"CityXcape","url":"https://www.pexels.com/video/3940427/"},"face":{"s":3,"h":"bun","hc":"black","t":"scrubs","tc":"#5b3f8f","a":["steth","tag"],"e":"grin","bgs":"ward","prop":"clipboard"}},"patel":{"nm":"Dr. Patel","av":"👨🏽‍⚕️","job":"医院的老年科医生 · 46 岁，印度裔","x":40,"y":95,"now":[["Sunday walk around the lake in Central Park. I tell my patients to walk, so I have to do it too!","周日绕着中央公园的湖走了一圈。我天天让病人多走路，自己也得做到！"],["A patient told me she wants to go home, not to a care home. So we made a plan together.","一位病人跟我说，她想回自己家，不想去养老院。我们就一起想了个办法。"],["My parents visited from New Jersey. My mom still asks when I'll be a \"real\" doctor, like a surgeon.","爸妈从新泽西来看我。我妈到现在还问我，什么时候当个「真正的」医生，比如外科医生。"],["Ahmed's dad came by with lunch from the cart. Best thank-you I've ever gotten.","Ahmed 的爸爸来了，还带着餐车的午饭。这是我收过最好的谢礼。"]],"story":"他总说「能出院」和「能安全回家」是两回事。他会花半小时问一位老太太家里有几级台阶、谁帮她买菜，而不是只看化验单。他学医，是因为小时候奶奶住院时，医院里没人听得懂她说的古吉拉特语。","ties":{"grace":"同一家医院的护士","ahmed":"Ahmed 的爸爸常来找他看病，一家人都跟他很熟"},"next":"ahmed","chat":[{"npc":["Hello! You must be Grace's friend. She told me you were coming.","你好！你一定是 Grace 的朋友。她跟我说你要来。"]},{"me":[["Nice to meet you, Dr. Patel. What kind of doctor are you?","很高兴认识你，Patel 医生。你是哪一科的？"],["What's your job like?","你的工作是什么样的？"]]},{"npc":["I'm a geriatrician. That means I work with older patients. My favorite question isn't \"What's wrong?\" It's \"What matters to you?\"","我是老年科医生，就是照顾年纪大的病人。我最喜欢问的不是「你哪儿不舒服？」，而是「什么对你最重要？」"]},{"me":[["That's a great question.","这个问题问得真好。"],["What do your patients usually say?","你的病人一般怎么回答？"]]},{"npc":["You know what most of them say? \"Home.\" Hey, are you hungry? Ahmed's family brings me food all the time. He runs a halal cart in Midtown. Try his chicken over rice!","你知道大多数人怎么回答吗？「家」。对了，你饿不饿？Ahmed 一家老给我送吃的。他在中城开一辆清真餐车，去尝尝他的鸡肉饭！"]}],"npc":"patel","clip":{"src":"https://img.heyvoyo.com/clips/body_mind_park_2.mp4","poster":"https://img.heyvoyo.com/clips/body_mind_park_2.webp","where":"纽约 · 中央公园的湖边","why":"他周日常来中央公园的湖边散步","by":"CityXcape","url":"https://www.pexels.com/video/4062155/"},"face":{"s":4,"h":"side","hc":"salt","t":"shirt","tc":"#ffffff","a":["steth","glasses"],"b":"mous","o":1,"e":"calm","bgs":"ward","prop":"xray"}},"ahmed":{"nm":"Ahmed","av":"🧔🏽","job":"中城街角清真餐车的摊主 · 39 岁，来自埃及","x":120,"y":150,"now":[["Cold night, long line. When it's cold, everyone wants chicken over rice.","天一冷，晚上的队就排得老长。冷天谁都想来一份鸡肉饭。"],["My dad came by the cart today. He still says my rice needs more salt.","今天我爸来餐车了。他还是说我的饭不够咸。"],["Marco brought me a coffee at five in the morning. I gave him breakfast. Our usual trade.","早上五点 Marco 给我送了杯咖啡，我给了他一份早饭。我们的老规矩。"],["Saving up for a little restaurant in Astoria. One day!","在攒钱，想在阿斯托里亚开一家小餐馆。总有一天！"]],"story":"十二年前从开罗来到纽约，先跟着叔叔在餐车上切洋葱。现在每天早上五点就出车，记得每个熟客要多辣。有个熟客失业那几个月，他一直没收那人的钱；后来那人找到了工作，上班第一天就来把钱全付清了，还多给了一倍。","ties":{"marco":"街对面咖啡店的咖啡师，每天早上拿早饭换咖啡","patel":"他爸爸的医生"},"next":"marco","chat":[{"npc":["Hey, my friend! Dr. Patel sent you? He's a good man. What can I get you?","嘿，朋友！Patel 医生让你来的？他是个好人。想吃点什么？"]},{"me":[["Chicken over rice, please.","一份鸡肉饭，谢谢。"],["What's good here?","这儿什么好吃？"]]},{"npc":["Chicken over rice. Always! White sauce? Hot sauce? Careful, my hot sauce is no joke.","鸡肉饭，永远是它！要白酱吗？辣酱呢？小心，我的辣酱可不是闹着玩的。"]},{"me":[["Just a little hot sauce.","辣酱少放一点。"],["Both, please!","都要！"]]},{"npc":["You got it! You know, I start at five every morning. The only other guy up that early is Marco, the barista across the street. He brings me coffee, I give him breakfast. Go meet him!","好嘞！你知道吗，我每天早上五点就开工。除了我，那么早起来的只有街对面咖啡店的 Marco。他给我送咖啡，我给他早饭。去认识一下他吧！"]}],"clip":{"src":"https://img.heyvoyo.com/clips/body_mind_konbini_2.mp4","poster":"https://img.heyvoyo.com/clips/body_mind_konbini_2.webp","where":"纽约 · 傍晚街边的餐车","why":"他的餐车就停在这样的街边，傍晚下班的人最多","by":"Juan Antonio Ordoñez","url":"https://www.pexels.com/video/34387415/"},"face":{"s":4,"h":"short","hc":"black","t":"apron","tc":"#c0392b","t2":"#f0f0f0","b":"full","e":"grin","bg":"#fde7c9","bgs":"cart","prop":"plate"}},"marco":{"nm":"Marco","av":"🧑🏽","job":"公司楼下咖啡店的咖啡师 · 26 岁","x":225,"y":170,"now":[["Morning rush. I said \"How are you?\" about two hundred times before nine.","早高峰。九点之前，我大概说了两百次 How are you。"],["Jay tried a new joke on the customers. Nobody laughed. I did, though.","Jay 拿新段子在顾客身上试了试，没人笑。不过我笑了。"],["Min ordered without looking at the menu today. He's a real regular now.","Min 今天点单都没看菜单。他现在是真正的熟客了。"],["Taking a latte art class on Sundays. My hearts still look like potatoes.","周日在上拉花课。我拉的心还是像土豆。"]],"story":"他记得两百多个常客喝什么，却常常忘了吃自己的午饭。他说问一句 How are you，不是真要听答案，是想让人知道：今天有人看见你了。有位老太太每天来要一杯热水，他从没收过钱，后来才知道，她丈夫以前每天都在这儿买咖啡。","ties":{"min":"最近的新熟客","jay":"同一家咖啡店的同事","ahmed":"餐车就停在咖啡店对面，每天早上拿咖啡换早饭"},"next":"min","chat":[{"npc":["Morning! Ahmed sent you? Then this coffee's on me. What can I get you?","早！Ahmed 让你来的？那这杯我请。想喝点什么？"]},{"me":[["An iced latte, please.","一杯冰拿铁，谢谢。"],["Thanks! What do you recommend?","谢谢！你推荐什么？"]]},{"npc":["Iced latte! Everybody loves it. My newest regular gets one every day. He's from Seoul. When he first came in, I said \"How are you?\" and he told me about his whole morning!","冰拿铁！大家都爱喝。我最新的一位熟客每天都点一杯。他是从首尔来的。他刚来那会儿，我问一句 How are you，他把整个早上都讲给我听了！"]},{"me":[["What does he say now?","他现在怎么回？"],["Do you remember all your regulars?","你所有熟客都记得吗？"]]},{"npc":["Ha, now he just says, \"Good, you?\" like a real New Yorker. I remember everybody's order. It's my superpower. His name's Min. He comes in at eight-thirty. Go say hi!","哈，现在他就回一句「挺好，你呢？」，跟地道的纽约人一样。每个人点什么我都记得，这是我的超能力。他叫 Min，八点半来。去打个招呼吧！"]}],"npc":"marco_ny","face":{"s":3,"h":"side","hc":"dbrown","t":"apron","tc":"#2f2f2f","t2":"#e9e0cf","b":"stubble","e":"grin","bgs":"cafe","prop":"coffee"}},"xiaoyu":{"nm":"Xiaoyu","av":"👩🏻‍🎓","job":"杭州来的交换生，每周四在开放麦讲脱口秀 · 21 岁","x":200,"y":105,"now":[["Did my coffee story at Jay's open mic. People laughed at \"Yes.\" I almost cried.","在 Jay 的开放麦讲了点咖啡的故事。大家在“是的”那里笑了。我差点哭了。"],["Min from the ad agency told me he also answers \"How are you?\" too seriously. We are a team now.","广告公司的 Min 说他回答“你好吗”也太认真。我们现在是一队的了。"],["Practiced my phone-call joke in the bathroom. My roommate knocked: \"Who are you talking to?\"","在卫生间练打电话的段子，室友敲门问：“你在跟谁说话？”"],["A barista wrote \"Shower\" on my cup again. New York, you too?","店员又在我杯子上写了“Shower”。纽约，你也这样？"]],"story":"杭州来的交换生，这学期在纽约。英语笔试满分，一开口就变小声。她第一次站上开放麦，是在一个叫「语言小镇」的地方；现在每周四去 Jay 办的开放麦讲五分钟。她说讲脱口秀是她练英语最吓人、也最有用的办法——台下的人笑了，就说明他们听懂了。","ties":{"jay":"每周四在他办的开放麦上台","min":"都是刚来纽约、被“How are you?”难倒的人"},"next":"jay","standup":true,"chat":[{"npc":["Oh! Hi... um, sorry. I'm Xiaoyu. I'm practicing my set.","噢！嗨……嗯，不好意思。我是小雨，我在练我的段子。"]},{"me":[["What's your set about?","你的段子讲什么？"],["You do stand-up? In English?","你讲脱口秀？用英语？"]]},{"npc":["Yes... in English. It's about ordering coffee. The barista asked, \"Hot or iced?\" And I said... \"Yes.\"","是……用英语。讲的是点咖啡。店员问“热的还是冰的？”，我说……“是的。”"]},{"me":[["Ha! That happened to me too.","哈！我也遇到过。"],["That's funny! Are you nervous?","好好笑！你紧张吗？"]]},{"npc":["Very nervous. But Jay says, \"Just talk to the people.\" He runs this open mic. Go say hi to Jay. He's funny, and he's kind.","非常紧张。但 Jay 说：“跟台下的人说话就好。”这个开放麦是他办的。去跟 Jay 打个招呼吧，他很好笑，人也很好。"]}],"face":{"s":2,"h":"long","hc":"black","t":"hoodie","tc":"#e88aa8","a":["rglasses"],"ac":{"rglasses":"#333"},"e":"grin","bgs":"stage","prop":"mic"}}}},"san_francisco":{"zh":"旧金山","en":"San Francisco","ll":[-122.4194,37.7749],"r_km":25,"start":["alex","may"],"order":["alex","jamie","rosa","diego","tony","marcus","priya","kevin","may","linda"],"clip":{"src":"https://img.heyvoyo.com/clips/dev_club_robotaxi_0.mp4","poster":"https://img.heyvoyo.com/clips/dev_club_robotaxi_0.webp","where":"旧金山 · 街边的出租车道，上午","by":"Dubang chang","url":"https://www.pexels.com/video/29190056/"},"people":{"alex":{"nm":"Alex","av":"👩🏻‍🎨","job":"住在教会区的设计师 · 32 岁","x":70,"y":60,"now":[["My robotaxi showed up super fast this morning. It still feels a little like magic.","今天早上叫的无人驾驶出租车一下就到了。到现在还是觉得有点神奇。"],["Sunny all afternoon, then freezing at night. I left my jacket at home. Big mistake.","下午还大太阳，一到晚上冷得要命。外套忘在家里了，大错特错。"],["I'm working on a new app design. My teammate Priya says it's too pink.","新的 app 设计做到一半。同事 Priya 说颜色太粉了。"],["It rained really hard last night, so I took a regular taxi. In that weather, I want a real person driving.","昨晚雨下得特别大，我就打了一辆普通出租车。那种天气，还是想要个真人开车。"]],"story":"她第一次坐无人驾驶出租车，从上车拍到下车，把视频发给了老家的妈妈。妈妈只回了一句：「那路上谁陪你说话？」从那以后，她每次坐车都给妈妈发一条语音。","ties":{"jamie":"每天早上都去 Jamie 的咖啡店买拿铁","priya":"同一家公司的同事，她做设计，Priya 写代码","linda":"她楼下的房东奶奶，Alex 租的就是 Linda 家的楼上"},"next":"jamie","chat":[{"npc":["Hey! Are you new around here? You look a little lost.","嘿！你是刚来这一片的吗？看着有点找不着路。"]},{"me":[["Yeah, I just moved here. I'm waiting for a taxi.","对，我刚搬来，在等出租车。"],["Kind of. Do the driverless taxis stop here?","有点。无人驾驶出租车是在这儿停吗？"]]},{"npc":["Then you're in the right place. The driverless taxis stop right here. I take one to work almost every day. The first time, I filmed the whole ride!","那你没找错地方，无人驾驶出租车就停在这儿。我差不多每天都坐它去上班。第一次坐的时候，我从头拍到了尾！"]},{"me":[["Isn't it scary with no driver?","没有司机，不害怕吗？"],["Do you like it more than a regular taxi?","你觉得它比普通出租车好吗？"]]},{"npc":["Honestly? It's easy, and it's quiet. But on rainy days, I still want a real driver. Anyway, I need coffee first. Come with me to Jamie's café. She makes the best latte in the Mission.","说实话？方便，也安静。不过下雨天我还是想要个真人司机。好啦，我得先喝杯咖啡。跟我去 Jamie 的咖啡店吧，她做的拿铁是教会区最好喝的。"]}],"npc":"alex_sf","clip":{"src":"https://img.heyvoyo.com/clips/dev_club_robotaxi_0.mp4","poster":"https://img.heyvoyo.com/clips/dev_club_robotaxi_0.webp","where":"旧金山 · 街边的出租车道，上午","why":"她常在这样的上车点等无人驾驶出租车","by":"Dubang chang","url":"https://www.pexels.com/video/29190056/"},"face":{"s":2,"h":"bob","hc":"black","t":"tee","tc":"#e9c46a","a":["rglasses","ear"],"ac":{"rglasses":"#222"},"e":"grin","bgs":"office","prop":"sketch"}},"jamie":{"nm":"Jamie","av":"👩🏼‍🎨","job":"教会区咖啡店的咖啡师，周末画壁画 · 27 岁","x":170,"y":40,"now":[["Morning rush! Same faces, same coffee orders, every single day.","早上最忙的时候！天天都是那几张脸，点的也都是那几样。"],["I finished the sketch for my next mural. It's a hummingbird, Rosa's favorite bird.","下一面壁画的草图画好了。是一只蜂鸟，Rosa 最喜欢的鸟。"],["My landlord raised the rent again. I might need a roommate.","房东又涨房租了。我可能得找个室友。"],["I painted all day Saturday. My arms hurt, but the wall looks amazing.","周六画了一整天。胳膊酸死了，不过那面墙好看极了。"]],"story":"她从俄亥俄搬来，本来想当画家，结果先当了咖啡师。有一天 Rosa 来买咖啡，看到她在杯子上随手画的小画，当场就把自己店的整面外墙交给了她。那是她画的第一面墙。","ties":{"alex":"每天早上来买拿铁的熟客","rosa":"她画的第一面壁画，就在 Rosa 店的外墙上"},"next":"rosa","chat":[{"npc":["Hi! You're Alex's friend, right? She said you'd come in. What can I get you?","嗨！你是 Alex 的朋友吧？她说你会来。想喝点什么？"]},{"me":[["A latte, please. Alex says yours is the best.","一杯拿铁，谢谢。Alex 说你做的最好喝。"],["Just a small coffee, please.","来一杯小杯的咖啡就行。"]]},{"npc":["Coming right up. Oh, look at your cup. I drew a little cat on it. I just can't stop drawing!","马上好。哦，看看你的杯子，我在上面画了只小猫。我就是忍不住要画！"]},{"me":[["That's so cute! Are you an artist?","好可爱！你是画画的吗？"],["Wow. Do you draw on every cup?","哇。每个杯子你都画吗？"]]},{"npc":["Kind of! On weekends I paint murals. My first one is on Rosa's taco shop on 24th Street. Go eat there and check out the wall. Tell Rosa I sent you!","算是吧！周末我画壁画。我画的第一面墙，就在 24 街 Rosa 的塔可店外面。去那儿吃一顿，顺便看看那面墙。跟 Rosa 说是我让你去的！"]}],"clip":{"src":"https://img.heyvoyo.com/clips/body_mind_ward_1.mp4","poster":"https://img.heyvoyo.com/clips/body_mind_ward_1.webp","where":"一家咖啡店的吧台，早上（看不出是哪座城市）","why":"她每天早上站的就是这样的吧台","by":"Kampus Production","url":"https://www.pexels.com/video/6829137/"},"face":{"s":1,"h":"bun","hc":"lblonde","t":"apron","tc":"#6a8caf","t2":"#f2e6d9","a":["bandana"],"ac":{"bandana":"#e76f51"},"e":"grin","bgs":"mural","prop":"brush"}},"rosa":{"nm":"Rosa","av":"👩🏽‍🍳","job":"24 街塔可店的老板 · 52 岁","x":270,"y":50,"now":[["The lunch line went out the door today. My feet are killing me.","今天中午排队排到了门外。脚疼死了。"],["My daughter got into nursing school! I cried in the kitchen.","女儿考上护士学校了！我在厨房里哭了一场。"],["The rent for the shop went up again. I don't want to raise my prices, but…","店面的租金又涨了。我不想涨价，可是……"],["Jamie started painting the hummingbird on my side wall. People already stop to take pictures.","Jamie 开始在我店的侧墙上画蜂鸟了。已经有人停下来拍照了。"]],"story":"她二十岁从墨西哥哈利斯科来到旧金山，在别人的后厨洗了十年碗，才开了自己的店。店里的莎莎酱是妈妈的方子，从来没写在纸上，只有她和哥哥 Diego 记得。","ties":{"jamie":"给她的店画壁画的咖啡师","diego":"她哥哥"},"next":"diego","chat":[{"npc":["¡Hola! Jamie sent you? Come in, sit anywhere you like.","¡Hola！Jamie 让你来的？进来，随便坐。"]},{"me":[["Yes! I came to see the mural.","对！我是来看壁画的。"],["Hi! What's good here?","你好！这儿什么好吃？"]]},{"npc":["Welcome! You have to try the carnitas tacos. The salsa is my mom's recipe. Only two people know it: me and my brother.","欢迎！一定要尝尝我们的炖猪肉塔可。莎莎酱是我妈的方子，只有两个人知道：我和我哥。"]},{"me":[["Mmm, this is so good! Who taught you to cook?","嗯，太好吃了！谁教你做菜的？"],["Does your brother cook too?","你哥哥也会做饭吗？"]]},{"npc":["My mom taught me. My brother Diego knows the salsa by heart, but he can't even boil an egg, ha! He drives a cable car up and down the hills all day, talking to everyone. Go ride with him. He's like a free tour guide!","我妈教的。我哥 Diego 把酱的方子记得清清楚楚，可连鸡蛋都不会煮，哈！他开缆车，一整天在坡上坡下来回跑，跟谁都能聊。去坐坐他的车吧，他就是个免费导游！"]}],"face":{"s":4,"h":"braidbun","hc":"black","t":"apron","tc":"#d94f3d","t2":"#f6e7c1","a":["hoops"],"o":1,"e":"grin","bg":"#fde4c8","bgs":"kitchen","prop":"taco"}},"diego":{"nm":"Diego","av":"👨🏽","job":"旧金山缆车的司机 · 55 岁","x":310,"y":140,"now":[["Thick fog this morning. You couldn't see the bay from the top of the hill.","今天早上雾很大，站在坡顶上连海湾都看不见。"],["A tourist asked me if the cable car goes to Los Angeles. I said, \"Only on Sundays!\"","有个游客问我缆车到不到洛杉矶。我说：「只有周日去！」"],["I stopped at May's bakery for egg tarts on my break. Still warm.","休息的时候去 May 的面包店买了蛋挞，还是热的。"],["My arms are sore. Pulling the grip on these hills all day is a real workout.","胳膊好酸。在这些坡上拉一整天闸，跟健身差不多。"]],"story":"他年轻时第一次考缆车司机没过，因为拉闸的力气不够。他去健身房练了半年，第二次才考上。现在他敲铃的节奏全城有名，还参加过缆车敲铃比赛。","ties":{"rosa":"他妹妹","may":"休息时常去她店里买蛋挞","tony":"在缆车终点站常碰到，一起聊几句"},"next":"tony","chat":[{"npc":["Hold on tight! Rosa told me you'd come. You're the one who loved her salsa, right?","抓紧了！Rosa 说你会来。你就是那个爱吃她莎莎酱的吧？"]},{"me":[["That's me! Wow, this hill is so steep!","就是我！哇，这个坡好陡！"],["Yes! Can I stand on the outside?","对！我能站在外面吗？"]]},{"npc":["Ha! Just hold the pole and don't lean out, and you'll be fine. And listen to my bell. I ring it a little differently on every hill!","哈！扶好杆子，别往外探身子，就没事。听我敲铃，每个坡我敲得都不太一样！"]},{"me":[["Do you ever get tired of the hills?","这些坡你不会腻吗？"],["Do you like your job?","你喜欢这份工作吗？"]]},{"npc":["No way, I love it! I meet people from all over the world. And at the end of the line, I always chat with Tony. He drives for Lyft, and he knows the best food in the city. Tell him Diego says hi!","哪会，我喜欢得很！我能碰到世界各地的人。到了终点站，我总跟 Tony 聊几句。他开网约车，城里哪儿好吃他全知道。跟他说 Diego 问他好！"]}],"face":{"s":4,"h":"short","hc":"salt","t":"uniform","tc":"#1f3550","t2":"#cfd8e3","a":["cap"],"b":"mous","o":1,"e":"grin","bgs":"cablecar","prop":"bell"}},"tony":{"nm":"Tony","av":"👨🏻","job":"开网约车的司机 · 45 岁","x":300,"y":250,"now":[["Gas went up again. I'm filling up before my night shift.","油价又涨了。上夜班之前先去加满。"],["Early airport ride this morning. They were flying to Manila, and suddenly I really missed my grandma's cooking.","一大早送人去机场。他们飞马尼拉，我一下子特别想吃外婆做的菜。"],["Robotaxis everywhere downtown today. I'm not worried… okay, maybe a little.","今天市中心到处都是无人驾驶出租车。我不担心……好吧，有一点点。"],["My son had a basketball game on Saturday. Marcus came to cheer too.","周六儿子打篮球比赛。Marcus 也来加油了。"]],"story":"他是菲律宾裔，开网约车之前，在奥克兰的港口开了十五年叉车。他车里总备着薄荷糖和手机充电线，他说：好司机要替乘客想到他们忘带的东西。这一点，他觉得无人车比不了。","ties":{"diego":"缆车终点站的老朋友，等客人的时候常一起聊天","marcus":"奥克兰的老街坊，Marcus 小时候骑车还是他教的"},"next":"marcus","chat":[{"npc":["Hey, get in! Diego's friend? That guy never stops talking, right?","嘿，上车！Diego 的朋友？那家伙嘴就没停过，对吧？"]},{"me":[["Ha, yeah! How's your night going?","哈，对！你今晚怎么样？"],["Hi! Busy night?","嗨！今晚忙吗？"]]},{"npc":["Not bad. Hey, did you see all those robotaxis out there? People say they'll take my job one day.","还行。哎，你看到外面那些无人驾驶出租车了吗？大家都说早晚有一天它们会抢了我的饭碗。"]},{"me":[["Do you think that's true?","你觉得会吗？"],["Does that worry you?","你担心吗？"]]},{"npc":["Who knows? But a robot can't tell you where to get good Filipino food! Okay, here we are. If you want to make friends here, join my buddy Marcus's run club on Saturday. Just so you know, he loves hills.","谁知道呢。可机器人没法告诉你哪儿有好吃的菲律宾菜！好了，到了。想在这儿交朋友的话，周六去参加我哥们 Marcus 的跑团。先提醒你：他最爱跑坡。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/economy_club_fuel_0.mp4","poster":"https://img.heyvoyo.com/clips/economy_club_fuel_0.webp","where":"美国 · 晚上街边的加油站","why":"他上夜班前常去这样的加油站加油","by":"Dillon Baxter","url":"https://www.pexels.com/video/39372797/"},"face":{"s":3,"h":"short","hc":"black","t":"polo","tc":"#3a3a3a","b":"stubble","e":"calm","bgs":"hills","prop":"wheel"}},"marcus":{"nm":"Marcus","av":"👨🏾","job":"高中体育老师，周末带跑团 · 34 岁","x":200,"y":290,"now":[["Wednesday night run. Cold and dark, but everyone finished.","周三晚上夜跑。又冷又黑，不过大家都跑完了。"],["My students did their first mile run. Some of them walked. That's okay. They showed up.","学生们第一次测一英里跑，有几个是走完的。没关系，来了就好。"],["Saturday's run was so foggy. We couldn't see the bridge at all!","周六跑步的时候雾特别大，连大桥都看不见！"],["Priya beat me up the hill again. I'm getting old!","Priya 上坡又超过我了。我老了！"]],"story":"他在奥克兰长大，跟 Tony 住一条街，骑自行车还是 Tony 教的。他当体育老师的原因很简单：小时候有个老师每天早上陪他跑步，把他从街头拉了回来。现在他想当那样的人。","ties":{"tony":"小时候住同一条街的大哥，骑车是 Tony 教的","priya":"跑团里跑得最快的队员"},"next":"priya","chat":[{"npc":["Morning! You're Tony's friend? Great. Ready for some hills?","早！你是 Tony 的朋友？太好了。准备好爬坡了吗？"]},{"me":[["I'll try! But I'm pretty slow.","我试试！不过我跑得挺慢的。"],["Hills? Tony warned me about you!","爬坡？Tony 提醒过我！"]]},{"npc":["Ha! Don't worry. Nobody gets left behind here. We run together, and then we get coffee. That's the best part.","哈！别担心，我们这儿不落下任何人。一起跑，跑完一起喝咖啡，那才是最棒的部分。"]},{"me":[["Who's the fastest here?","这儿谁跑得最快？"],["Who else is in the club?","跑团里还有谁？"]]},{"npc":["See the woman in the blue jacket? That's Priya. She moved here from India last year, and now she's faster than me. Go say hi!","看到那个穿蓝外套的了吗？那是 Priya。她去年从印度搬来，现在比我跑得还快。去跟她打个招呼吧！"]}],"clip":{"src":"https://img.heyvoyo.com/clips/growth_club_run_1.mp4","poster":"https://img.heyvoyo.com/clips/growth_club_run_1.webp","where":"夜里跑步的人（拍摄地不详）","why":"他周三晚上带人夜跑，跑的就是这样的路","by":"Atilla Kurt","url":"https://www.pexels.com/video/40145656/"},"face":{"s":6,"h":"crop","hc":"black","t":"jersey","tc":"#c0392b","t2":"#fff","a":["whistle"],"ac":{"whistle":"#222"},"b":"short","e":"grin","bgs":"track","prop":"stopwatch"}},"priya":{"nm":"Priya","av":"👩🏽‍💻","job":"科技公司的软件工程师 · 29 岁","x":90,"y":270,"now":[["We launch on Friday. My teammate and I are fixing bugs on one laptop.","周五就要上线了。我和同事挤在一台电脑前改 bug。"],["Video call with my parents in Bangalore. It's morning for them and night for me.","跟班加罗尔的爸妈视频。他们那边是早上，我这边是晚上。"],["I looked at a new apartment. Tiny room, crazy rent. Welcome to San Francisco!","去看了一套房子。房间小小的，房租贵得离谱。欢迎来到旧金山！"],["Got my flu shot at Kevin's pharmacy. He explained everything so clearly.","在 Kevin 的药房打了流感疫苗。他把每一步都讲得清清楚楚。"]],"story":"她来旧金山的第一个夏天，只带了短袖，结果冷得在路边买了一件印着金门大桥的游客卫衣。那件卫衣她现在还天天穿，同事都管她叫「游客」。","ties":{"marcus":"她参加的跑团的领队","alex":"同事，一起做公司的 app","kevin":"她家附近药房的药剂师，她刚来时生病，是 Kevin 帮的忙"},"next":"kevin","chat":[{"npc":["Hi! Marcus sent you over? He tells everyone I'm fast. I'm just stubborn!","嗨！Marcus 让你过来的？他逢人就说我跑得快。其实我只是不服输！"]},{"me":[["Ha! How do you like San Francisco?","哈！你觉得旧金山怎么样？"],["Marcus said you moved here last year. What do you do?","Marcus 说你是去年搬来的。你做什么工作？"]]},{"npc":["I'm a software engineer, and I love it here. The city is beautiful. But nobody told me about the fog! I'm always cold here.","我是软件工程师，很喜欢这儿。城市很美，可没人告诉我这儿的雾这么大！我在这儿老是觉得冷。"]},{"me":[["Is it hard to live in a new country?","在一个新的国家生活难吗？"],["Do you miss home?","你想家吗？"]]},{"npc":["Sometimes. The hardest time was when I got sick and didn't know what medicine to buy. Kevin at the pharmacy on Irving Street helped me so much. If you ever need help, go see him.","有时候会。最难的一次是我生病了，不知道该买什么药。Irving 街药房的 Kevin 帮了我好大的忙。你哪天要是需要帮忙，就去找他。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/dev_club_code_2.mp4","poster":"https://img.heyvoyo.com/clips/dev_club_code_2.webp","where":"美国 · 联合办公空间","why":"她和同事赶工的就是这样的开放式办公室","by":"fauxels","url":"https://www.pexels.com/video/3252423/"},"face":{"s":4,"h":"long","hc":"black","t":"hoodie","tc":"#c2453a","a":["badge"],"e":"grin","bgs":"office","prop":"laptop"}},"kevin":{"nm":"Kevin","av":"🧑🏻‍⚕️","job":"日落区药房的药剂师 · 30 岁","x":40,"y":180,"now":[["I said the same thing all day: twice a day, with food.","今天一整天都在说同一句：一天两次，吃饭时一起吃。"],["So many coughs this week. Everyone wants cold medicine.","这周咳嗽的人特别多，人人都来买感冒药。"],["I helped my grandma at the bakery on Saturday. Her egg tarts sold out before lunch.","周六去奶奶的面包店帮忙。她的蛋挞还没到中午就卖光了。"],["An old man came in who only speaks Cantonese. Good thing I do too!","今天来了个只会说粤语的老伯。还好我也会！"]],"story":"他小时候在唐人街奶奶的面包店楼上长大，放学就趴在柜台后面写作业。他当药剂师，是因为小时候常帮奶奶看药瓶上的英文。现在好多老街坊还是只找他问药。","ties":{"priya":"常来药房的客人，她刚来时生病，是他帮的忙","may":"他奶奶"},"next":"may","chat":[{"npc":["Hi there, how can I help you? Oh, Priya told you about me? That's nice of her.","你好，有什么能帮你的？哦，Priya 跟你说起过我？她人真好。"]},{"me":[["I have a sore throat. What can I take?","我嗓子疼。可以吃点什么？"],["Yes. I need something for a cold.","对。我想买点治感冒的药。"]]},{"npc":["Sure. Do you have a fever? No? Then try these, and drink lots of water. If you don't feel better in three days, see a doctor, okay?","好的。发烧吗？不发烧？那就试试这个，多喝水。三天还不见好，就去看医生，好吗？"]},{"me":[["Thank you so much. Are you from San Francisco?","太谢谢了。你是旧金山人吗？"],["Thanks! Any good food you'd recommend?","谢谢！有什么好吃的推荐吗？"]]},{"npc":["I grew up here! My grandma May has a bakery in Chinatown, and I lived upstairs. Go try her egg tarts. Best in the city, and I'm not just saying that because she's my grandma.","我就是在这儿长大的！我奶奶 May 在唐人街开面包店，我小时候住在楼上。去尝尝她的蛋挞，全城最好吃。我可不是因为她是我奶奶才这么说的。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/med_club_pharmacy_4.mp4","poster":"https://img.heyvoyo.com/clips/med_club_pharmacy_4.webp","where":"手边的一板药（拍摄地不详）","why":"他每天都要跟人讲清楚这样的药怎么吃","by":"Tima Miroshnichenko","url":"https://www.pexels.com/video/7033928/"},"face":{"s":2,"h":"side","hc":"black","t":"shirt","tc":"#ffffff","a":["glasses","badge"],"ac":{"badge":"#2a8c5a"},"e":"calm","bgs":"pharmacy","prop":"pills"}},"may":{"nm":"May","av":"👵🏻","job":"唐人街面包店的老板 · 72 岁","x":170,"y":160,"now":[["Up before the sun to make egg tarts, same as every day.","天还没亮就起来做蛋挞，天天都这样。"],["My grandson Kevin helped out on Saturday. He worked the counter all day and ate half my pork buns!","孙子 Kevin 周六来帮忙。在柜台忙了一天，我的叉烧包被他吃了一半！"],["So many tourists this week, and not enough chairs. Everyone wants a photo with the egg tarts!","这周游客好多，椅子都不够坐。人人都要跟蛋挞合影！"],["Dim sum with Linda again on Sunday. After all these years, she still can't use chopsticks!","周日又跟 Linda 去饮茶了。认识这么多年，她筷子还是用不好！"]],"story":"她二十岁从香港来到旧金山，跟丈夫在唐人街开了这家面包店。丈夫走了以后，大家都劝她把店卖了，她不肯。她说：「街坊每天早上要来买面包，我关了门，他们去哪儿买？」","ties":{"kevin":"她孙子","diego":"每天休息时来买蛋挞的缆车司机","linda":"认识几十年的老朋友，每周日一起饮茶"},"next":"linda","chat":[{"npc":["Come in, come in! You look hungry. Kevin sent you, didn't he? That boy tells everyone about my egg tarts.","进来进来！看你饿的。是 Kevin 让你来的吧？那孩子见人就夸我的蛋挞。"]},{"me":[["He did! Two egg tarts, please.","是他！要两个蛋挞。"],["Yes! He said they're the best in the city.","对！他说是全城最好吃的。"]]},{"npc":["Here, fresh from the oven. Careful, they're hot! I've made these every morning for almost fifty years.","给，刚出炉的。小心烫！差不多五十年了，我每天早上都做。"]},{"me":[["Wow, fifty years! Do you ever take a day off?","哇，五十年！你休息吗？"],["They're amazing! What do you do when you're not baking?","太好吃了！不做点心的时候你干什么？"]]},{"npc":["Sundays! I close the shop and go for dim sum with my old friend Linda. She lives in the Mission and has the friendliest dog. Go visit her. She knows everyone on her street.","周日呀！我关了店，跟老朋友 Linda 去饮茶。她住在教会区，养了一只特别亲人的狗。去找她坐坐吧，她那条街上的人她全认识。"]}],"face":{"s":2,"h":"curly","hc":"grey","t":"apron","tc":"#c6423b","t2":"#f2e8d8","a":["glasses"],"o":1,"e":"grin","bg":"#fbe6d6","bgs":"bakery","prop":"bread"}},"linda":{"nm":"Linda","av":"👵🏼","job":"教会区的退休小学老师 · 74 岁","x":50,"y":110,"now":[["Early walk in the park with Biscuit. He chased a squirrel and lost, as always.","一大早带 Biscuit 去公园走了一圈。它又去追松鼠，又没追上。"],["The fog rolled in fast this afternoon, so I made a big pot of soup.","下午雾一下子就上来了，我就煮了一大锅汤。"],["Alex from upstairs fixed my phone. Young people are so clever!","楼上的 Alex 帮我把手机弄好了。年轻人真聪明！"],["This street has changed so much since I moved in. New faces, new shops. But the hill is still the same.","我搬来以后，这条街变了好多，新面孔，新店铺。只有这个坡还是老样子。"]],"story":"她在这栋维多利亚式的老房子里住了快五十年，教了一辈子小学。房子早就很值钱了，有人出高价想买，她都没卖，而是把楼上便宜租给刚来旧金山的年轻人。现在住在楼上的，就是 Alex。","ties":{"may":"几十年的老朋友，每周日一起饮茶","alex":"住在她家楼上的租客"},"next":"alex","chat":[{"npc":["Oh, hello! May called and said a nice young person was coming. Don't mind Biscuit, he just wants to say hi.","哦，你好！May 打电话说有个不错的年轻人要来。别管 Biscuit，它就是想跟你打个招呼。"]},{"me":[["He's so cute! How old is he?","它好可爱！几岁了？"],["Hi, Linda! May says you know everyone here.","你好 Linda！May 说这儿的人你全认识。"]]},{"npc":["Biscuit is ten, but he acts like a puppy. And me? I've lived on this street for almost fifty years. I taught half the kids around here!","Biscuit 十岁了，还跟小狗似的。我呢，在这条街上住了快五十年，这一片一半的孩子都是我教过的！"]},{"me":[["That's amazing. Has the neighborhood changed a lot?","太了不起了。这一片变化大吗？"],["Do you live here by yourself?","你一个人住吗？"]]},{"npc":["Well, lots of my old neighbors have moved away. But I'm never lonely. A young designer named Alex lives upstairs. She takes those driverless cars everywhere! Go knock on her door. She'll tell you all about them.","老邻居搬走了不少。不过我从来不孤单。楼上住着个年轻的设计师，叫 Alex，去哪儿都坐那种没人开的车！去敲敲她的门吧，她会跟你好好讲讲。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/pet_club_walk_2.mp4","poster":"https://img.heyvoyo.com/clips/pet_club_walk_2.webp","where":"洛杉矶 · 公园","why":"她每天早上带 Biscuit 去的就是这样的公园","by":"RDNE Stock project","url":"https://www.pexels.com/video/7515922/"},"face":{"s":1,"h":"bob","hc":"white","t":"cardigan","tc":"#5b8a7a","t2":"#fff","a":["rglasses","pearls"],"o":1,"e":"calm","bg":"#e6f0ea","bgs":"hills","prop":"teacup"}}}},"singapore":{"zh":"新加坡","en":"Singapore","ll":[103.8198,1.3521],"r_km":25,"start":["weiling","uncletan"],"order":["weiling","raj","priya","siti","junhao","uncletan","joy","weijie","lena","hafiz"],"people":{"weiling":{"nm":"Wei Ling","av":"👩🏻‍💼","job":"樟宜机场值机柜台的地勤 · 30 岁","x":50,"y":60,"now":[["Early shift at Changi again. The first flight leaves at six, so people start queuing at four.","又是樟宜机场的早班。第一班飞机六点走，四点就有人来排队了。"],["A family missed their flight yesterday. I got them seats on the next one, and their little girl gave me a drawing!","昨天有一家人误了飞机，我帮他们换到了下一班。他们的小女儿还送了我一张画！"],["Finally a day off. I'm going for a run at East Coast Park with Hafiz's group.","终于休息一天。要去东海岸公园，跟 Hafiz 的跑团一起跑步。"],["My manager asked if I'd like to train the new staff. I said yes. A bit nervous!","经理问我愿不愿意带新人，我答应了。有点紧张！"]],"story":"她一天要说几百遍「请出示护照」，最记得的却是一位八十岁的阿嬷：第一次一个人坐飞机，去澳洲看孙子。那天 Wei Ling 下了班没走，一路陪她走到登机口。","ties":{"raj":"上早班时地铁还没开，她常坐 Raj 的德士去机场","hafiz":"Hafiz 跑团最早的那批人，跑完总抢着请大家喝椰子水","lena":"Lena 第一次回德国过圣诞，行李超重，是她在柜台帮着重新装的；后来在跑团又碰上了"},"next":"raj","chat":[{"npc":["Good morning! Passport, please. Where are you flying today?","早上好！请出示护照。今天飞哪儿？"]},{"me":[["I'm not flying, actually. I just wanted to say hi!","其实我不坐飞机，就是想来打个招呼！"],["Can I ask what your job is like?","能问问你的工作是什么样的吗？"]]},{"npc":["Wah, that's a first! I check in hundreds of people a day, and almost everyone asks the same thing: can I have a window seat?","哇，头一回遇到！我一天给几百个人办值机，几乎人人都问同一句：能换个靠窗的位子吗？（Wah：新加坡人常说的感叹）"]},{"me":[["Do you use other languages at work?","你上班会用别的语言吗？"],["What's the hardest part of your job?","你的工作最难的是什么？"]]},{"npc":["Every day I use English, Chinese and a bit of Malay. And the hardest part is the early start! The trains aren't running yet, so I often take a taxi. Talk to Raj, my usual driver. He's been driving for over twenty years and he loves a good chat.","我每天都要说英语、中文，还有一点马来语。最难的是起得早！那时候地铁还没开，我常打车去。去找 Raj 聊聊吧，我常坐他的车。他开了二十多年，特别爱聊天。"]}],"npc":"weiling","clip":{"src":"https://img.heyvoyo.com/clips/see_world_checkin_0.mp4","poster":"https://img.heyvoyo.com/clips/see_world_checkin_0.webp","by":"LayG Traveller","url":"https://www.pexels.com/video/38274409/","where":"新加坡 · 樟宜机场航站楼，清晨","why":"这是她常在的那种地方：樟宜机场的航站楼"},"face":{"s":2,"h":"bun","hc":"black","t":"uniform","tc":"#2a3f6b","t2":"#fff","a":["scarf","badge"],"ac":{"scarf":"#c0392b"},"e":"grin","bgs":"airport","prop":"passport"}},"raj":{"nm":"Raj","av":"👨🏾","job":"开了二十二年德士（新加坡人这么叫出租车）· 58 岁","x":160,"y":40,"now":[["Waiting at the airport taxi stand. Three planes just landed, so the queue is moving fast.","在机场的出租车站等客。刚落地三班飞机，队伍走得很快。"],["It rained so hard on Tuesday. Everyone in Singapore wanted a taxi at the same time.","周二雨下得好大，全新加坡的人好像同时都要打车。"],["My daughter Priya cooked dinner for me. She says I eat too much chicken rice.","女儿 Priya 给我做了晚饭。她说我鸡饭吃得太多了。"],["I took Sunday off and drove my wife to the temple in Little India. No meter running!","周日休息，开车带老婆去小印度的庙里。今天不打表！"]],"story":"年轻时在船厂干了十年，船厂关门后才开德士。车里一直放着一小瓶茉莉花，是女儿 Priya 第一次领工资那天买给他的。花换了好多回，瓶子一直没换。","ties":{"weiling":"常在凌晨送她去机场上早班","uncletan":"十五年来，几乎天天中午去他的摊子吃鸡饭","priya":"他的女儿"},"next":"priya","chat":[{"npc":["Hello! You're Wei Ling's friend, right? She told me about you. Where to?","你好！你是 Wei Ling 的朋友吧？她跟我说起过你。去哪儿？"]},{"me":[["Chinatown, please. How long will it take?","去牛车水，谢谢。要多久？"],["Hi Raj! Chinatown, please. Can we chat on the way?","嗨 Raj！去牛车水，谢谢。路上能跟你聊聊吗？"]]},{"npc":["About twenty minutes if there's no traffic. And of course we can chat. Sitting alone in the car all day is very sian.","不堵车的话二十分钟左右。当然可以聊，一个人在车里坐一整天，很 sian 的。（sian：新加坡说法，闷、没劲）"]},{"me":[["How long have you been a taxi driver?","你开出租车多久了？"],["Do you have any kids?","你有孩子吗？"]]},{"npc":["I've been driving for twenty-two years, and I have one daughter, Priya. She's a nurse at a clinic in Toa Payoh. Go and say hi to her. She knows every auntie and uncle in the neighbourhood.","我开了二十二年车，有一个女儿，叫 Priya，在大巴窑的诊所当护士。去跟她打个招呼吧，那一带的阿姨、阿伯她全认识。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/people_singapore_raj.mp4","poster":"https://img.heyvoyo.com/clips/people_singapore_raj.webp","where":"新加坡 · 白天的大街，车来车往，远处是市中心的高楼","why":"他开了二十二年德士，天天跑的就是这样的路","by":"CK Seng","url":"https://www.pexels.com/video/bustling-street-with-singapore-skyline-32212990/"},"face":{"s":5,"h":"short","hc":"salt","t":"shirt","tc":"#cfe3f0","b":"mous","o":1,"e":"grin","bgs":"hdb","prop":"wheel"}},"priya":{"nm":"Priya","av":"👩🏽‍⚕️","job":"大巴窑社区诊所的护士 · 31 岁","x":280,"y":50,"now":[["Busy morning at the clinic. So many people have a cough this week.","诊所的早上很忙，这周咳嗽的人特别多。"],["A tourist came in with a bad sunburn. I gave her some cream and told her: hat, shade and water!","有个游客晒伤得很厉害来看病。我给她拿了药膏，叮嘱她：戴帽子，待在阴凉处，多喝水！"],["Siti's blood sugar is much better this month. I was so happy for her.","Siti 这个月的血糖好多了，我真替她高兴。"],["Dad finally agreed to have a health check. It only took me three years!","我爸终于肯来做体检了。我只花了三年就劝动了他！"]],"story":"小时候常坐在爸爸的德士后座写作业。十二岁那年爸爸半夜发高烧住院，一个护士陪了她一整夜，她就决定以后也当护士。现在诊所里要是有老人一个人来看病，她总会多陪着说几句话。","ties":{"raj":"她爸爸","siti":"每个月来诊所量血糖的熟面孔"},"next":"siti","chat":[{"npc":["Hi there! Are you the person who took my dad's taxi? He called me right after. Are you feeling okay? This heat is no joke.","你好！你就是坐我爸车的那个人吧？你一下车他就给我打电话了。你身体还好吗？这么热的天，可别大意。"]},{"me":[["I'm fine, thanks! Just a bit tired from the heat.","我挺好，谢谢！就是被热得有点累。"],["Yes, I'm okay. I just wanted to meet you.","嗯，我没事，就是想来认识你一下。"]]},{"npc":["The heat gets everyone. Drink lots of water, okay? Lots of people come in feeling dizzy because they forget to drink.","这么热，谁都受不了。多喝水，好吗？好多人来这儿，就是因为忘了喝水，头晕。"]},{"me":[["What do people usually come here for?","大家一般来这儿看什么？"],["Do you know a lot of people around here?","这一带的人你认识很多吗？"]]},{"npc":["Oh yes, lots of regulars! People come in for coughs, fevers, check-ups. Siti lives in the block across the road. She makes amazing kueh, little Malay cakes. Go and say hi, and tell her I sent you.","熟面孔可多了！大家来看咳嗽、发烧，做体检。Siti 就住在马路对面那栋组屋，她做的 kueh（马来小糕点）特别好吃。去跟她打个招呼，就说是我让你来的。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/people_singapore_priya.mp4","poster":"https://img.heyvoyo.com/clips/people_singapore_priya.webp","where":"诊所前台，护士在接待两个年轻人（拍摄地没写）","why":"她在诊所的一天，就是这样一个接一个地接待病人","by":"Pavel Danilyuk","url":"https://www.pexels.com/video/a-couple-an-appointment-from-a-nurse-6998342/"},"face":{"s":5,"h":"braidbun","hc":"black","t":"scrubs","tc":"#7fb3d5","a":["tag","ear"],"e":"grin","bgs":"clinic","prop":"clipboard"}},"siti":{"nm":"Siti","av":"🧕🏽","job":"住在大巴窑组屋，在家做马来糕点接订单 · 52 岁","x":320,"y":150,"now":[["Up at five to steam kueh. Twelve boxes for a wedding this Saturday!","五点就起来蒸糕。这周六有场婚礼，订了十二盒！"],["The wedding went well. The bride's mother asked for my number.","婚礼很顺利，新娘的妈妈还要了我的电话。"],["Hafiz says I should sell online. I don't know how, but he's teaching me.","Hafiz 说我该在网上卖。我不会弄，他在教我。"],["My first online order came in! A lady from Jurong. So far away, and she still wants my kueh.","第一张网上订单来了！是裕廊的一位太太。那么远，还是要订我的糕。"]],"story":"丈夫走得早，她靠在家做糕把 Hafiz 拉扯大。楼里的邻居有华人也有印度人：开斋节她给每家送一盒糕，到了农历新年和屠妖节，家里就堆满了邻居的回礼。","ties":{"priya":"诊所的护士，每个月帮她量血糖","hafiz":"她的儿子","junhao":"住在隔壁，她看着长大的孩子"},"next":"junhao","chat":[{"npc":["Hello! Oh, Priya sent you? Come in, come in. Have you makan already?","你好！哦，是 Priya 让你来的？进来进来。吃过了吗？（makan：马来语的「吃」，新加坡人都这么说）"]},{"me":[["Not yet. Something smells really good!","还没呢。好香啊！"],["Yes, thank you. Priya says you make great kueh.","吃过了，谢谢。Priya 说你做的糕特别好吃。"]]},{"npc":["Here, try this one. It's kueh lapis. Nine layers, and I steam them one by one. It takes the whole morning.","来，尝尝这个，是九层糕。一共九层，一层一层地蒸，要花一整个早上。"]},{"me":[["Wow, it's soft and sweet. Do you sell these?","哇，又软又甜。这个你卖吗？"],["Do you know your neighbours well?","你跟邻居熟吗？"]]},{"npc":["I take orders from home. And my neighbours are like family! Jun Hao next door, I watched him grow up. He's at university now, very clever. Go and talk to him. He loves meeting new people.","我在家接订单。邻居嘛，跟一家人一样！隔壁的 Jun Hao 是我看着长大的，现在在读大学，可聪明了。去跟他聊聊吧，他最喜欢认识新朋友。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/people_singapore_siti.mp4","poster":"https://img.heyvoyo.com/clips/people_singapore_siti.webp","where":"新加坡 · 从空中看城区，老楼和新楼挤在一起","why":"新加坡大多数人住在这样的高楼里，Siti 家的组屋也是","by":"Maksim Romashkin","url":"https://www.pexels.com/video/drone-video-of-singapore-cityscape-14372138/"},"face":{"s":4,"h":"hijab","hc":"#2e8b6f","t":"tee","tc":"#f2c8d2","o":1,"e":"grin","bg":"#fdf0e0","bgs":"kitchen","prop":"cake"}},"junhao":{"nm":"Jun Hao","av":"🧑🏻‍🎓","job":"读大四商科的学生，周末在爷爷的鸡饭摊帮忙 · 23 岁","x":290,"y":260,"now":[["Exams start soon. I'm studying at the void deck because it's cooler than my room.","快考试了。我在组屋楼下的空地复习，比房间里凉快。（void deck：组屋底层空出来的公共空间）"],["Took Saturday off from studying to help Grandpa at the stall. My arms hurt from chopping chicken.","周六没复习，在爷爷摊上帮了一整天忙，剁鸡剁得胳膊好酸。"],["Grandpa and I argued again. I want to put a QR code on the stall, but he says cash is fine.","又跟爷爷争起来了。我想在摊子上放个付款码，他说收现金就够了。"],["Grandpa let me try. Ten people paid by QR on the first day. He just said, 'Hmm, not bad.'","爷爷让我试试了。第一天就有十个人扫码付款。他只说了一句：「嗯，还行。」"]],"story":"大家都以为他毕业后会去银行上班，连爷爷也这么想。其实每个周六收摊后，他都偷偷跟爷爷学煮那锅鸡饭，因为爷爷从来没把做法写下来过。","ties":{"uncletan":"他爷爷，周末在爷爷的摊子上帮忙","siti":"隔壁的阿姨，考试那几周常给他送糕"},"next":"uncletan","chat":[{"npc":["Hey! Auntie Siti texted me that you were coming. Sorry about the mess, my exams are coming up.","嘿！Siti 阿姨发消息说你要来。不好意思，乱糟糟的，我快考试了。"]},{"me":[["No problem. What are you studying?","没关系。你学什么的？"],["Good luck with your exams!","考试加油！"]]},{"npc":["Thanks! Business, final year. My parents want me to work in a bank. My grandpa wants me to take over his stall. Me? Still deciding lah.","谢谢！读商科，大四了。我爸妈想让我去银行，我爷爷想让我接他的摊子。我自己嘛？还没想好啦。（lah：新加坡说法，放在句尾，语气更随意）"]},{"me":[["What does your grandpa sell?","你爷爷卖什么？"],["That's a hard choice.","这个选择不容易。"]]},{"npc":["My grandpa has sold chicken rice at the hawker centre for forty years. We don't always agree, but his chicken rice is the best. Everyone calls him Uncle Tan. Go and try it, and tell him his grandson sent you.","我爷爷在小贩中心卖了四十年鸡饭。我们俩常常意见不合，但他的鸡饭是最好吃的。大家都叫他 Uncle Tan。去尝尝，跟他说是他孙子让你来的。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/people_singapore_junhao.mp4","poster":"https://img.heyvoyo.com/clips/people_singapore_junhao.webp","where":"新加坡 · 巴耶利峇广场，地铁站旁边的空地","why":"新加坡的学生下了课，常在这样的地方等车、碰头","by":"saw sing","url":"https://www.pexels.com/video/subway-mrt-station-plq-19270692/"},"face":{"s":2,"h":"fringe","hc":"black","t":"tee","tc":"#2a7aa8","a":["glasses"],"e":"grin","bgs":"hawker","prop":"rice"}},"uncletan":{"nm":"Uncle Tan","av":"👴🏻","job":"在大巴窑小贩中心卖了四十年鸡饭 · 68 岁","x":180,"y":170,"now":[["Up at four to cook the chicken. By eleven, the queue is already long.","四点起来煮鸡。到十一点，队伍就排得老长了。"],["Priya told me to give her dad less rice. So I did, and Raj complained!","Priya 让我给她爸少盛点饭。我照做了，Raj 还抱怨！"],["Jun Hao wants to put a QR code on my stall. Young people, always want to change things.","Jun Hao 想在我摊上放个付款码。年轻人，老想改这改那。"],["Okay lah, the QR code is quite useful. Don't tell Jun Hao I said that.","好啦，扫码还挺方便的。别跟 Jun Hao 说是我说的。（lah：新加坡说法，放在句尾，语气更随意）"]],"story":"四十年前跟师傅学手艺，被骂了整整一年，师傅才让他碰那锅饭。他从不轻易涨价，因为有些老顾客一个人住，一天就靠这一盒鸡饭。谁要不要辣、要不要鸡皮，他全记得。","ties":{"raj":"十五年的老顾客，天天中午来","junhao":"他的孙子","joy":"每个周六来买四份，给孩子的那两份他总多加黄瓜"},"next":"joy","chat":[{"npc":["Next! Oh, you're Jun Hao's friend? He told me. What would you like? One chicken rice?","下一位！哦，你是 Jun Hao 的朋友？他跟我说了。要什么？一份鸡饭？"]},{"me":[["Yes, one chicken rice, please. Not too spicy.","对，一份鸡饭，谢谢。不要太辣。"],["What do you recommend?","你推荐什么？"]]},{"npc":["Chicken rice is all I sell! Steamed chicken, rice cooked in chicken stock, and my own chilli sauce. Forty years, same recipe. Here, try some.","我就只卖鸡饭！白切鸡、鸡汤煮的饭，再加我自己做的辣椒酱。四十年，一直是这个做法。来，尝尝。"]},{"me":[["This is delicious! How do you make the rice?","太好吃了！这饭是怎么做的？"],["So good! Do you have many regulars?","太好吃了！你熟客多吗？"]]},{"npc":["Thank you! The recipe is my secret. But my regulars, I know them all. Every Saturday, Joy buys four boxes for the family she works for, with extra cucumber for the kids. Go and meet her. She's very kind, and she sees Singapore from a different side.","谢谢！做法是秘密。不过熟客我个个都认识。Joy 在一户人家帮忙，每个周六都来给他们买四份，给孩子的那两份多加黄瓜。去认识一下她吧，她人很好，她看到的新加坡跟别人不太一样。"]}],"face":{"s":2,"h":"thin","hc":"grey","t":"tee","tc":"#ececec","o":1,"e":"calm","bg":"#efe6d6","bgs":"hawker","prop":"cleaver"}},"joy":{"nm":"Joy","av":"👩🏽","job":"从菲律宾来，在 Wei Jie 家做了八年住家帮佣 · 39 岁","x":160,"y":290,"now":[["Saturday morning. I bought chicken rice for the family, then took the kids swimming.","周六早上。给家里买了鸡饭，然后带孩子们去游泳。"],["Sunday with my friends at Orchard Road. We sat, ate and talked for six hours!","周日跟朋友们在乌节路，坐着、吃着、聊着，一待就是六个小时！"],["Video call with my daughter in Manila. She got into university! I cried a little.","跟在马尼拉的女儿视频。她考上大学了！我哭了一会儿。"],["Wei Jie's family bought a little cake for my daughter's good news. The kids wrote on it: 'Congrats, Ate!'","Wei Jie 一家为我女儿的好消息买了个小蛋糕。孩子们在上面写：「恭喜，Ate！」（Ate：菲律宾话的「姐姐」，孩子们这么叫她）"]],"story":"她在新加坡带大了别人家的两个孩子，自己的女儿却一直是外婆在菲律宾带。工资一大半寄回家。她说最难的不是想家，是女儿上台领奖那天，她只能在手机上看。","ties":{"weijie":"她照顾的那一家的爸爸，她在他家八年了","uncletan":"每个周六都去他摊上买鸡饭"},"next":"weijie","chat":[{"npc":["Hello! Uncle Tan said you might come by. Sorry, I have to watch the kids while we talk. Ethan, slow down!","你好！Uncle Tan 说你可能会来。不好意思，我得一边聊一边看着孩子。Ethan，慢点跑！"]},{"me":[["No problem! Are these the kids you look after?","没事！这就是你照顾的孩子吗？"],["Hi Joy! How long have you lived in Singapore?","嗨 Joy！你在新加坡住多久了？"]]},{"npc":["I've been with this family for eight years. These two are theirs. When I came, the little one was a baby. Now he's eight and he runs everywhere!","我在这家八年了，这两个就是他们家的孩子。我刚来的时候，小的那个还是个婴儿，现在都八岁了，满地跑！"]},{"me":[["Do you miss home?","你想家吗？"],["What do you do on your day off?","你休息的时候做什么？"]]},{"npc":["I miss home every day. But on Sundays I meet my friends at Orchard Road, and that helps a lot. Oh, here comes Wei Jie, the kids' dad. Talk to him. He used to be a teacher, so he explains everything very clearly.","每天都想家。不过周日能在乌节路见朋友，好受多了。哦，孩子们的爸爸 Wei Jie 来了。跟他聊聊吧，他以前当过老师，什么都讲得特别清楚。"]}],"face":{"s":3,"h":"pony","hc":"black","t":"tee","tc":"#7ab0a0","e":"calm","bgs":"home","prop":"phone"}},"weijie":{"nm":"Wei Jie","av":"👨🏻‍💼","job":"把学习软件卖给国际学校的销售，以前教了八年数学 · 38 岁","x":60,"y":260,"now":[["Three school visits this week: two in Singapore and one in Kuala Lumpur.","这周要跑三所学校：两所在新加坡，一所在吉隆坡。"],["A principal asked me something I couldn't answer. I said, 'Let me find out for you.' Better than guessing.","有位校长问了个我答不上来的问题。我说：「我问清楚了再告诉您。」总比瞎猜好。"],["Joy's daughter got into university! We're all so proud of her.","Joy 的女儿考上大学了！我们全家都替她骄傲。"],["Back from KL. The kids made me promise: no work this Sunday, only the beach.","从吉隆坡回来了。孩子们逼我保证：这周日不许工作，只去海边。"]],"story":"教了八年数学，最难忘的是一个怕数学怕到哭的女孩，后来考了满分。转做销售以后，他常对学校说「这个功能你们可能用不上」，没想到反而签下了更多学校。","ties":{"joy":"在他家帮忙八年，两个孩子都是她带大的","lena":"同一个公寓的邻居，常在楼下泳池碰到"},"next":"lena","npc":"weijie","chat":[{"npc":["Hi! Joy said you were asking about life in Singapore. Happy to help. What would you like to know?","你好！Joy 说你在打听新加坡的生活。乐意帮忙。你想知道什么？"]},{"me":[["What do you do for work?","你是做什么工作的？"],["Is it true that kids here study really hard?","听说这儿的孩子学习特别拼，是真的吗？"]]},{"npc":["I sell learning software to international schools. Before that, I taught maths for eight years. So I know how hard kids study here! Lots of them have tuition after school.","我把学习软件卖给国际学校，之前教了八年数学。所以这儿的孩子有多拼，我最清楚！很多人放学后还要去补习。"]},{"me":[["Do you miss teaching?","你想念教书吗？"],["Is sales very different from teaching?","做销售跟教书差别大吗？"]]},{"npc":["A little. But honestly, I still teach! Just principals now, not kids. Hey, my neighbour Lena moved here from Germany three years ago. Talk to her about life as a newcomer. I'll text her now, can?","有一点。不过说真的，我还在教书！只是现在教的是校长，不是小孩。对了，我的邻居 Lena 三年前从德国搬来。问问她刚来新加坡是什么感觉。我现在给她发消息，好吗？（can：新加坡说法，「行吗」）"]}],"face":{"s":2,"h":"side","hc":"black","t":"shirt","tc":"#dfe8f2","a":["glasses"],"e":"grin","bgs":"office","prop":"laptop"}},"lena":{"nm":"Lena","av":"👩🏼","job":"从德国来，在航运公司排船期 · 34 岁","x":40,"y":160,"now":[["Busy week at the port office. Three ships are late because of a storm at sea.","港口办公室这周很忙。海上起了风暴，三艘船都晚到了。"],["All the ships finally arrived. I can sleep again!","船总算全到了，我终于能睡个好觉了！"],["Ran with the run club on Saturday. So hot, even at seven in the morning!","周六跟跑团跑步。早上七点就热得不行！"],["My mum is visiting from Hamburg next week. The first place I'll take her is a hawker centre.","我妈下周从汉堡来看我。我带她去的第一个地方，就是小贩中心。"]],"story":"刚来的那个月，她一个朋友都没有，下了班就在家看德国电视。后来进了跑团，认识了一大群人。现在她说话会不自觉地带个 lah，回汉堡时被老朋友笑了好久。","ties":{"weijie":"同一个公寓的邻居，常在楼下泳池碰到","hafiz":"跑团的组织者，她刚来时第一个交到的朋友","weiling":"第一次回德国时，Wei Ling 在柜台帮她重新装了超重的行李；后来在跑团又碰上了"},"next":"hafiz","chat":[{"npc":["Hi! You must be the person Wei Jie told me about. Nice to meet you, I'm Lena.","嗨！你就是 Wei Jie 说的那个人吧？很高兴认识你，我是 Lena。"]},{"me":[["Nice to meet you too! How do you like Singapore?","我也很高兴认识你！你觉得新加坡怎么样？"],["Hi Lena! What brought you to Singapore?","嗨 Lena！你怎么会来新加坡？"]]},{"npc":["I came for work, and now I love it! I plan ship schedules for a shipping company. Singapore is one of the busiest ports in the world, so it's perfect for my job. But the first month was lonely.","我是为工作来的，现在很喜欢这儿！我在一家航运公司排船期。新加坡是世界上最繁忙的港口之一，干我这行再合适不过了。不过刚来的第一个月挺孤单的。"]},{"me":[["How did you make friends?","你是怎么交到朋友的？"],["What helped you feel at home?","后来是什么让你有了家的感觉？"]]},{"npc":["I joined a run club! Hafiz runs it, every Saturday morning at East Coast Park. Come with us lah! Hafiz is so friendly, you'll know everyone after one run.","我加了一个跑团！是 Hafiz 组织的，每周六早上在东海岸公园。跟我们一起来嘛！Hafiz 特别热情，跑一次你就谁都认识了。（lah：她跟新加坡朋友学的说法，放在句尾，语气更随意）"]}],"clip":{"src":"https://img.heyvoyo.com/clips/people_singapore_lena.mp4","poster":"https://img.heyvoyo.com/clips/people_singapore_lena.webp","where":"新加坡 · 城区和远处的货柜码头，黄昏","why":"她排船期的那些船，就停在这样的码头","by":"Az Horsley","url":"https://www.pexels.com/video/time-lapse-footage-of-a-busy-city-and-sea-harbor-6414069/"},"face":{"s":1,"h":"pony","hc":"blonde","t":"tee","tc":"#2f6db5","e":"grin","bgs":"port","prop":"clipboard"}},"hafiz":{"nm":"Hafiz","av":"🏃🏽‍♂️","job":"健身教练，周六在东海岸公园组织免费跑团 · 27 岁","x":120,"y":110,"now":[["Saturday run at East Coast Park. Forty people today! Most of them came for the breakfast after.","周六在东海岸公园跑步，今天来了四十个人！一大半是冲着跑完的早餐来的。"],["I'm teaching Mum to sell her kueh online. She calls me every hour with a new question.","在教我妈在网上卖糕。她每隔一小时就打电话问个新问题。"],["Such a hot week. We moved the run to six in the morning. Nobody complained... okay, a few did.","这周太热了，我们把跑步改到早上六点。没人抱怨……好吧，有几个抱怨了。"],["Mum got her first online order! She's more excited than when I passed my exams.","我妈接到第一张网上订单了！比我当年考试及格时还激动。"]],"story":"中学时他是全班跑得最慢的，体育老师说他「没救了」。他为了争口气开始每天早上跑，结果跑上了瘾，后来当了健身教练。跑团一分钱不收，他说：「跑步本来就不该花钱。」","ties":{"siti":"他妈妈","lena":"跑团里第一个外国人，现在每周都来","weiling":"跑团最早的那批人，跑完总抢着请大家喝椰子水"},"next":"weiling","chat":[{"npc":["Hi! Lena's friend? Welcome! First time running with us? Don't worry lah, we go slowly. Nobody gets left behind.","嗨！Lena 的朋友？欢迎！第一次跟我们跑？别担心啦，我们跑得慢，不会丢下谁。（lah：新加坡说法，放在句尾，语气更随意）"]},{"me":[["Thanks! I'm not a very good runner, though.","谢谢！不过我跑得不太行。"],["How far do you usually run?","你们一般跑多远？"]]},{"npc":["Five kilometres along the sea. If you're tired, just walk. The real goal is breakfast after: roti prata and teh tarik!","沿着海边跑五公里。累了就走。真正的目标是跑完的早餐：印度煎饼配拉茶！"]},{"me":[["That sounds fun. Who comes to the run club?","听起来很好玩。都有谁来跑团？"],["Is it always this hot?","一直都这么热吗？"]]},{"npc":["Always hot, that's why we start early! All kinds of people come: teachers, students, even airport staff. See Wei Ling over there? She works at Changi Airport. Next time you fly, say hi to her at the check-in counter!","一直这么热，所以我们才起这么早！什么人都有：老师、学生，还有机场的人。看到那边的 Wei Ling 了吗？她在樟宜机场上班。下次你坐飞机，去值机柜台跟她打个招呼！"]}],"clip":{"src":"https://img.heyvoyo.com/clips/people_singapore_hafiz.mp4","poster":"https://img.heyvoyo.com/clips/people_singapore_hafiz.webp","where":"海边的城市公园，从空中往下看（拍摄地没写）","why":"他周六带着跑团跑的，就是这样的海边公园","by":"David Pickup","url":"https://www.pexels.com/video/aerial-view-of-coastal-urban-park-37231642/"},"face":{"s":4,"h":"crop","hc":"black","t":"jersey","tc":"#e86a33","t2":"#fff","a":["whistle"],"ac":{"whistle":"#222"},"e":"grin","bg":"#ffe6d6","bgs":"park","prop":"stopwatch"}}},"clip":{"src":"https://img.heyvoyo.com/clips/see_world_checkin_0.mp4","poster":"https://img.heyvoyo.com/clips/see_world_checkin_0.webp","by":"LayG Traveller","url":"https://www.pexels.com/video/38274409/","where":"新加坡 · 樟宜机场航站楼"}},"sydney":{"zh":"悉尼","en":"Sydney","ll":[151.2093,-33.8688],"r_km":40,"clip":{"src":"https://img.heyvoyo.com/clips/pet_club_vet_0.mp4","poster":"https://img.heyvoyo.com/clips/pet_club_vet_0.webp","where":"悉尼 · 环形码头，晴天的下午（远处是渡轮和游轮）","by":"Ray .","url":"https://www.pexels.com/video/20186333/"},"start":["ben","chloe"],"order":["ben","margaret","yu","chloe","priya","shane","nikos","jack","jiwoo","linh"],"people":{"ben":{"nm":"Ben","av":"👨🏼‍⚕️","job":"纽敦宠物诊所的兽医护士 · 31 岁","x":60,"y":70,"now":[["Busy week at the clinic. It's spring, so lots of puppies are coming in for their first vaccines.","诊所这周很忙。一到春天，好多小狗来打第一针疫苗。"],["Pepper found a new spot on the couch. In the sun, of course. Lazy dog.","Pepper 在沙发上找了个新位置，当然是晒得到太阳的地方。懒狗。"],["The waves were great this weekend. I was in the water by six.","这周末浪特别好，我六点就下水了。"],["It's getting hot. Please don't walk your dog on the footpath at lunchtime. It burns their feet!","天越来越热了。中午别带狗走人行道，地面会烫伤它们的脚！"]],"story":"Ben 小时候想当兽医，考了两次都没考上，只好先当兽医护士。干了七年，他反倒觉得这才最适合自己——他陪动物的时间比兽医还多。Pepper 是一只退役的赛狗，刚领回家时连楼梯都不敢走，是 Ben 一级一级陪着它学会的。","ties":{"margaret":"邻居，Margaret 家的老狗 Biscuit 一直在他们诊所看病","linh":"每天上班前去 Linh 的咖啡馆买一杯咖啡，常带着 Pepper"},"next":"margaret","chat":[{"npc":["G'day! Sorry, I've got dog hair all over me. Long day at the clinic.","你好！不好意思，我一身狗毛。今天在诊所忙了一整天。"]},{"me":[["No worries! Are you a vet?","没事！你是兽医吗？"],["Hi! What kind of animals do you see?","嗨！你们那儿都看什么动物？"]]},{"npc":["I'm a vet nurse. Mostly dogs and cats, but today someone brought in a lizard! It ate a bit too much.","我是兽医护士。主要是猫和狗，不过今天有人带来一只蜥蜴！它吃多了。"]},{"me":[["Do you have a pet yourself?","你自己养宠物吗？"],["That sounds like a fun job.","听起来这工作挺有意思的。"]]},{"npc":["I love it. And at home I've got my own dog, a greyhound called Pepper. Hey, you should meet my neighbour Margaret. She's lived in Newtown forever and knows everyone on our street.","我很喜欢。家里我自己也养了一只狗，是只灰猎犬，叫 Pepper。对了，你应该认识一下我的邻居 Margaret。她在纽敦住了大半辈子，我们这条街的人她都认识。"]}],"npc":"ben_vet","clip":{"src":"https://img.heyvoyo.com/clips/people_sydney_ben.mp4","poster":"https://img.heyvoyo.com/clips/people_sydney_ben.webp","where":"宠物诊所的候诊区（拍摄地没写）","why":"他上班的地方，就是这样的宠物诊所","by":"Hasan basri Yentekün","url":"https://www.pexels.com/video/modern-veterinary-clinic-waiting-area-40703704/"},"face":{"s":1,"h":"side","hc":"blonde","t":"scrubs","tc":"#2a8c8c","a":["tag"],"b":"stubble","e":"grin","bgs":"vet","prop":"pup"}},"margaret":{"nm":"Margaret","av":"👵🏼","job":"退休的小学老师 · 72 岁","x":70,"y":170,"now":[["The jacaranda outside my house is purple again. My favourite time of year.","我家门口的蓝花楹又开成一片紫了。一年里我最喜欢这时候。"],["Biscuit had his check-up with Ben. He's getting old, but he's doing fine.","Biscuit 去 Ben 那儿做了体检。它老了，不过身体还行。"],["Yu cooked dinner for me last night. Mapo tofu! Very spicy, but I loved it.","昨晚 Yu 给我做了晚饭，麻婆豆腐！辣得很，但我特别喜欢。"],["My grandkids are coming for Christmas, so I've already started on the pudding.","孙子孙女要来过圣诞，我已经开始做圣诞布丁了。"]],"story":"Margaret 教了三十多年小学，退休后觉得房子太空，就把一间房租给留学生。她只有一条规矩：每周一起吃一顿晚饭。住过她家的学生来自七个国家，每年圣诞都有人从世界各地给她寄卡片。","ties":{"ben":"邻居，Biscuit 的病都是在 Ben 那儿看的","linh":"每天早上去 Linh 的咖啡馆喝一杯 flat white、做填字游戏","yu":"Yu 租住在她家"},"next":"yu","chat":[{"npc":["Oh, hello! Ben said you might pop by. Come in, and mind the dog.","哦，你好呀！Ben 说你可能会过来坐坐。进来吧，小心别踩到狗。"]},{"me":[["Thank you! What a lovely house.","谢谢！这房子真好看。"],["Hi Margaret. How long have you lived here?","你好，Margaret。你在这儿住多久了？"]]},{"npc":["It's an old house. I've lived here for forty years! Newtown was very different back then. Now there are cafés everywhere. I don't mind, the coffee's good.","这房子可老了，我在这儿住了四十年！那时候的纽敦跟现在很不一样，现在到处都是咖啡馆。我倒不介意，咖啡挺好喝的。"]},{"me":[["Do you live here by yourself?","你一个人住吗？"],["Does your family live nearby?","你家里人住得近吗？"]]},{"npc":["My kids moved away, but I'm never lonely. I've got Biscuit, and a student called Yu rents my spare room. She's from Chengdu. Go and say hi to Yu. She'd love to practise her English.","孩子们都搬走了，不过我从来不寂寞。有 Biscuit 陪着，还有个叫 Yu 的学生租了我家空着的那间房，她是成都来的。去跟 Yu 打个招呼吧，她很想多练练英语。"]}],"face":{"s":1,"h":"bob","hc":"white","t":"cardigan","tc":"#d98aa4","t2":"#fff","a":["glasses","pearls"],"o":1,"e":"grin","bg":"#fbe7ee","bgs":"home","prop":"teacup"}},"yu":{"nm":"Yu","av":"👩🏻‍🎓","job":"成都来的护理专业留学生 · 21 岁","x":110,"y":260,"now":[["Exams are finally over! Margaret and I had hotpot at home to celebrate.","终于考完试了！我和 Margaret 在家吃火锅庆祝。"],["First day of my placement in the emergency department. I was so nervous I couldn't eat breakfast.","第一天去急诊科实习。我紧张得早饭都吃不下。"],["An old man called me 'love' today. Chloe says that's normal here. It just means he's being friendly.","今天有个老爷爷叫我 love。Chloe 说这在这儿很正常，就是对你友好。"],["My first Christmas in summer! Everyone's talking about going to the beach. It feels so strange.","第一次在夏天过圣诞！大家都在说要去海边，感觉好奇怪。"]],"story":"Yu 刚来的时候听不惯澳洲口音。第一次在超市，收银员问她「How ya going?」，她以为是问她去哪儿，回了一句「Home」。现在她拿这件事逗新来的同学。她想毕业后留在澳洲当护士，再把爸妈接过来看看海。","ties":{"margaret":"房东，每周一起吃一顿晚饭","chloe":"在 Chloe 的急诊科实习，是 Chloe 带她","jiwoo":"在图书馆的语言交换活动上认识的"},"next":"chloe","chat":[{"npc":["Hi! Margaret told me about you. Sorry, my English isn't perfect.","嗨！Margaret 跟我说起过你。不好意思，我英语说得不太好。"]},{"me":[["Your English is great! I'm learning too.","你英语很好啊！我也在学。"],["No worries. Where are you from?","没关系。你是哪里人？"]]},{"npc":["Thanks! I'm from Chengdu, and I'm studying nursing here. The hardest part isn't the English. It's all the medical words!","谢谢！我是成都人，在这儿学护理。最难的不是英语，是那一大堆医学词！"]},{"me":[["How do you remember all those words?","那么多词你怎么记？"],["Do you work in a hospital?","你在医院上班吗？"]]},{"npc":["I'm doing a placement in the emergency department, so I hear new words every day and write them down at night. Chloe looks after me there. She's amazing. Go and talk to Chloe, but maybe not on a Saturday night!","我在急诊科实习，每天都能听到新词，晚上回来记在本子上。在那儿是 Chloe 带我，她特别厉害。去找 Chloe 聊聊吧，不过最好别挑周六晚上！"]}],"clip":{"src":"https://img.heyvoyo.com/clips/people_sydney_yu.mp4","poster":"https://img.heyvoyo.com/clips/people_sydney_yu.webp","where":"医院病房，一格一格拉着帘子（拍摄地没写）","why":"她第一次去实习，进的就是这样的病房","by":"Mister Edits","url":"https://www.pexels.com/video/a-footage-inside-a-hospital-6151283/"},"face":{"s":2,"h":"pony","hc":"black","t":"scrubs","tc":"#7fb3d5","a":["tag"],"e":"grin","bgs":"campus","prop":"book"}},"chloe":{"nm":"Chloe","av":"👩🏼‍⚕️","job":"公立医院急诊室的护士 · 34 岁","x":190,"y":190,"now":[["Summer's nearly here. We had three jellyfish stings in one night!","快到夏天了。一个晚上就来了三个被水母蜇的！"],["Yu started her placement with us. She asks really good questions.","Yu 开始在我们这儿实习了。她问的问题都问在点子上。"],["Parkrun with Priya on Saturday morning, straight after a night shift. Not my best idea!","周六早上跟 Priya 去跑 parkrun，刚下夜班就去了。真不是个好主意！"],["I'm working on Christmas night this year, so I'm bringing a pavlova for the whole team.","今年圣诞节晚上要上班，我给全组带了一个奶油蛋白饼（pavlova）。"]],"story":"Chloe 家三代都是护士：外婆、妈妈，还有她。外婆当年在乡下的小医院，一个人管整个病房。夜班最累、病人一个接一个来的时候，Chloe 就想起外婆的话：先看最危险的那个，再一个一个来。","ties":{"jack":"Jack 是邦迪海滩的救生员，常把在海边受伤的人送到她们急诊","priya":"周六早上一起跑 parkrun","yu":"她带的实习护士"},"next":"priya","chat":[{"npc":["Hi there. Yu said you're lovely. I've got five minutes before my shift, so let's chat!","你好。Yu 说你人很好。我上班前还有五分钟，聊会儿吧！"]},{"me":[["Thanks! Is the emergency department busy?","谢谢！急诊科忙吗？"],["Hi Chloe. Do you always work nights?","你好，Chloe。你一直上夜班吗？"]]},{"npc":["I mostly work nights, and it's always busy. Saturday nights are crazy! People think we see whoever comes first. We don't. We see the sickest person first.","我大多上夜班，一直都很忙，周六晚上最疯。大家以为我们是先来先看，其实不是，是先看病得最重的。"]},{"me":[["How do you relax after a night shift?","下了夜班你怎么放松？"],["That sounds really stressful.","听起来压力好大。"]]},{"npc":["Running helps! On Saturday mornings I go running with my friend Priya. She's a software engineer, and she takes the ferry to work every day. Ask Priya about it. She loves that ferry.","跑步很管用！周六早上我会跟朋友 Priya 去跑步。她是做软件的，每天坐渡轮上班。你问问 Priya，她可喜欢那条渡轮了。"]}],"npc":"chloe_er","face":{"s":1,"h":"bun","hc":"brown","t":"scrubs","tc":"#1f3550","a":["steth","fob"],"e":"calm","bgs":"ward","prop":"clipboard"}},"priya":{"nm":"Priya","av":"👩🏽‍💻","job":"银行的软件工程师，住在曼利 · 33 岁","x":240,"y":110,"now":[["Saw dolphins from the ferry this morning! Everyone ran to one side to look.","今天早上在渡轮上看到海豚了！大家都跑到一边去看。"],["Our team is launching a new app next week, so it's been late nights all week.","我们组下周要上线一个新 app，这一周天天忙到很晚。"],["I beat my parkrun record by twenty seconds! Chloe says it's the new shoes.","parkrun 比我最好成绩快了二十秒！Chloe 说是新鞋的功劳。"],["My parents are visiting from Mumbai. Dad wants to see the Opera House every single day.","我爸妈从孟买来看我。我爸天天都想去看歌剧院。"]],"story":"Priya 来悉尼读研，毕业后找工作被拒了十几次，有一阵差点回孟买。后来她搬到曼利，每天坐半小时渡轮上班。她说那半小时是她一天里最安静的时候，好多写代码的点子都是在船上想出来的。","ties":{"chloe":"周六早上一起跑 parkrun","shane":"每天坐 Shane 那条渡轮上班，早上总跟他打招呼"},"next":"shane","chat":[{"npc":["Hey! You must be Chloe's friend. Want to walk to the wharf with me? My ferry leaves in ten minutes.","嘿！你就是 Chloe 的朋友吧。跟我一起走去码头？我的渡轮还有十分钟就开了。"]},{"me":[["Sure! Do you take the ferry every day?","好啊！你每天都坐渡轮吗？"],["Sure. Is it a long trip?","好啊。路上要很久吗？"]]},{"npc":["It's about half an hour, and I do it every day! I could check my emails, but I just look at the water and the Harbour Bridge. Best commute in the world.","大概半个小时，我天天都坐！本来可以看看邮件，但我就看海、看海港大桥。全世界最好的通勤。"]},{"me":[["Do you work in the city?","你在市中心上班吗？"],["What do you do?","你是做什么的？"]]},{"npc":["I'm a software engineer at a bank in the city. Oh look, that's Shane on the ferry. He's worked on it for twenty years. Say g'day to Shane. He loves a chat.","我在市中心一家银行做软件工程师。哎你看，渡轮上那个就是 Shane，他在这条船上干了二十年。跟 Shane 打个招呼吧，他最爱聊天了。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/people_sydney_priya.mp4","poster":"https://img.heyvoyo.com/clips/people_sydney_priya.webp","where":"悉尼 · 曼利码头，大家排队上渡轮","why":"她每天早上就在这里坐渡轮去上班","by":"David Pickup","url":"https://www.pexels.com/video/sydney-ferry-boarding-at-manly-wharf-37265273/"},"face":{"s":4,"h":"long","hc":"black","t":"blazer","tc":"#2e5c8a","t2":"#f4f4f4","a":["ear"],"e":"calm","bgs":"harbour","prop":"laptop"}},"shane":{"nm":"Shane","av":"👨🏼","job":"曼利渡轮上的水手 · 56 岁","x":300,"y":40,"now":[["Huge cruise ship at Circular Quay today. The whole place was packed with tourists.","今天环形码头停了一艘超大的游轮，到处都是游客。"],["Saw a whale near the harbour entrance this morning. Never gets old.","今天早上在港口出口那儿看见一头鲸鱼。看多少次都看不腻。"],["Windy day. The ferry was rocking, and a few passengers went a bit pale.","今天风大，船晃得厉害，有几个乘客脸都白了。"],["Fish and chips at Nikos's shop on Friday, like always. Twenty years, and he's never given me extra chips. Not once!","周五照常去 Nikos 店里吃炸鱼薯条。二十年了，他一次都没多给过我几根薯条。一次都没有！"]],"story":"Shane 年轻时是练冲浪的好苗子，二十岁膝盖受了伤，再也没法比赛。他说上渡轮干活，是「离海最近、又不用冲浪的活儿」。有位老太太坐这条渡轮上班坐了三十年，她退休那天，Shane 跟船长说好，在她下船时鸣了两声笛。","ties":{"priya":"Priya 每天坐他这条渡轮上班","nikos":"每个周五去 Nikos 的炸鱼薯条店，吃了二十年"},"next":"nikos","chat":[{"npc":["G'day! You're Priya's mate, are ya? Hang on, let me tie this rope. Right, how ya going?","你好！你是 Priya 的朋友吧？等一下，我把这根绳子系好。好了，最近怎么样？"]},{"me":[["Good, thanks! How long have you worked on the ferry?","挺好的，谢谢！你在渡轮上干多久了？"],["Not bad! Is this the ferry to the city?","还不错！这是去市中心的渡轮吗？"]]},{"npc":["Twenty years on this ferry, Manly to Circular Quay and back! Every day I see the Opera House from the water. Still my favourite view.","这条船我干了二十年了，曼利到环形码头，来来回回！每天都从水上看歌剧院，到现在还是我最喜欢的风景。"]},{"me":[["Do you live in Manly?","你住在曼利吗？"],["Where's a good place to eat in Manly?","曼利哪儿有好吃的？"]]},{"npc":["Born and bred in Manly! And for food, you have to try Nikos's fish and chips near the wharf. He'll tell you Manly's better than Bondi. Don't argue with Nikos!","我就是曼利土生土长的！说到吃，一定要去码头附近 Nikos 的店吃炸鱼薯条。他会跟你说曼利比邦迪好。千万别跟 Nikos 争！"]}],"clip":{"src":"https://img.heyvoyo.com/clips/pet_club_vet_0.mp4","poster":"https://img.heyvoyo.com/clips/pet_club_vet_0.webp","where":"悉尼 · 环形码头（渡轮进出的码头）","why":"他每天在这里的渡轮码头上上下下，这是他常在的地方","by":"Ray .","url":"https://www.pexels.com/video/20186333/"},"face":{"s":2,"h":"short","hc":"salt","t":"uniform","tc":"#ffffff","t2":"#1f3550","b":"full","o":1,"e":"grin","bg":"#d6ecf6","bgs":"harbour","prop":"lifebuoy"}},"nikos":{"nm":"Nikos","av":"👨🏻‍🦳","job":"曼利码头边炸鱼薯条店的老板 · 64 岁","x":310,"y":150,"now":[["School holidays are coming. Time to order twice as much fish.","学校快放假了，鱼得多订一倍。"],["A seagull stole a whole piece of fish from a tourist today. Right out of his hand!","今天一只海鸥从游客手里叼走了一整块鱼，直接从手上抢的！"],["My nephew Jack came for lunch. He still says Bondi is better, so I only gave him small chips.","我外甥 Jack 来吃午饭，还是说邦迪更好，所以我只给了他一小份薯条。"],["I'm thinking about retiring. My daughter wants the shop, but she wants to sell vegan fish! Vegan fish!","我在想退休的事。我女儿想接这家店，可她想卖素鱼！素鱼！"]],"story":"Nikos 的爸妈从希腊的一个小岛来到澳洲，开了这家店，他十岁就在柜台后面帮忙。他嘴上天天说邦迪不行，其实每年太太过生日，两个人都会悄悄去邦迪吃一顿饭——那是他们第一次约会的地方。","ties":{"shane":"Shane 每个周五来吃炸鱼薯条，吃了二十年","jack":"Jack 是他外甥，两人为邦迪和曼利哪个好吵了一辈子"},"next":"jack","chat":[{"npc":["Shane sent you? Good bloke, Shane. Fish and chips? Best in Sydney. No, best in Australia!","Shane 让你来的？Shane 人不错。来份炸鱼薯条？全悉尼最好吃的。不对，全澳洲最好吃的！"]},{"me":[["Yes, please! Have you had this shop for a long time?","好的，来一份！你这家店开很久了吗？"],["Yes, please. Shane says you really love Manly.","好的，来一份。Shane 说你特别爱曼利。"]]},{"npc":["My parents opened this shop. I've been behind this counter since I was ten. Manly is the best beach in Sydney, no question. People who say Bondi don't know anything.","这家店是我爸妈开的，我十岁就站在这柜台后面了。曼利是悉尼最好的海滩，没得说。说邦迪好的人什么都不懂。"]},{"me":[["Hmm, I've heard Bondi is really nice too.","嗯……我听说邦迪也挺好的。"],["Why is Manly better?","曼利为什么更好？"]]},{"npc":["Bondi? Too many tourists, too many selfies. My nephew Jack is a lifesaver there, and he thinks it's the best. Go and ask Jack, then come back and tell me he's wrong!","邦迪？游客太多，自拍的人太多。我外甥 Jack 在那儿当救生员，他觉得那儿最好。你去问问 Jack，然后回来告诉我他错了！"]}],"clip":{"src":"https://img.heyvoyo.com/clips/people_sydney_nikos.mp4","poster":"https://img.heyvoyo.com/clips/people_sydney_nikos.webp","where":"悉尼港 · 开往曼利的渡轮，傍晚","why":"他的炸鱼薯条店就在曼利渡轮码头边上","by":"Luke R","url":"https://www.pexels.com/video/manly-ferry-16924478/"},"face":{"s":2,"h":"thin","hc":"white","t":"apron","tc":"#2b6cb0","t2":"#fff","b":"mous","o":1,"e":"grin","bgs":"chippy","prop":"chips"}},"jack":{"nm":"Jack","av":"👱🏼‍♂️","job":"水管工，周末在邦迪当志愿救生员 · 40 岁","x":290,"y":250,"now":[["Big crowds at Bondi on Sunday. We pulled four people out of a rip.","周日邦迪人山人海，我们从离岸流里拉回来四个人。"],["Fixed a burst pipe at a café at 5 am, then went straight to the beach for patrol.","早上五点去一家咖啡馆修爆掉的水管，修完直接去海滩值班。"],["Gave Ji-woo and her friends a swimming lesson. They can all spot a rip now.","给 Ji-woo 和她朋友上了一节游泳课，现在她们都能认出离岸流了。"],["Christmas lunch at Uncle Nikos's place. We'll argue about Bondi and Manly again. Every year!","圣诞午饭去 Nikos 舅舅家吃。又要为邦迪和曼利吵一架，年年如此！"]],"story":"Jack 平时是水管工，周末穿上红黄两色的衣服在邦迪当救生员，没有工资，一干就是十五年。他说最难的不是把人拉上岸，是劝游客别在没插旗子的地方下水。他在曼利长大，却跑去邦迪当救生员，舅舅到现在还没原谅他。","ties":{"chloe":"常把在海边受伤的人送到 Chloe 的急诊","jiwoo":"Ji-woo 刚来那周被离岸流卷走，是他把她拉回来的","nikos":"他舅舅，两人为邦迪和曼利哪个好吵了一辈子"},"next":"jiwoo","chat":[{"npc":["Ha! Uncle Nikos sent you to argue with me, didn't he? Classic.","哈！是 Nikos 舅舅让你来跟我吵的吧？他就是这样。"]},{"me":[["Yes! He says Manly is better.","对！他说曼利更好。"],["Kind of. So which beach is better?","算是吧。那到底哪个海滩更好？"]]},{"npc":["Bondi, of course! But honestly, the best beach is the one with lifesavers on it. Always swim between the red and yellow flags.","当然是邦迪！不过说真的，最好的海滩是有救生员的那个。一定要在红黄两色的旗子中间游。"]},{"me":[["Why the flags?","为什么要看旗子？"],["Is it dangerous here?","这儿危险吗？"]]},{"npc":["It can be, because of rips. They can pull you out to sea really fast, so we put the flags where it's safe. My friend Ji-woo found out in her first week here. Now she works at a café in Newtown. Go and ask Ji-woo what happened!","可能会有危险，因为有离岸流，一下子就能把人拉到海里去，所以我们把旗子插在安全的地方。我朋友 Ji-woo 刚来第一周就碰上了。她现在在纽敦一家咖啡馆打工，去问问 Ji-woo 当时是怎么回事吧！"]}],"clip":{"src":"https://img.heyvoyo.com/clips/people_sydney_jack.mp4","poster":"https://img.heyvoyo.com/clips/people_sydney_jack.webp","where":"悉尼 · 邦迪海滩，冲浪的人，从空中往下看","why":"他周末在这片海滩当志愿救生员","by":"Macourt Media","url":"https://www.pexels.com/video/aerial-view-of-surfers-at-bondi-beach-australia-31845100/"},"face":{"s":1,"h":"crop","hc":"blonde","t":"lifeguard","tc":"#e33b2f","b":"stubble","e":"grin","bg":"#d6ecf6","bgs":"beach","prop":"rescuetube"}},"jiwoo":{"nm":"Ji-woo","av":"👩🏻","job":"韩国来打工度假的背包客 · 24 岁","x":190,"y":290,"now":[["Found my old paper map from Western Australia in my bag. There was no phone signal on the farm, so this map saved me.","在包里翻到了我在西澳用的那张纸质地图。农场那边手机没信号，全靠这张地图。"],["Linh let me make the coffee by myself today! Only one customer complained.","今天 Linh 让我自己做咖啡了！只有一个客人有意见。"],["Swimming lesson with Jack at Bondi. I can spot a rip now. Well, almost.","跟 Jack 在邦迪上了游泳课，现在我能认出离岸流了。嗯，差不多吧。"],["Went to a language exchange with Yu. I taught Korean, she taught Chinese, and we both practised English.","跟 Yu 去了语言交换。我教韩语，她教中文，我们俩都练了英语。"]],"story":"Ji-woo 来悉尼第一周，在邦迪没看旗子就下了水，被离岸流卷了出去，是 Jack 游过来把她拉回岸上。她吓得一个月没敢下海。后来她干脆报了救生课，想有一天也穿上那身红黄衣服。","ties":{"linh":"在 Linh 的咖啡馆打工，Linh 手把手教她做咖啡","yu":"在图书馆的语言交换活动上认识的","jack":"她刚来那周被离岸流卷走，是 Jack 救了她"},"next":"linh","chat":[{"npc":["Hi, welcome! What can I get you? Sorry, I'm still new here. Jack sent you, right?","嗨，欢迎光临！你要点什么？不好意思，我刚来没多久。是 Jack 让你来的吧？"]},{"me":[["Yes! A flat white, please. He said you had a scary day at Bondi.","对！来杯 flat white。他说你在邦迪碰上过一回惊险的事。"],["Yep. Can I grab a flat white, please?","对。给我来杯 flat white，谢谢。"]]},{"npc":["One flat white, coming up! Jack saved my life, you know. I nearly got pulled out to sea at Bondi. Now I always swim between the flags.","一杯 flat white，马上好！跟你说，Jack 救过我的命。我在邦迪差点被卷到海里。现在我一定在旗子中间游。"]},{"me":[["Why did you come to Australia?","你为什么来澳洲？"],["Do you like working here?","你喜欢在这儿打工吗？"]]},{"npc":["I'm on a working holiday. I picked fruit on a farm in Western Australia, so this job feels easy! Well, except the coffee. My boss is very fussy about coffee. Oh, here she comes. Say hi to Linh!","我是来打工度假的。之前在西澳的农场摘水果，跟那比，这份活儿轻松多了！嗯，除了做咖啡。我老板对咖啡特别讲究。哎，她来了，跟 Linh 打个招呼吧！"]}],"clip":{"src":"https://img.heyvoyo.com/clips/see_world_directions_2.mp4","poster":"https://img.heyvoyo.com/clips/see_world_directions_2.webp","where":"澳大利亚西部 · 一张纸质地图","why":"她在西澳农场打工时，没信号就靠这种纸质地图认路","by":"Rachel Claire","url":"https://www.pexels.com/video/8899929/"},"face":{"s":2,"h":"long","hc":"dbrown","t":"tee","tc":"#f2a65a","a":["ear"],"e":"grin","bgs":"beach","prop":"backpack"}},"linh":{"nm":"Linh","av":"👩🏻","job":"纽敦一家咖啡馆的老板 · 29 岁","x":150,"y":50,"now":[["Went home to Melbourne for the weekend. I walked down my old laneway and had a coffee where I first learned to make it.","周末回了趟墨尔本。走了走以前那条小巷，在我当年学做咖啡的那家店喝了一杯。"],["Ben came in with Pepper again. Pepper always gets a free puppuccino.","Ben 又带 Pepper 来了。Pepper 每次都能免费喝一小杯狗狗奶泡。"],["Ji-woo made her first perfect flat white! I almost cried.","Ji-woo 做出了她第一杯完美的 flat white！我差点哭了。"],["Margaret finished the crossword before me again. Every morning, she wins.","Margaret 又比我先做完填字游戏。每天早上都是她赢。"]],"story":"Linh 的爸妈是越南人，在墨尔本开河粉店。她小时候一放学就在店里帮忙，发誓长大绝不开店。结果二十五岁那年，她拿出全部积蓄在悉尼开了这家咖啡馆。她爸第一次来，喝了一口，只说了一句：比我们的越南咖啡差一点。","ties":{"ben":"Ben 每天上班前来买咖啡，常带着 Pepper","margaret":"Margaret 每天早上来喝 flat white、做填字游戏","jiwoo":"Ji-woo 在她店里打工，她手把手教她做咖啡"},"next":"ben","chat":[{"npc":["Hey! You're Ji-woo's friend? Welcome. Is she looking after you? She's getting really good.","嘿！你是 Ji-woo 的朋友？欢迎。她招呼得还好吧？她进步可快了。"]},{"me":[["She's great! Is this your café?","她很好！这是你的咖啡馆吗？"],["Yes! Her coffee is really good.","对！她做的咖啡真不错。"]]},{"npc":["Thanks! This is my café, so I taught her myself. I learned to make coffee in Melbourne. Melbourne people think they make the best coffee in Australia. They might be right, but don't tell anyone in Sydney!","谢谢！这是我的店，她是我手把手教出来的。我是在墨尔本学的做咖啡。墨尔本人觉得全澳洲就数他们的咖啡最好。可能真是，不过别告诉悉尼人！"]},{"me":[["Do you have a lot of regulars?","你这儿熟客多吗？"],["What's the most popular coffee here?","这儿最受欢迎的是哪种咖啡？"]]},{"npc":["Flat white, always. And lots of regulars! Every morning, a vet nurse called Ben comes in with his greyhound. Have you met Ben? He's lovely, and so is his dog.","一直都是 flat white。熟客也特别多！每天早上有个叫 Ben 的兽医护士带着他的灰猎犬来。你认识 Ben 吗？他人很好，他的狗也是。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/first_money_job_0.mp4","poster":"https://img.heyvoyo.com/clips/first_money_job_0.webp","where":"墨尔本 · 开着咖啡馆的小巷","why":"她在墨尔本长大，当年就是在这种小巷里的咖啡馆学做咖啡","by":"Ous Njie","url":"https://www.pexels.com/video/34735013/"},"face":{"s":2,"h":"bob","hc":"black","t":"apron","tc":"#3a5a40","t2":"#f2efe6","e":"grin","bgs":"cafe","prop":"coffee"}}}},"toronto":{"zh":"多伦多","en":"Toronto","ll":[-79.3832,43.6532],"r_km":40,"start":["harjit","aisha"],"order":["harjit","denise","grace","liam","arjun","nima","manny","sam","joy","aisha"],"people":{"harjit":{"nm":"Harjit","av":"👳🏽‍♂️","job":"网约车司机，在印度当过土木工程师 · 47 岁","x":50,"y":150,"now":[["Long day. Three airport runs before lunch, and the 401 was a parking lot.","今天好累。午饭前跑了三趟机场，401 高速堵得跟停车场一样。"],["Put on my winter tires today. Now I'm ready for anything.","今天换上了雪地胎，现在什么天气都不怕了。"],["First snow this week. Everyone forgets how to drive in the snow!","这周下了第一场雪。一下雪，大家好像都忘了怎么开车！"],["My daughter wants to study engineering, just like me. I'm so proud.","女儿说想学工程，跟我一样。我太骄傲了。"]],"story":"在旁遮普当了十五年土木工程师，来加拿大后学历不被认，只好先开车。每天在车里听工程师考试的录音，打算考回执照。他常说：在多伦多，给你开车的人，说不定就是个工程师。","ties":{"denise":"天天中午去她店里吃肉饼","joy":"太太的同事，下夜班有时顺路送她回家"},"next":"denise","chat":[{"npc":["Welcome to Toronto! Is this your first time here?","欢迎来多伦多！第一次来吗？"]},{"me":[["Yes, I just moved here.","是的，我刚搬来。"],["Yeah. Is it always this cold?","对。这儿一直这么冷吗？"]]},{"npc":["Ha! Wait till January, it gets much colder. I came from Punjab nine years ago. My first winter, I almost went home!","哈！等到一月再说吧，那才叫冷。我九年前从旁遮普来，第一个冬天差点就回去了！"]},{"me":[["What did you do back home?","你在老家是做什么的？"],["Do you like driving here?","你喜欢在这儿开车吗？"]]},{"npc":["Back home I was an engineer. Now I drive, and honestly, it's okay. I meet lots of people. Hey, are you hungry? Go see Denise in Little Jamaica. Best patties in the city. Tell her Harjit sent you!","我在老家是工程师，现在开车，说实话也挺好，能认识很多人。对了，你饿不饿？去小牙买加找 Denise，全城最好吃的牙买加肉饼。就说是 Harjit 让你去的！"]}],"clip":{"src":"https://img.heyvoyo.com/clips/people_toronto_harjit.mp4","poster":"https://img.heyvoyo.com/clips/people_toronto_harjit.webp","where":"多伦多 · 白天车多的大街","why":"他每天开车接客，跑的就是这样的路","by":"IslandHopper X","url":"https://www.pexels.com/video/busy-toronto-street-view-in-daytime-traffic-31328171/"},"face":{"s":4,"h":"turban","hc":"#1f3d7a","t":"shirt","tc":"#cfd8e3","b":"full","e":"calm","bgs":"toronto","prop":"wheel"}},"denise":{"nm":"Denise","av":"👩🏾‍🍳","job":"小牙买加一家牙买加肉饼店的老板 · 52 岁","x":80,"y":50,"now":[["Crazy morning. The beef patties sold out by ten!","早上忙疯了，牛肉饼十点前就卖光了。"],["My mom's oxtail is back on the menu this week.","这周菜单上又有我妈那道炖牛尾了。"],["Cold day. Everybody wants soup today.","天冷了，今天人人都要喝汤。"],["My blood pressure is better. Grace was right about the salt!","我的血压好多了。Grace 让我少吃盐，说得对！"]],"story":"十九岁从牙买加的金斯敦来到多伦多，先跟妈妈在家做肉饼卖给邻居，后来开了这家店，一开就是快三十年。她最骄傲的不是店，是没让一个饿肚子的孩子空着手走——没带钱的，她偷偷多塞一个。","ties":{"harjit":"老主顾，每天中午都来","grace":"隔壁药房的药剂师，总提醒她量血压"},"next":"grace","chat":[{"npc":["Hi there! Harjit sent you? That man eats here every single day!","你好！是 Harjit 让你来的？他天天都来这儿吃！"]},{"me":[["What do you recommend?","你推荐什么？"],["One beef patty, please.","一个牛肉饼，谢谢。"]]},{"npc":["Beef is the best! Try it in coco bread. It's like a sandwich. Trust me.","牛肉的最好吃！夹在椰奶面包里试试，像个三明治。相信我。"]},{"me":[["It smells so good in here!","这里好香啊！"],["Is it spicy?","辣吗？"]]},{"npc":["It's my mother's recipe. A little spicy, just right. Hey, you're sniffling. Got a cold? Go next door to the pharmacy and ask for Grace. She'll look after you.","这是我妈的方子，有一点辣，刚刚好。哎，你在吸鼻子，感冒了吧？去隔壁药房找 Grace，她会照顾好你的。"]}],"face":{"s":5,"h":"braidbun","hc":"black","t":"apron","tc":"#f2c318","t2":"#2e7d32","a":["hoops"],"o":1,"e":"grin","bg":"#fdf0c8","bgs":"kitchen","prop":"patty"}},"grace":{"nm":"Grace","av":"👩🏻‍⚕️","job":"社区药房的药剂师，香港长大 · 41 岁","x":175,"y":30,"now":[["Flu shot season. I gave so many shots today, my arm is tired!","又到打流感疫苗的时候了。今天打了好多针，胳膊都酸了！"],["My son's class went skating today. He came home with red cheeks and a big smile.","儿子班上今天去滑冰了，回家脸蛋红红的，笑得特别开心。"],["So many colds this week. My best advice? Rest, drink water, and stay home.","这周感冒的人特别多。我的建议？好好休息、多喝水、待在家里。"],["Denise brought me a patty to say thanks. Best lunch all week.","Denise 给我送了个肉饼说谢谢。这是我这周最好吃的一顿午饭。"]],"story":"十二岁跟爸妈从香港搬来多伦多，第一年在学校几乎一句话都不说。她当药剂师，是因为小时候常陪不会英语的外婆去药房问药。现在店里一来讲粤语或普通话的老人，同事就喊她。","ties":{"denise":"隔壁肉饼店的老板，常来量血压","liam":"儿子的四年级老师"},"next":"liam","chat":[{"npc":["Hi, how can I help? Denise called and said you'd come by.","你好，需要什么？Denise 打电话说你会过来。"]},{"me":[["I think I have a cold.","我好像感冒了。"],["I need something for a sore throat.","我想买点治喉咙痛的药。"]]},{"npc":["Okay. Any fever? No? Then try this, and drink lots of water. If you're not better in a week, see a doctor.","好的。发烧吗？没有？那试试这个，多喝水。一个星期还不好，就去看医生。"]},{"me":[["Thank you so much.","太谢谢你了。"],["Thanks! Anything else I should do?","谢谢！我还要注意什么吗？"]]},{"npc":["You're welcome! Get lots of sleep, too. And when you feel better, why not try hockey? My son's teacher, Liam, plays every week. He loves meeting new people.","不客气！也要多睡觉。等你好了，要不要试试冰球？我儿子的老师 Liam 每周都打，他特别喜欢认识新朋友。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/people_toronto_grace.mp4","poster":"https://img.heyvoyo.com/clips/people_toronto_grace.webp","where":"药店柜台上的刷卡机（拍摄地没写）","why":"她每天站的，就是这样的药店柜台","by":"cottonbro studio","url":"https://www.pexels.com/video/customer-paying-cashless-8657613/"},"face":{"s":2,"h":"bob","hc":"black","t":"blazer","tc":"#ffffff","t2":"#cfe3f0","a":["glasses","badge"],"e":"calm","bgs":"pharmacy","prop":"pills"}},"liam":{"nm":"Liam","av":"🧑🏼","job":"小学四年级老师，业余冰球队守门员 · 31 岁","x":275,"y":55,"now":[["Hockey night. We lost again, but the beer after was great.","冰球之夜。又输了，不过打完喝的那杯啤酒真不错。"],["Took my class skating at the arena. Lots of falling, lots of laughing.","带全班去室内冰场滑冰。摔了好多跤，也笑了好多回。"],["Parent-teacher interviews this week. Long days, but I love hearing about the kids.","这周开家长会。每天都很长，可我喜欢听家长讲孩子的事。"],["Called my mom in Halifax. She says it's already snowing there.","给哈利法克斯的妈妈打电话，她说那边已经下雪了。"]],"story":"在新斯科舍的海边长大，八年前为了工作搬来多伦多，一开始一个朋友都没有。是周二晚上的业余冰球队让他交到了朋友：队里有护士、水管工，还有一个三十岁才学滑冰的人。现在他总拉刚来的人入队。","ties":{"grace":"班上一个学生的妈妈","arjun":"周二业余冰球队的队友"},"next":"arjun","chat":[{"npc":["Hey! You're Grace's friend? She said you want to try hockey.","嘿！你是 Grace 的朋友？她说你想试试冰球。"]},{"me":[["Yes, but I can't skate very well.","是的，可是我滑得不太好。"],["Maybe! Is it hard?","也许吧！难吗？"]]},{"npc":["Don't worry. It's a beer league. Nobody's good, we just have fun. Honestly, the drinks after are the best part.","别担心，这是业余队，没人打得好，就是图个开心。说实话，打完一起喝一杯才是最棒的。"]},{"me":[["When do you play?","你们什么时候打？"],["Do you play every week?","你们每周都打吗？"]]},{"npc":["Every Tuesday night. Come and watch first. Our newest player is Arjun. He started skating at thirty, and now he never misses a game!","每周二晚上。先来看看吧。我们队最新的队员是 Arjun，他三十岁才学滑冰，现在一场都不落！"]}],"clip":{"src":"https://img.heyvoyo.com/clips/people_toronto_liam.mp4","poster":"https://img.heyvoyo.com/clips/people_toronto_liam.webp","where":"室内冰球场，有人在练球（拍摄地没写）","why":"他每周二晚上在这样的冰场上当守门员","by":"Tony Schnagl","url":"https://www.pexels.com/video/people-playing-ice-hockey-6339369/"},"face":{"s":1,"h":"short","hc":"brown","t":"jumper","tc":"#2f6db5","b":"stubble","e":"grin","bgs":"class","prop":"hockeystick"}},"arjun":{"nm":"Arjun","av":"👨🏽‍💻","job":"科技公司的 AI 产品经理，从班加罗尔来 · 33 岁","x":320,"y":145,"now":[["Big launch at work this week. Basically, I lived on coffee.","这周公司上新产品，基本上靠咖啡活着。"],["Scored my first goal in hockey! To be fair, their goalie fell over.","冰球打进了第一个球！不过说实话，是对方守门员自己摔倒了。"],["Video call with my little brother. He's still looking for a job. I told him to keep going.","跟弟弟视频。他还在找工作，我让他别放弃。"],["Bought my first real winter coat. My colleagues say I finally look Canadian.","买了第一件真正的冬天大衣。同事说我终于像个加拿大人了。"]],"story":"五年前从班加罗尔搬来，白天在公司做 AI 写作工具，晚上担心刚毕业的弟弟找不到工作。三十岁第一次穿上冰鞋，摔了一整个冬天。他说：到了新地方，交朋友最快的办法，就是去做一件你很不擅长的事。","ties":{"liam":"冰球队队友，滑冰是跟他学的","nima":"常去的咖啡馆的咖啡师"},"next":"nima","chat":[{"npc":["Hey! Liam said you might join the team. Welcome to the worst skaters club!","嘿！Liam 说你可能要入队。欢迎加入「滑得最差俱乐部」！"]},{"me":[["Ha! What do you do for work?","哈！你是做什么工作的？"],["Liam said you started skating at thirty?","Liam 说你三十岁才开始学滑冰？"]]},{"npc":["I make AI tools at a tech company. And yeah, I started skating at thirty. Basically, I fell all winter!","我在一家科技公司做 AI 工具。对，我三十岁才学滑冰，基本上摔了一整个冬天！"]},{"me":[["Do you think AI will take our jobs?","你觉得 AI 会抢走我们的工作吗？"],["Do you like your job?","你喜欢你的工作吗？"]]},{"npc":["Honestly? I love my job, but I worry too. Jobs will change, but they won't all disappear. I work from a café most days. The barista, Nima, was an architect back in Tehran. Go say hi!","说实话？我很喜欢我的工作，但也担心。工作会变，但不会全没了。对了，我大多数时候在一家咖啡馆干活，那儿的咖啡师 Nima 在德黑兰是建筑师。去打个招呼吧！"]}],"npc":"arjun","clip":{"src":"https://img.heyvoyo.com/clips/people_toronto_arjun.mp4","poster":"https://img.heyvoyo.com/clips/people_toronto_arjun.webp","where":"多伦多 · 市中心，CN 塔脚下","why":"他的公司就在多伦多市中心","by":"Hao Le","url":"https://www.pexels.com/video/vibrant-downtown-toronto-with-cn-tower-38168516/"},"face":{"s":4,"h":"side","hc":"black","t":"tee","tc":"#2d2d2d","a":["glasses"],"b":"short","e":"calm","bgs":"office","prop":"laptop"}},"nima":{"nm":"Nima","av":"🧔🏻","job":"咖啡馆的咖啡师，在德黑兰当过建筑师 · 32 岁","x":280,"y":240,"now":[["Busy morning. Arjun's been here with his laptop since eight.","早上很忙。Arjun 八点就抱着电脑来了。"],["Manny fixed my heater. My basement apartment is finally warm!","Manny 帮我修好了暖气，地下室终于暖和了！"],["My architecture exam is coming up. I study on the subway every day.","建筑师考试快到了，我每天在地铁上复习。"],["My mom sent saffron from Iran. I made saffron rice for my friends.","妈妈从伊朗寄来了藏红花，我给朋友们做了藏红花饭。"]],"story":"在德黑兰设计过一座图书馆，两年前来到多伦多，从头开始：一边做咖啡，一边准备加拿大的建筑师考试。他给老板画了一张咖啡馆的新布局，老板真照着改了，熟客都说现在坐着舒服多了。","ties":{"arjun":"每天早上来的熟客","manny":"他住的地下室那栋楼的楼管","aisha":"两年前帮他开了第一个银行账户，现在每天早上来买咖啡"},"next":"manny","chat":[{"npc":["Hi! What can I get you? You're Arjun's friend, right? He told me.","你好！喝点什么？你是 Arjun 的朋友吧？他跟我说了。"]},{"me":[["Yes! A medium latte, please.","对！一杯中杯拿铁，谢谢。"],["Hi! Can I get a coffee to go?","你好！能要一杯咖啡带走吗？"]]},{"npc":["Sure thing! Arjun gets the same every morning. He's here so much, we should give him his own desk!","没问题！Arjun 每天早上都点这个。他来得太勤了，真该给他一张自己的桌子！"]},{"me":[["Arjun said you were an architect?","Arjun 说你以前是建筑师？"],["What brought you to Toronto?","你怎么会来多伦多？"]]},{"npc":["I was an architect in Tehran. I came here to start again. Now I live around the corner, in a basement. If you need a room, ask my super, Manny. He knows every place for rent around here.","我在德黑兰是建筑师，来这儿是想重新开始。现在住拐角那边的地下室。你要找房，就去问我们楼的楼管 Manny，这一带哪儿有房出租他都知道。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/people_toronto_nima.mp4","poster":"https://img.heyvoyo.com/clips/people_toronto_nima.webp","where":"咖啡店里，咖啡师在拉花（拍摄地没写）","why":"他每天早上做的，就是这件事","by":"Esra Afşar","url":"https://www.pexels.com/video/barista-creating-latte-art-in-coffee-shop-34601858/"},"face":{"s":3,"h":"curly","hc":"black","t":"apron","tc":"#3d3d3d","t2":"#e8e0d0","b":"full","e":"calm","bgs":"cafe","prop":"sketch"}},"manny":{"nm":"Manny","av":"👴🏻","job":"公寓楼的楼管，葡萄牙裔 · 61 岁","x":190,"y":290,"now":[["Garbage day tomorrow. Blue bin for recycling, green bin for food. I tell everyone twice!","明天收垃圾。蓝桶放可回收的，绿桶放厨余。我跟每个人都说两遍！"],["The heat is on now. Three tenants called me before breakfast.","暖气开了。早饭前就有三个租户给我打电话。"],["Shovelled snow at six this morning. My back says I'm getting old.","早上六点就起来铲雪，腰在提醒我老了。"],["Portugal played on Sunday. The whole street watched it at the café.","周日葡萄牙队比赛，整条街的人都在咖啡馆看。"]],"story":"二十岁从葡萄牙的亚速尔群岛来多伦多，先在工地干活，后来在这栋楼当了三十年楼管。楼里每家人的名字他都记得，谁家孩子考上大学，他比谁都高兴。他说：房租再贵，邻居也得认识。","ties":{"nima":"住在楼里的地下室","sam":"住三楼的租户"},"next":"sam","chat":[{"npc":["Hello! Nima told me you're looking for a room?","你好！Nima 说你在找房？"]},{"me":[["Yes, something small and not too expensive.","对，小一点、不太贵的就行。"],["Yes. Is there anything available?","是的。有空房吗？"]]},{"npc":["There's a small room on the third floor. You pay first and last month's rent, no damage deposit. That's the rule in Ontario.","三楼有个小房间。交第一个月和最后一个月的房租，不收押金，安大略就是这么规定的。"]},{"me":[["Is it quiet?","安静吗？"],["Who else lives here?","这里还住着谁？"]]},{"npc":["Lots of students, so it's pretty quiet. Like Sam, on the third floor. He works at the grocery store. Knock on his door. He knows all the best deals around here.","住的多是学生，所以挺安静的。比如三楼的 Sam，在超市打工。去敲他的门，这一带哪儿买东西便宜他都知道。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/life_abroad_rubbish_3.mp4","poster":"https://img.heyvoyo.com/clips/life_abroad_rubbish_3.webp","where":"加拿大 · 公寓楼外，收回收和厨余","why":"Manny 管的就是这样的公寓楼，分垃圾、拉桶出去是他每周的活","by":"Everett Bumstead","url":"https://www.pexels.com/video/5434519/"},"face":{"s":3,"h":"thin","hc":"grey","t":"polo","tc":"#3b5a7a","b":"mous","o":1,"e":"grin","bgs":"lobby","prop":"keys"}},"sam":{"nm":"Sam","av":"🧑🏻‍🎓","job":"大二学生，学心理学，晚上在超市打工 · 20 岁","x":95,"y":265,"now":[["Evening shift again. Most people use self-checkout now. I just help when it beeps.","又是晚班。现在大部分人用自助结账，机器一响我就过去帮忙。"],["Psych midterm tomorrow. Honestly, I'm not ready.","明天心理学期中考。说实话，我还没准备好。"],["Visited my grandma on Sunday. Joy did her hair, and she looked so happy.","周日去看奶奶。Joy 给她梳了头，她看起来特别开心。"],["Someone asked where I'm from again. I said, \"I guess... everywhere?\"","又有人问我是哪里人。我说：“大概……哪儿都是？”"]],"story":"在首尔出生，在迪拜和多伦多长大，三种语言都会，可被问到“你是哪里人”总答不上来。每周日去养老院看奶奶，用韩语给她读新闻——那是奶奶一周里话最多的时候。","ties":{"manny":"他住的那栋楼的楼管","joy":"在养老院照顾他奶奶"},"next":"joy","chat":[{"npc":["Oh hey! Manny said someone new might knock. I'm Sam.","哦，嘿！Manny 说可能有新邻居来敲门。我是 Sam。"]},{"me":[["Hi Sam! Manny said you know the best deals.","嗨 Sam！Manny 说你知道哪儿买东西便宜。"],["Hi! I might be your new neighbour.","嗨！我可能是你的新邻居。"]]},{"npc":["Cool! Here's tip number one: the store where I work has cheap bread after eight at night. Honestly, that's how I survive.","好啊！第一条建议：我打工的超市，晚上八点以后面包打折。说实话，我就靠这个活着。"]},{"me":[["Where are you from?","你是哪里人？"],["Do you have family here?","你家里人在这儿吗？"]]},{"npc":["Ha, long story! I was born in Seoul, then grew up in Dubai and here. My grandma lives here too, in a care home. Joy looks after her. You'd love Joy. She's the warmest person in Toronto.","哈，说来话长！我在首尔出生，在迪拜和这儿长大。我奶奶也在这儿，住养老院，是 Joy 在照顾她。你会喜欢 Joy 的，她是全多伦多最暖心的人。"]}],"npc":"sam","clip":{"src":"https://img.heyvoyo.com/clips/life_abroad_grocery_2.mp4","poster":"https://img.heyvoyo.com/clips/life_abroad_grocery_2.webp","where":"加拿大 · 哈利法克斯一家超市的自助结账","why":"Sam 晚上打工的就是这种加拿大超市，自助结账越来越多","by":"Max Medyk","url":"https://www.pexels.com/video/7457422/"},"face":{"s":2,"h":"fringe","hc":"black","t":"hoodie","tc":"#7a5aa0","e":"calm","bgs":"campus","prop":"newspaper"}},"joy":{"nm":"Joy","av":"👩🏽","job":"养老院的护工，从菲律宾来 · 38 岁","x":145,"y":170,"now":[["Night shift this week. The residents are asleep, so I'm texting my kids. It's afternoon in Manila.","这周上夜班。老人们都睡了，我在给孩子们发消息，马尼拉那边已经是下午了。"],["Sent money home on payday. Aisha at the bank always asks about my kids.","发工资那天往家里汇钱。银行的 Aisha 每次都问起我的孩子。"],["Sunday karaoke with my friends. I sang Celine Dion, of course!","周日跟朋友们唱卡拉 OK，当然唱了席琳·迪翁！"],["Big news: my kids' visas came through. They're coming in the spring!","大好消息：孩子们的签证批下来了！春天他们就来了！"]],"story":"七年前把两个孩子留在马尼拉给妈妈带，自己来多伦多做住家保姆，后来考了护工证。养老院里每个老人爱吃什么、爱听什么歌，她都记得。Sam 的奶奶几乎不会英语，Joy 就学了几句韩语，奶奶一听就笑。","ties":{"sam":"她照顾 Sam 的奶奶","harjit":"同事的丈夫，下夜班有时顺路送她回家","aisha":"每个月去她的柜台汇钱"},"next":"aisha","chat":[{"npc":["Hi, welcome! You must be Sam's friend. His grandma just had lunch. She's in a good mood.","你好，欢迎！你一定是 Sam 的朋友。他奶奶刚吃完午饭，心情很好。"]},{"me":[["Nice to meet you, Joy. Sam talks about you a lot.","很高兴认识你，Joy。Sam 常提起你。"],["Hi Joy, nice to meet you! How long have you worked here?","嗨 Joy，很高兴认识你！你在这儿工作多久了？"]]},{"npc":["Aw, nice to meet you too! I've been here five years. I came from the Philippines. My kids are still in Manila with my mom.","哎呀，我也很高兴认识你！我在这儿五年了，是从菲律宾来的。孩子们还在马尼拉，跟着我妈。"]},{"me":[["You must miss them.","你一定很想他们。"],["Do you talk to them every day?","你每天都跟他们联系吗？"]]},{"npc":["Every single day. We video call every night, and I send money home every month. If you need to send money too, go see Aisha at the bank downtown. She's so patient with newcomers.","每一天都是。我们每天晚上视频，我每个月往家里汇钱。你要是也要汇钱，去市中心的银行找 Aisha，她对刚来的人特别有耐心。"]}],"clip":{"src":"https://img.heyvoyo.com/clips/people_toronto_joy.mp4","poster":"https://img.heyvoyo.com/clips/people_toronto_joy.webp","where":"一位护工陪着坐在椅子上的老爷爷（拍摄地没写）","why":"她每天照顾的，就是这样的老人","by":"Kampus Production","url":"https://www.pexels.com/video/elderly-man-sitting-on-the-chair-7516767/"},"face":{"s":3,"h":"pony","hc":"black","t":"scrubs","tc":"#e88aa8","a":["tag"],"e":"grin","bgs":"home","prop":"teacup"}},"aisha":{"nm":"Aisha","av":"👩🏽‍💼","job":"市中心一家银行的柜员 · 29 岁","x":230,"y":155,"now":[["Sunny morning downtown. I walked to work from Union Station, coffee in hand.","市中心阳光很好的早上。我从联合车站走路去上班，手里拿着咖啡。"],["Opened accounts for three newcomers today. One of them cried a little. Happy tears!","今天给三个新来的人开了户。有一个人哭了，是高兴哭的。"],["My mom made biryani for the whole family on Sunday. I ate way too much.","周日妈妈给全家做了香饭，我吃得太多了。"],["Joy came in with big news: her kids are coming! I almost cried at my desk.","Joy 来柜台跟我说了个好消息：她的孩子们要来了！我在座位上差点哭了。"]],"story":"爸妈从巴基斯坦移民过来，英语不好，她从八岁起就陪他们跑银行、当小翻译。现在坐在柜台的另一边，她最常对新移民说的是：开户只要证件，不用先有工作，别被吓到。","ties":{"joy":"每个月来汇钱的老客人","nima":"两年前帮他开了户，现在每天早上喝他做的咖啡"},"next":"nima","chat":[{"npc":["Next, please! Hi there, how can I help you today?","下一位！你好，今天要办什么？"]},{"me":[["I'd like to open a bank account.","我想开个银行账户。"],["Hi. Joy said you could help me.","你好。Joy 说你能帮我。"]]},{"npc":["Of course! You just need your passport and your immigration papers. You don't need a job first, don't worry.","当然可以！带上护照和移民文件就行。不用先有工作，别担心。"]},{"me":[["Really? Someone told me I need a job.","真的吗？有人跟我说要先有工作。"],["Great. How long does it take?","太好了。要多久？"]]},{"npc":["Twenty minutes, and no job needed, I promise. I helped my parents do this when I was eight! After this, go get a coffee from Nima at the café around the corner. Tell him I sent you.","二十分钟，真的不用先有工作。我八岁就陪爸妈办过！办完去拐角的咖啡馆找 Nima 喝杯咖啡，就说是我让你去的。"]}],"npc":"aisha_bank","clip":{"src":"https://img.heyvoyo.com/clips/life_abroad_bank_0.mp4","poster":"https://img.heyvoyo.com/clips/life_abroad_bank_0.webp","by":"WeStarMoney Rec","url":"https://www.pexels.com/video/38863596/","where":"多伦多 · 市中心的街道","why":"她上班的银行就在市中心这一带"},"face":{"s":4,"h":"long","hc":"black","t":"blazer","tc":"#24405e","t2":"#f4f4f4","a":["badge","ear"],"e":"calm","bgs":"bank","prop":"card"}}},"clip":{"src":"https://img.heyvoyo.com/clips/life_abroad_bank_0.mp4","poster":"https://img.heyvoyo.com/clips/life_abroad_bank_0.webp","by":"WeStarMoney Rec","url":"https://www.pexels.com/video/38863596/","where":"多伦多 · 市中心的街道"}}};
