function eyes(n, sp, e, o, skin, iris, lash){
  const L = 100 - sp, R = 100 + sp, D = "#1d1410";
  if (e === "tired") n = 0;
  const one = x => [
    `<ellipse cx="${x}" cy="90" rx="4.6" ry="${e === "tired" ? 3.6 : 4.8}" fill="${D}"/><circle cx="${x + 1.6}" cy="88.4" r="1.4" fill="#fff"/>`,
    `<path d="M${x - 6} 92 q6 -8 12 0" stroke="${D}" stroke-width="3.2" fill="none" stroke-linecap="round"/>`,
    `<path d="M${x - 8} 90 q8 -8 16 0 q-8 6 -16 0z" fill="#fff"/><circle cx="${x}" cy="89.6" r="3.6" fill="${iris}"/><circle cx="${x}" cy="89.6" r="1.7" fill="${D}"/><path d="M${x - 8} 90 q8 -8 16 0" stroke="${D}" stroke-width="2" fill="none"/>`,
    `<circle cx="${x}" cy="90" r="5.4" fill="${D}"/><circle cx="${x + 1.8}" cy="88" r="1.7" fill="#fff"/>${lash ? `<path d="${x < 100 ? `M${x - 5} 86.5 l-2.5 -2 M${x - 3.5} 85 l-1.2 -2.4` : `M${x + 5} 86.5 l2.5 -2 M${x + 3.5} 85 l1.2 -2.4`}" stroke="${D}" stroke-width="1.3" stroke-linecap="round"/>` : ""}`,
    `<ellipse cx="${x}" cy="91" rx="5.2" ry="2.6" fill="${D}"/><path d="M${x - 7} 88 q7 -3 14 0" stroke="${dk(skin,.65)}" stroke-width="1.6" fill="none"/>`,
    `<ellipse cx="${x}" cy="90.5" rx="4.6" ry="4.2" fill="${D}"/><path d="M${x - 6} 88.6 q6 -3 12 0 l0 -4 h-12z" fill="${skin}"/><path d="M${x - 6} 88.6 q6 -3 12 0" stroke="${D}" stroke-width="1.8" fill="none"/>`][n];
  let s = one(L) + one(R);
  if (e === "tired") s += `<path d="M${L - 7} 87 q7 -4 14 0 M${R - 7} 87 q7 -4 14 0" stroke="${skin}" stroke-width="5" fill="none"/><path d="M${L - 6} 88.5 q6 -3 12 0 M${R - 6} 88.5 q6 -3 12 0" stroke="#3a2418" stroke-width="1.6" fill="none"/>`;
  if (o) s += `<path d="M${L - 13} 92 l-5 -2 M${L - 13} 96 l-5 1 M${R + 13} 92 l5 -2 M${R + 13} 96 l5 1" stroke="${dk(skin,.72)}" stroke-width="1.4"/><path d="M84 63 q16 -4 32 0 M88 68 q12 -3 24 0" stroke="${dk(skin,.78)}" stroke-width="1.4" fill="none"/><path d="M84 117 q-6 -4 -6 -10 M116 117 q6 -4 6 -10" stroke="${dk(skin,.75)}" stroke-width="1.3" fill="none"/>`;
  return s;
}
function brows(n, sp, c){
  // 填色的眉毛：靠鼻子那头粗、外头细，弧度和粗细五种，都是放松的样子（不皱眉、不挑眉）
  const [ar, t] = [[5, 3.4], [3, 4], [6.5, 2.7], [4.5, 4.4], [5.5, 3.8]][n];
  const one = (x, k) => { const o = x - 9 * k, i = x + 8 * k, m = x - 1 * k;
    return `M${o} 78.5 Q${m} ${76 - ar} ${i} 76.5 L${i} ${76.5 + t} Q${m} ${77.5 - ar + t * .9} ${o} ${79.5}Z`; };
  return `<path d="${one(100 - sp, 1)} ${one(100 + sp, -1)}" fill="${c}" stroke="${c}" stroke-width=".8" stroke-linejoin="round"/>`;
}

