const cache = {};
window.PFACE = function(p, cls){
  if (!p.face) return `<span class="${cls || ""}">${p.av}</span>`;
  const k = p.nm + JSON.stringify(p.face);
  if (!cache[k]) cache[k] = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svg(Object.assign({nm: p.nm + (p.job || "")}, p.face)));
  return `<img class="${cls || ""}" src="${cache[k]}" alt="${p.nm}">`;
};
window.PFACE_URL = function(p){ window.PFACE(p); return cache[p.nm + JSON.stringify(p.face)]; };
