  $("#suLines").innerHTML = L.lines.map((l, i) => `<div class="su-ln${l.punch ? " punch" : ""}" data-i="${i}" data-s="${l.t0}" data-e="${l.t1}"><div class="su-en">${l.w.map(w => `<span class="su-wd" data-s="${w[1]}" data-e="${w[2]}">${esc(w[0])}</span>`).join(" ")}</div><div class="su-zh">${esc(l.zh)}</div></div>`).join("");
  root.querySelectorAll(".su-ln").forEach(el => el.onclick = () => { const l = L.lines[+el.dataset.i]; seg(l.t0, l.t1); });
